const PIPELINE_SAVE_COMPONENT_IDS = ['px-importer', 'px-preprocessor', 'px-modeling'];

const AppDataContext = createContext(null);

export function AppDataProvider({ userName, children }) {
  const [components, setComponents] = useState(INITIAL_COMPONENTS);
  const [pipelines, setPipelines] = useState(INITIAL_PIPELINES);
  const showToast = useToast();

  // Keyed by node id. Lives here (not in PipelineEditorPage's local state) so a
  // notebook's real Window reference survives PipelineEditorPage remounting -
  // e.g. toggling edit/view mode or navigating away and back - which a
  // component-local useRef would otherwise reset, leaving the "notebook open"
  // (blue) icon with no live window to focus.
  const notebookWindowsRef = useRef({});
  const notebookPollRef = useRef({});

  useEffect(() => {
    function handleGlobalNotebookMessage(event) {
      if (event.origin !== window.location.origin) return;
      if (event.data?.type !== 'px-pipeline-save') return;

      const bumped = {};
      components.forEach(c => {
        if (!PIPELINE_SAVE_COMPONENT_IDS.includes(c.id)) return;
        const latest = c.versions[0];
        bumped[c.id] = { ...latest, version: bumpVersion(latest.version), updatedBy: userName, updated: 'Just now', usedIn: 0 };
      });

      setComponents(prev => prev.map(c => (bumped[c.id] ? { ...c, versions: [bumped[c.id], ...c.versions] } : c)));

      setPipelines(prev => [
        {
          id: generateId(),
          name: 'Testing new pipeline',
          description: '',
          type: 'AI',
          created: 'Just now',
          updated: 'Just now',
          canvasNodes: [
            { id: generateId(), name: 'Importer', version: bumped['px-importer']?.version, createdAt: 'Just now', updatedAt: 'Just now', computeProfile: bumped['px-importer']?.computeProfile },
            { id: generateId(), name: 'Preprocessor', version: bumped['px-preprocessor']?.version, createdAt: 'Just now', updatedAt: 'Just now', computeProfile: bumped['px-preprocessor']?.computeProfile },
            { id: generateId(), name: 'Modeling', version: bumped['px-modeling']?.version, createdAt: 'Just now', updatedAt: 'Just now', computeProfile: bumped['px-modeling']?.computeProfile },
          ],
        },
        ...prev,
      ]);

      showToast({ variant: 'success', message: 'Pipeline "Testing new pipeline" created' });
    }
    window.addEventListener('message', handleGlobalNotebookMessage);
    return () => window.removeEventListener('message', handleGlobalNotebookMessage);
  }, [components, userName, showToast]);

  return (
    <AppDataContext.Provider value={{ components, setComponents, pipelines, setPipelines, notebookWindowsRef, notebookPollRef }}>
      {children}
    </AppDataContext.Provider>
  );
}

export function useAppData() {
  const ctx = useContext(AppDataContext);
  if (!ctx) throw new Error('useAppData must be used within an AppDataProvider');
  return ctx;
}
