import { useState } from 'react';
import { X } from 'lucide-react';
import './ConfirmDeleteModal.css';
import './NewPipelineModal.css';

export default function NewPipelineModal({ onCancel, onCreate }) {
  const [name, setName] = useState('');
  const [description, setDescription] = useState('');

  function handleCreate() {
    if (!name.trim()) return;
    onCreate({ name: name.trim(), description: description.trim() });
  }

  return (
    <div className="px-modal-overlay" onClick={onCancel}>
      <div className="px-modal px-modal--form" onClick={e => e.stopPropagation()}>
        <button type="button" className="px-modal__close" aria-label="Close" onClick={onCancel}>
          <X size={18} />
        </button>
        <h2 className="px-modal__title">New pipeline</h2>
        <p className="px-modal__subtitle">Provide a pipeline name and description.</p>

        <div className="px-field">
          <label className="px-field__label" htmlFor="new-pipeline-name">
            Pipeline Name <span className="px-field__required">*</span>
          </label>
          <input
            id="new-pipeline-name"
            type="text"
            className="px-field__input"
            placeholder="Enter a pipeline name"
            value={name}
            onChange={e => setName(e.target.value)}
            autoFocus
          />
        </div>

        <div className="px-field">
          <label className="px-field__label" htmlFor="new-pipeline-description">Description</label>
          <textarea
            id="new-pipeline-description"
            className="px-field__textarea"
            placeholder="Enter a description"
            value={description}
            onChange={e => setDescription(e.target.value)}
          />
        </div>

        <div className="px-modal__actions">
          <button type="button" className="px-modal__btn px-modal__btn--cancel" onClick={onCancel}>
            Cancel
          </button>
          <button
            type="button"
            className="px-modal__btn px-modal__btn--primary"
            disabled={!name.trim()}
            onClick={handleCreate}
          >
            Create pipeline
          </button>
        </div>
      </div>
    </div>
  );
}
