import React, { useState, useRef, useEffect } from "react";
import { Tag, X } from "lucide-react";

function Field({ label, value, onChange, placeholder, mono }) {
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
      <label style={{
        fontSize: 11, fontWeight: 600, letterSpacing: "0.08em",
        textTransform: "uppercase", color: "rgba(170,171,177,0.55)",
      }}>
        {label}
      </label>
      <input
        value={value}
        onChange={e => onChange(e.target.value)}
        placeholder={placeholder}
        style={{
          background: "#13161c", border: "1px solid #2e3035", borderRadius: 7,
          color: "#fff", fontSize: 13, padding: "8px 12px", outline: "none",
          fontFamily: mono ? "'Geist Mono', monospace" : "inherit",
          transition: "border-color 0.15s",
          width: "100%", boxSizing: "border-box",
        }}
        onFocus={e  => e.target.style.borderColor = "rgba(99,102,241,0.6)"}
        onBlur={e   => e.target.style.borderColor = "#2e3035"}
      />
    </div>
  );
}

function TagsField({ tags, onChange }) {
  const [input, setInput] = useState("");
  const inputRef = useRef(null);

  function addTag(raw) {
    const t = raw.trim().replace(/,+$/, "");
    if (!t || tags.includes(t)) return;
    onChange([...tags, t]);
  }

  function handleKey(e) {
    if (e.key === "Enter" || e.key === ",") {
      e.preventDefault();
      addTag(input);
      setInput("");
    } else if (e.key === "Backspace" && input === "" && tags.length > 0) {
      onChange(tags.slice(0, -1));
    }
  }

  function removeTag(i) {
    onChange(tags.filter((_, idx) => idx !== i));
  }

  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
      <label style={{
        fontSize: 11, fontWeight: 600, letterSpacing: "0.08em",
        textTransform: "uppercase", color: "rgba(170,171,177,0.55)",
      }}>
        Tags
      </label>
      <div
        onClick={() => inputRef.current?.focus()}
        style={{
          display: "flex", flexWrap: "wrap", alignItems: "center", gap: 6,
          background: "#13161c", border: "1px solid #2e3035", borderRadius: 7,
          padding: "7px 10px", cursor: "text", minHeight: 38,
        }}
      >
        {tags.map((t, i) => (
          <span key={i} style={{
            display: "inline-flex", alignItems: "center", gap: 4,
            background: "rgba(99,102,241,0.15)", border: "1px solid rgba(99,102,241,0.3)",
            borderRadius: 5, padding: "2px 8px",
            fontSize: 12, fontFamily: "monospace", color: "#a5b4fc",
          }}>
            {t}
            <button
              onClick={e => { e.stopPropagation(); removeTag(i); }}
              style={{ background: "none", border: "none", cursor: "pointer", padding: 0, display: "flex", color: "rgba(165,180,252,0.6)", lineHeight: 1 }}
            >
              <X size={10} />
            </button>
          </span>
        ))}
        <input
          ref={inputRef}
          value={input}
          onChange={e => setInput(e.target.value)}
          onKeyDown={handleKey}
          onBlur={() => { if (input.trim()) { addTag(input); setInput(""); } }}
          placeholder={tags.length === 0 ? "gnn, winglet, v3 …" : ""}
          style={{
            background: "none", border: "none", outline: "none",
            color: "#fff", fontSize: 13, padding: "1px 2px",
            fontFamily: "monospace", flexGrow: 1, minWidth: 80,
          }}
        />
      </div>
      <span style={{ fontSize: 11, color: "rgba(170,171,177,0.35)" }}>
        Press Enter or comma to add a tag
      </span>
    </div>
  );
}

export default function RegisterModelModal({ onClose, onSaveAsPipeline, onNotNow }) {
  const [name,           setName]           = useState("winglet-gnn-v3");
  const [version,        setVersion]        = useState("1.0.0");
  const [tags,           setTags]           = useState(["gnn", "winglet", "aerodynamics"]);
  const [pipelineChoice, setPipelineChoice] = useState(null); // null | 'save' | 'skip'

  // Close on Escape
  useEffect(() => {
    function onKey(e) { if (e.key === "Escape") onClose?.(); }
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);

  return (
    <div
      style={{
        position: "fixed", inset: 0, zIndex: 2000,
        background: "rgba(0,0,0,0.65)", backdropFilter: "blur(3px)",
        display: "flex", alignItems: "center", justifyContent: "center",
      }}
      onClick={e => { if (e.target === e.currentTarget) onClose?.(); }}
    >
      <div style={{
        width: 460, background: "#16191f",
        border: "1px solid #2e3035", borderRadius: 14,
        boxShadow: "0 24px 80px rgba(0,0,0,0.6)",
        display: "flex", flexDirection: "column", overflow: "hidden",
      }}>

        {/* ── Header ── */}
        <div style={{
          display: "flex", alignItems: "center", justifyContent: "space-between",
          padding: "18px 20px 14px", borderBottom: "1px solid #2e3035",
        }}>
          <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
            <div style={{
              width: 30, height: 30, borderRadius: 7,
              background: "rgba(99,102,241,0.15)", border: "1px solid rgba(99,102,241,0.25)",
              display: "flex", alignItems: "center", justifyContent: "center",
            }}>
              <Tag size={14} style={{ color: "#a5b4fc" }} />
            </div>
            <div>
              <div style={{ fontSize: 15, fontWeight: 700, color: "#fff" }}>Register model</div>
              <div style={{ fontSize: 11, color: "rgba(170,171,177,0.45)", fontFamily: "monospace", marginTop: 1 }}>
                Evaluation · Status: PASS
              </div>
            </div>
          </div>
          <button
            onClick={onClose}
            style={{ background: "none", border: "none", cursor: "pointer", color: "rgba(170,171,177,0.5)", padding: 4, display: "flex" }}
            onMouseEnter={e => e.currentTarget.style.color = "#fff"}
            onMouseLeave={e => e.currentTarget.style.color = "rgba(170,171,177,0.5)"}
          >
            <X size={16} />
          </button>
        </div>

        {/* ── Body ── */}
        <div style={{ padding: "20px", display: "flex", flexDirection: "column", gap: 16 }}>

          <Field label="Name"    value={name}    onChange={setName}    placeholder="e.g. winglet-gnn-v3" />
          <Field label="Version" value={version} onChange={setVersion} placeholder="e.g. 1.0.0" mono />
          <TagsField tags={tags} onChange={setTags} />

          {/* ── Pipeline prompt ── */}
          <div style={{
            background: "#0e1014", border: "1px solid #2e3035", borderRadius: 9,
            padding: "14px 16px", marginTop: 4,
          }}>
            <p style={{
              fontSize: 13, color: "rgba(255,255,255,0.7)", lineHeight: 1.6,
              margin: "0 0 14px 0",
            }}>
              Your workbook contains the steps that produced this model.
              <br />
              Would you like to save them as a reusable training pipeline?
            </p>
            <div style={{ display: "flex", gap: 8 }}>
              {/* Save as pipeline — selection button */}
              <button
                onClick={() => setPipelineChoice(c => c === 'save' ? null : 'save')}
                style={{
                  flex: 1,
                  background: pipelineChoice === 'save' ? "rgba(99,102,241,0.22)" : "rgba(99,102,241,0.07)",
                  border: `1px solid ${pipelineChoice === 'save' ? "rgba(99,102,241,0.7)" : "rgba(99,102,241,0.25)"}`,
                  borderRadius: 7,
                  color: pipelineChoice === 'save' ? "#c4b5fd" : "rgba(165,180,252,0.6)",
                  fontSize: 13, fontWeight: 600,
                  padding: "8px 14px", cursor: "pointer",
                  transition: "background 0.15s, border-color 0.15s, color 0.15s",
                  display: "flex", alignItems: "center", justifyContent: "center", gap: 6,
                }}
              >
                {pipelineChoice === 'save' && (
                  <svg width="12" height="12" viewBox="0 0 12 12" fill="none">
                    <path d="M2 6.5L4.5 9L10 3" stroke="#a5b4fc" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/>
                  </svg>
                )}
                Save as pipeline
              </button>
              {/* Not now — selection button */}
              <button
                onClick={() => setPipelineChoice(c => c === 'skip' ? null : 'skip')}
                style={{
                  flex: 1,
                  background: pipelineChoice === 'skip' ? "rgba(255,255,255,0.07)" : "#1a1d23",
                  border: `1px solid ${pipelineChoice === 'skip' ? "rgba(255,255,255,0.35)" : "#2e3035"}`,
                  borderRadius: 7,
                  color: pipelineChoice === 'skip' ? "rgba(255,255,255,0.85)" : "rgba(255,255,255,0.45)",
                  fontSize: 13,
                  padding: "8px 14px", cursor: "pointer",
                  transition: "border-color 0.15s, color 0.15s, background 0.15s",
                  display: "flex", alignItems: "center", justifyContent: "center", gap: 6,
                }}
              >
                {pipelineChoice === 'skip' && (
                  <svg width="12" height="12" viewBox="0 0 12 12" fill="none">
                    <path d="M2 6.5L4.5 9L10 3" stroke="rgba(255,255,255,0.7)" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/>
                  </svg>
                )}
                Not now
              </button>
            </div>
          </div>

        </div>

        {/* ── Footer ── */}
        <div style={{
          padding: "12px 20px 16px", borderTop: "1px solid #2e3035",
          display: "flex", justifyContent: "flex-end",
        }}>
          <button
            onClick={() => {
              if (pipelineChoice === 'save') onSaveAsPipeline?.({ name, version, tags });
              else onNotNow?.({ name, version, tags });
              onClose?.();
            }}
            style={{
              background: "#3b82f6", border: "none", borderRadius: 8,
              color: "#fff", fontSize: 13, fontWeight: 600,
              padding: "8px 22px", cursor: "pointer",
              transition: "background 0.15s",
            }}
            onMouseEnter={e => e.currentTarget.style.background = "#2563eb"}
            onMouseLeave={e => e.currentTarget.style.background = "#3b82f6"}
          >
            Register →
          </button>
        </div>

      </div>
    </div>
  );
}
