import React, { useState, useMemo } from "react";
import {
  Lock, Unlock, RotateCcw, Copy, Check, ChevronDown, ChevronRight,
  CheckCircle2, AlertTriangle, Wind, Cpu, SlidersHorizontal, BarChart2
} from "lucide-react";

// ─── Constants ────────────────────────────────────────────────────────────────
const OUTLET_TYPES     = ["pressure outlet", "far-field", "outflow"];
const PRESSURE_OPTS    = ["ambient", "specified"];
const WALL_TYPES       = ["no-slip wall", "slip wall", "moving wall"];
const WALL_TREATMENTS  = ["low-Re", "wall functions", "automatic"];
const TURB_MODELS      = ["k-ω SST", "k-ε realizable", "Spalart-Allmaras", "LES"];
const FLOW_REGIMES     = ["compressible", "incompressible"];
const FLUIDS           = ["air", "air (ideal gas)", "custom"];
const NUM_SCHEMES      = ["second order upwind", "first order upwind", "QUICK", "central differencing"];
const MESH_FACES       = ["winglet_skin", "wake_region", "far_field", "root_attachment", "symmetry_plane", "inlet_face", "outlet_face"];

const DEFAULTS = {
  // Inlet
  mach:     0.85,
  altitude: 11000,
  aoa:      2.0,
  density:  0.364,
  // Outlet
  outlet_type:     "pressure outlet",
  outlet_pressure: "ambient",
  // Winglet surface
  wall_type:      "no-slip wall",
  wall_treatment: "low-Re",
  // Region assignments
  regions: {
    inlet:          "inlet_face",
    outlet:         "outlet_face",
    winglet_surface: "winglet_skin",
    symmetry:       "symmetry_plane",
  },
  // Physics
  turb_model:  "k-ω SST",
  flow_regime: "compressible",
  fluid:       "air",
  // Solver
  conv_tol:    1e-6,
  max_iter:    2000,
  relax_p:     0.3,
  relax_v:     0.7,
  relax_t:     0.5,
  num_scheme:  "second order upwind",
  check_every: 50,
  // Outputs
  outputs: { Cd: true, Cl: true, LD: true },
};

// ─── Serialisers ─────────────────────────────────────────────────────────────
function toYAML(cfg) {
  return `# CFD Solver Configuration
# Generated by Flux Pipelines — ${new Date().toISOString().slice(0, 10)}

boundary_conditions:
  inlet:
    mach_number:     ${cfg.mach}
    altitude_m:      ${cfg.altitude}
    angle_of_attack: ${cfg.aoa}
    air_density:     ${cfg.density}
  outlet:
    type:     ${cfg.outlet_type}
    pressure: ${cfg.outlet_pressure}
  winglet_surface:
    type:           ${cfg.wall_type}
    wall_treatment: ${cfg.wall_treatment}
  symmetry_plane:
    type: symmetry
  region_assignments:
    inlet:           ${cfg.regions.inlet}
    outlet:          ${cfg.regions.outlet}
    winglet_surface: ${cfg.regions.winglet_surface}
    symmetry:        ${cfg.regions.symmetry}

physics:
  turbulence_model: ${cfg.turb_model}
  flow_regime:      ${cfg.flow_regime}
  fluid:            ${cfg.fluid}

solver:
  convergence_tolerance: ${cfg.conv_tol}
  max_iterations:        ${cfg.max_iter}
  relaxation:
    pressure:   ${cfg.relax_p}
    velocity:   ${cfg.relax_v}
    turbulence: ${cfg.relax_t}
  numerical_scheme: ${cfg.num_scheme}
  check_every:      ${cfg.check_every}

outputs:
  Cd:  ${cfg.outputs.Cd}
  Cl:  ${cfg.outputs.Cl}
  L_D: ${cfg.outputs.LD}
`;
}

function toAPIJson(cfg) {
  return JSON.stringify({
    boundary_conditions: {
      inlet: { mach: cfg.mach, altitude_m: cfg.altitude, aoa_deg: cfg.aoa, density_kg_m3: cfg.density },
      outlet: { type: cfg.outlet_type, pressure: cfg.outlet_pressure },
      winglet_surface: { type: cfg.wall_type, wall_treatment: cfg.wall_treatment },
      symmetry_plane: { type: "symmetry" },
      region_assignments: cfg.regions,
    },
    physics: { turbulence_model: cfg.turb_model, flow_regime: cfg.flow_regime, fluid: cfg.fluid },
    solver: {
      convergence_tolerance: cfg.conv_tol, max_iterations: cfg.max_iter,
      relaxation: { pressure: cfg.relax_p, velocity: cfg.relax_v, turbulence: cfg.relax_t },
      numerical_scheme: cfg.num_scheme, check_every: cfg.check_every,
    },
    outputs: Object.entries(cfg.outputs).filter(([,v]) => v).map(([k]) => k),
  }, null, 2);
}

// ─── Sub-components ───────────────────────────────────────────────────────────
function SectionHeader({ icon: Icon, label }) {
  return (
    <div className="flex items-center gap-2 mb-3">
      <Icon size={13} className="text-[#aaabb1] shrink-0" />
      <span className="text-[11px] font-semibold uppercase tracking-widest text-[#aaabb1] opacity-60">
        {label}
      </span>
    </div>
  );
}

function Field({ label, hint, children, tight }) {
  return (
    <div className={tight ? "mb-2" : "mb-3"}>
      <div className="flex items-baseline justify-between mb-1">
        <label className="text-[11px] text-[#aaabb1]">{label}</label>
        {hint && <span className="text-[10px] text-[#aaabb1] opacity-40">{hint}</span>}
      </div>
      {children}
    </div>
  );
}

function NumInput({ value, onChange, min, max, step, disabled, suffix, sci }) {
  const display = sci ? value.toExponential() : value;
  return (
    <div className="flex items-center gap-1.5">
      <input type={sci ? "text" : "number"} value={display}
        min={min} max={max} step={step} disabled={disabled}
        onChange={e => {
          const n = sci ? parseFloat(e.target.value) : parseFloat(e.target.value);
          if (!isNaN(n)) onChange(n);
        }}
        className="w-full bg-[#1d2024] border border-[#2e3035] rounded px-2.5 py-1.5 text-[12px] text-white
          focus:outline-none focus:border-[#aaabb1]/40 disabled:opacity-40 disabled:cursor-not-allowed
          [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none
          [&::-webkit-inner-spin-button]:appearance-none transition-colors font-mono" />
      {suffix && <span className="text-[11px] text-[#aaabb1] opacity-40 shrink-0 font-mono">{suffix}</span>}
    </div>
  );
}

function Select({ value, options, onChange, disabled }) {
  const [open, setOpen] = useState(false);
  return (
    <div className="relative">
      <button onClick={() => !disabled && setOpen(v => !v)} disabled={disabled}
        className="w-full flex items-center justify-between bg-[#1d2024] border border-[#2e3035]
          rounded px-2.5 py-1.5 text-[12px] text-white hover:border-[#aaabb1]/40
          disabled:opacity-40 disabled:cursor-not-allowed transition-colors">
        <span className="capitalize">{value}</span>
        <ChevronDown size={12} className={`text-[#aaabb1] transition-transform shrink-0 ${open ? "rotate-180" : ""}`} />
      </button>
      {open && (
        <div className="absolute z-50 top-full left-0 right-0 mt-1 bg-[#1d2024] border border-[#2e3035]
          rounded shadow-xl overflow-hidden">
          {options.map(opt => (
            <button key={opt} onClick={() => { onChange(opt); setOpen(false); }}
              className={`w-full text-left px-3 py-2 text-[12px] capitalize hover:bg-[#2e3035] transition-colors
                ${value === opt ? "text-white" : "text-[#aaabb1]"}`}>
              {opt}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

function Pills({ value, options, onChange, disabled }) {
  return (
    <div className="flex gap-1.5 flex-wrap">
      {options.map(opt => (
        <button key={opt} disabled={disabled} onClick={() => !disabled && onChange(opt)}
          className={`px-2.5 py-1 rounded border text-[11px] capitalize transition-all
            disabled:opacity-40 disabled:cursor-not-allowed
            ${value === opt
              ? "border-[#aaabb1]/40 bg-[#2e3035] text-white"
              : "border-[#2e3035] text-[#aaabb1] hover:border-[#aaabb1]/30 hover:text-white"}`}>
          {opt}
        </button>
      ))}
    </div>
  );
}

// Collapsible BC subsection
function BCSection({ label, defaultOpen = true, children }) {
  const [open, setOpen] = useState(defaultOpen);
  return (
    <div className="rounded border border-[#2e3035] overflow-hidden">
      <button onClick={() => setOpen(v => !v)}
        className="w-full flex items-center gap-2 px-3 py-2 bg-[#1d2024] hover:bg-[#2e3035] transition-colors text-left">
        {open
          ? <ChevronDown size={11} className="text-[#aaabb1] opacity-50 shrink-0" />
          : <ChevronRight size={11} className="text-[#aaabb1] opacity-50 shrink-0" />}
        <span className="text-[12px] font-medium text-white">{label}</span>
      </button>
      {open && <div className="px-3 pt-2 pb-3 bg-[#111318] space-y-2">{children}</div>}
    </div>
  );
}

// Relax slider row
function RelaxRow({ label, value, onChange, disabled }) {
  return (
    <div className="flex items-center gap-3">
      <span className="text-[11px] text-[#aaabb1] w-20 shrink-0">{label}</span>
      <input type="range" min={0.05} max={1} step={0.05} value={value} disabled={disabled}
        onChange={e => onChange(parseFloat(e.target.value))}
        className="flex-1 h-1 appearance-none bg-[#2e3035] rounded cursor-pointer
          [&::-webkit-slider-thumb]:appearance-none [&::-webkit-slider-thumb]:w-3
          [&::-webkit-slider-thumb]:h-3 [&::-webkit-slider-thumb]:rounded-full
          [&::-webkit-slider-thumb]:bg-white disabled:opacity-40" />
      <span className="text-[12px] text-white font-mono w-8 text-right shrink-0">{value}</span>
    </div>
  );
}

// Output toggle row
function OutputRow({ id, label, desc, value, onChange, disabled, derived }) {
  return (
    <button disabled={disabled || derived} onClick={() => !(disabled || derived) && onChange(!value)}
      className="flex items-start gap-3 w-full text-left py-2 border-b border-[#2e3035]/60 last:border-0
        disabled:cursor-not-allowed group">
      <div className={`mt-0.5 w-3 h-3 rounded-sm border flex items-center justify-center shrink-0 transition-colors
        ${value ? "border-[#aaabb1]/50 bg-[#2e3035]" : "border-[#2e3035]"}
        ${derived ? "opacity-50" : ""}`}>
        {value && (
          <svg width="7" height="5" viewBox="0 0 7 5" fill="none">
            <path d="M1 2.5L2.5 4L6 1" stroke="white" strokeWidth="1.2" strokeLinecap="round" strokeLinejoin="round"/>
          </svg>
        )}
      </div>
      <div className="flex-1 min-w-0">
        <div className="flex items-center gap-2">
          <span className="text-[12px] font-mono text-white">{id}</span>
          {derived && <span className="text-[10px] text-[#aaabb1] opacity-40 border border-[#2e3035] rounded px-1">derived</span>}
        </div>
        <span className="text-[11px] text-[#aaabb1] opacity-50">{desc}</span>
      </div>
    </button>
  );
}

function CodeBlock({ code, lang }) {
  const [copied, setCopied] = useState(false);
  return (
    <div className="rounded border border-[#2e3035] bg-[#0c0e13] overflow-hidden">
      <div className="flex items-center justify-between px-3 py-1.5 border-b border-[#2e3035]">
        <span className="text-[10px] text-[#aaabb1] opacity-40 font-mono">{lang}</span>
        <button onClick={() => { navigator.clipboard.writeText(code); setCopied(true); setTimeout(() => setCopied(false), 1500); }}
          className="text-[#aaabb1] hover:text-white transition-colors">
          {copied ? <Check size={12} className="text-green-400" /> : <Copy size={12} />}
        </button>
      </div>
      <pre className="p-3 text-[11px] font-mono text-[#aaabb1] overflow-x-auto whitespace-pre leading-relaxed">{code}</pre>
    </div>
  );
}

// ─── Main ─────────────────────────────────────────────────────────────────────
export default function CFDSolverConfig({ locked = false, onClose }) {
  const [cfg, setCfg]         = useState(DEFAULTS);
  const [isLocked, setLocked] = useState(locked);
  const [tab, setTab]         = useState("ui");

  const set    = (k, v) => { if (!isLocked) setCfg(p => ({ ...p, [k]: v })); };
  const setReg = (k, v) => { if (!isLocked) setCfg(p => ({ ...p, regions:  { ...p.regions,  [k]: v } })); };
  const setOut = (k, v) => { if (!isLocked) setCfg(p => ({ ...p, outputs:  { ...p.outputs,  [k]: v } })); };
  const reset  = ()     => { if (!isLocked) setCfg(DEFAULTS); };

  const yaml    = useMemo(() => toYAML(cfg),   [cfg]);
  const apiJson = useMemo(() => toAPIJson(cfg), [cfg]);

  return (
    <div className="flex flex-col h-full bg-[#111318] text-white overflow-hidden select-none">

      {/* Header */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-[#2e3035] shrink-0">
        <div className="flex items-center gap-2">
          <Wind size={14} className="text-[#aaabb1]" />
          <span className="text-[13px] font-semibold">CFD Solver</span>
          <span className="text-[10px] text-[#aaabb1] opacity-50 bg-[#1d2024] px-1.5 py-0.5 rounded border border-[#2e3035]">StarCCM+</span>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={reset} disabled={isLocked}
            className="text-[#aaabb1] hover:text-white disabled:opacity-30 transition-colors" title="Reset">
            <RotateCcw size={13} />
          </button>
          <button onClick={() => setLocked(v => !v)} className="text-[#aaabb1] hover:text-white transition-colors">
            {isLocked ? <Lock size={13} /> : <Unlock size={13} />}
          </button>
          {onClose && (
            <button onClick={onClose} className="text-[#aaabb1] hover:text-white transition-colors ml-1" title="Close">
              <svg width="13" height="13" viewBox="0 0 13 13" fill="none"><path d="M2 2L11 11M11 2L2 11" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round"/></svg>
            </button>
          )}
        </div>
      </div>

      {/* Tabs */}
      <div className="flex border-b border-[#2e3035] shrink-0">
        {["ui", "yaml"].map(t => (
          <button key={t} onClick={() => setTab(t)}
            className={`px-4 py-2 text-[11px] font-medium uppercase tracking-wider transition-colors border-b-2
              ${tab === t ? "border-white text-white" : "border-transparent text-[#aaabb1] hover:text-white"}`}>
            {t === "api" ? "API" : t.toUpperCase()}
          </button>
        ))}
      </div>

      {/* Body */}
      <div className="flex-1 overflow-y-auto px-4 py-4">
        {tab !== "ui" ? (
          <CodeBlock code={yaml} lang="yaml" />
        ) : (
          <div className="space-y-5">

            {/* ── Boundary conditions ── */}
            <div>
              <SectionHeader icon={Wind} label="Boundary Conditions" />
              <div className="flex flex-col gap-2">

                <BCSection label="Inlet">
                  <div className="grid grid-cols-2 gap-x-3 gap-y-2">
                    <Field label="Mach number" tight>
                      <NumInput value={cfg.mach} onChange={v => set("mach", v)} min={0} max={3} step={0.01} disabled={isLocked} />
                    </Field>
                    <Field label="Altitude" tight>
                      <NumInput value={cfg.altitude} onChange={v => set("altitude", v)} min={0} max={40000} step={100} suffix="m" disabled={isLocked} />
                    </Field>
                    <Field label="Angle of attack" tight>
                      <NumInput value={cfg.aoa} onChange={v => set("aoa", v)} min={-20} max={30} step={0.5} suffix="°" disabled={isLocked} />
                    </Field>
                    <Field label="Air density" tight>
                      <NumInput value={cfg.density} onChange={v => set("density", v)} min={0.01} max={1.5} step={0.001} suffix="kg/m³" disabled={isLocked} />
                    </Field>
                  </div>
                </BCSection>

                <BCSection label="Outlet" defaultOpen={false}>
                  <Field label="Type" tight>
                    <Select value={cfg.outlet_type} options={OUTLET_TYPES} onChange={v => set("outlet_type", v)} disabled={isLocked} />
                  </Field>
                  <Field label="Pressure" tight>
                    <Pills value={cfg.outlet_pressure} options={PRESSURE_OPTS} onChange={v => set("outlet_pressure", v)} disabled={isLocked} />
                  </Field>
                </BCSection>

                <BCSection label="Winglet surface" defaultOpen={false}>
                  <Field label="Type" tight>
                    <Select value={cfg.wall_type} options={WALL_TYPES} onChange={v => set("wall_type", v)} disabled={isLocked} />
                  </Field>
                  <Field label="Wall treatment" tight>
                    <Pills value={cfg.wall_treatment} options={WALL_TREATMENTS} onChange={v => set("wall_treatment", v)} disabled={isLocked} />
                  </Field>
                </BCSection>

                <BCSection label="Symmetry plane" defaultOpen={false}>
                  <div className="flex items-center gap-2 py-1">
                    <div className="w-2 h-2 rounded-full bg-[#2e3035]" />
                    <span className="text-[12px] text-[#aaabb1]">Type: symmetry</span>
                    <span className="text-[10px] text-[#aaabb1] opacity-40 ml-1">(fixed)</span>
                  </div>
                </BCSection>

                {/* Region assignments */}
                <div className="rounded border border-[#2e3035] overflow-hidden">
                  <div className="flex items-center gap-2 px-3 py-2 bg-[#1d2024]">
                    <span className="text-[12px] font-medium text-white">Region assignments</span>
                    <span className="text-[10px] text-[#aaabb1] opacity-40 ml-auto">mesh face → BC</span>
                  </div>
                  <div className="bg-[#111318] px-3 divide-y divide-[#2e3035]/50">
                    {[
                      { id: "inlet",           label: "Inlet" },
                      { id: "outlet",          label: "Outlet" },
                      { id: "winglet_surface", label: "Winglet surface" },
                      { id: "symmetry",        label: "Symmetry" },
                    ].map(({ id, label }) => (
                      <div key={id} className="flex items-center justify-between py-2 gap-3">
                        <span className="text-[12px] text-white shrink-0">{label}</span>
                        <div className="w-40">
                          <Select value={cfg.regions[id]} options={MESH_FACES}
                            onChange={v => setReg(id, v)} disabled={isLocked} />
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>

            <div className="border-t border-[#2e3035]" />

            {/* ── Physics ── */}
            <div>
              <SectionHeader icon={Cpu} label="Physics Model" />
              <div className="grid grid-cols-1 gap-3">
                <Field label="Turbulence model">
                  <Select value={cfg.turb_model} options={TURB_MODELS} onChange={v => set("turb_model", v)} disabled={isLocked} />
                </Field>
                <Field label="Flow regime">
                  <Pills value={cfg.flow_regime} options={FLOW_REGIMES} onChange={v => set("flow_regime", v)} disabled={isLocked} />
                </Field>
                <Field label="Fluid">
                  <Pills value={cfg.fluid} options={FLUIDS} onChange={v => set("fluid", v)} disabled={isLocked} />
                </Field>
              </div>
            </div>

            <div className="border-t border-[#2e3035]" />

            {/* ── Solver settings ── */}
            <div>
              <SectionHeader icon={SlidersHorizontal} label="Solver Settings" />

              <div className="grid grid-cols-2 gap-x-3">
                <Field label="Convergence tolerance">
                  <NumInput value={cfg.conv_tol} onChange={v => set("conv_tol", v)} sci disabled={isLocked} />
                </Field>
                <Field label="Max iterations">
                  <NumInput value={cfg.max_iter} onChange={v => set("max_iter", v)} min={100} max={50000} step={100} disabled={isLocked} />
                </Field>
              </div>

              <Field label="Relaxation factors">
                <div className="rounded border border-[#2e3035] bg-[#1d2024] px-3 py-2.5 flex flex-col gap-2.5">
                  <RelaxRow label="Pressure"   value={cfg.relax_p} onChange={v => set("relax_p", v)} disabled={isLocked} />
                  <RelaxRow label="Velocity"   value={cfg.relax_v} onChange={v => set("relax_v", v)} disabled={isLocked} />
                  <RelaxRow label="Turbulence" value={cfg.relax_t} onChange={v => set("relax_t", v)} disabled={isLocked} />
                </div>
              </Field>

              <Field label="Numerical scheme">
                <Select value={cfg.num_scheme} options={NUM_SCHEMES} onChange={v => set("num_scheme", v)} disabled={isLocked} />
              </Field>

              <Field label="Convergence check interval">
                <NumInput value={cfg.check_every} onChange={v => set("check_every", v)} min={1} max={500} step={10} suffix="iters" disabled={isLocked} />
              </Field>
            </div>

            <div className="border-t border-[#2e3035]" />

            {/* ── Scalar outputs ── */}
            <div>
              <SectionHeader icon={BarChart2} label="Scalar Outputs" />
              <div className="rounded border border-[#2e3035] bg-[#1d2024] px-3 divide-y divide-[#2e3035]/60">
                <OutputRow id="Cd" label="Drag coefficient"
                  desc="Integrated from winglet surface"
                  value={cfg.outputs.Cd} onChange={v => setOut("Cd", v)} disabled={isLocked} />
                <OutputRow id="Cl" label="Lift coefficient"
                  desc="Integrated from winglet surface"
                  value={cfg.outputs.Cl} onChange={v => setOut("Cl", v)} disabled={isLocked} />
                <OutputRow id="L/D" label="Lift-to-drag ratio"
                  desc="Derived from Cd and Cl"
                  value={cfg.outputs.LD} onChange={v => setOut("LD", v)} disabled={isLocked} derived />
              </div>
            </div>

            {/* Status */}
            <div className="flex items-center gap-2 text-[11px] text-[#aaabb1] opacity-40 pt-1">
              <CheckCircle2 size={11} className="text-green-400 opacity-100" />
              <span className="text-green-400 opacity-100">Ready to run</span>
            </div>

          </div>
        )}
      </div>
    </div>
  );
}
