const DEFAULT_VERSIONS = [
  { version: 'v0.3', label: 'v0.3', note: 'Latest',          date: '2024-11-01', tag: 'latest' },
  { version: 'v0.2', label: 'v0.2', note: 'Previous stable', date: '2024-09-12' },
  { version: 'v0.1', label: 'v0.1', note: 'Initial release', date: '2024-07-04', tag: 'legacy' },
];

function getVersions(name) {
  if (!name) return DEFAULT_VERSIONS;
  for (const key of Object.keys(COMPONENT_VERSIONS)) {
    if (name.toLowerCase().includes(key.toLowerCase())) return COMPONENT_VERSIONS[key];
  }
  return DEFAULT_VERSIONS;
}

/* ── VersionPicker dropdown ─────────────────────────────────────── */
function VersionPicker({ name, currentVersion, onSelect, align = 'left' }) {
  const [open, setOpen] = useState(false);
  const ref = useRef(null);
  const versions = getVersions(name);
  const active = versions.find(v => currentVersion?.includes(v.version)) || versions[0];

  useEffect(() => {
    if (!open) return;
    function handler(e) { if (ref.current && !ref.current.contains(e.target)) setOpen(false); }
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, [open]);

  return (
    <div className="ver-picker" ref={ref} style={{ position: 'relative' }}>
      <button
        className="ver-picker__trigger"
        onClick={e => { e.stopPropagation(); setOpen(o => !o); }}
      >
        <span>{active.version}</span>
        <svg width="10" height="10" viewBox="0 0 10 10" fill="none"
          style={{ transform: open ? 'rotate(180deg)' : 'none', transition: 'transform 0.15s', flexShrink: 0 }}>
          <path d="M2 3.5L5 6.5L8 3.5" stroke="currentColor" strokeWidth="1.1" strokeLinecap="round" strokeLinejoin="round"/>
        </svg>
      </button>

      {open && (
        <div className={`ver-picker__menu ver-picker__menu--${align}`} onClick={e => e.stopPropagation()}>
          <div className="ver-picker__header">Version history</div>
          {versions.map(v => (
            <button
              key={v.version}
              className={`ver-picker__item${v.version === active.version ? ' ver-picker__item--active' : ''}`}
              onClick={() => { onSelect?.(v); setOpen(false); }}
            >
              <div className="ver-picker__item-top">
                <span className="ver-picker__item-ver">{v.version}</span>
                {v.tag && (
                  <span className={`ver-picker__tag ver-picker__tag--${v.tag}`}>{v.tag}</span>
                )}
              </div>
              <div className="ver-picker__item-bot">
                <span className="ver-picker__item-note">{v.note}</span>
                <span className="ver-picker__item-date">{v.date}</span>
              </div>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

