const MESH_SURFACES = ['Wing surface', 'Fuselage structure', 'Tail assembly', 'Engine configuration', 'Landing gear design'];

function drawMeshOnCanvas(canvas) {
  if (!canvas) return;
  const rect = canvas.getBoundingClientRect();
  if (!rect.width) return;
  const dpr = window.devicePixelRatio || 1;
  canvas.width  = rect.width  * dpr;
  canvas.height = rect.height * dpr;
  const ctx = canvas.getContext('2d');
  ctx.scale(dpr, dpr);
  const W = rect.width, H = rect.height;

  ctx.fillStyle = '#000000';
  ctx.fillRect(0, 0, W, H);

  // Battery slab: 8 cols × 5 rows × 2 layers
  const COLS = 8, ROWS = 5, LAYERS = 2;
  // Computed centre — slab is left/bottom-heavy due to yaw perspective
  const cx = W * 0.62, cy = H * 0.40;

  // Spacing — each grid unit = this many pixels at the centre depth
  const SP = Math.min(W / 12.5, H / 10.0);

  // Very shallow pitch (looking slightly down) + moderate yaw = flat battery slab look
  const yaw   = 0.54;   // ~31° around Y
  const pitch = 0.20;   // ~11° pitch
  const [cY, sY] = [Math.cos(yaw),   Math.sin(yaw)];
  const [cP, sP] = [Math.cos(pitch), Math.sin(pitch)];

  function rotate(x, y, z) {
    const x1 =  x*cY + z*sY,  z1 = -x*sY + z*cY;
    const y2 =  y*cP - z1*sP, z2 =  y*sP + z1*cP;
    return [x1, y2, z2];
  }
  function project(x, y, z) {
    // Higher fov = less extreme perspective distortion
    const fov = 11.0, d = z + fov;
    const s = fov / Math.max(d, 0.4);
    return { px: cx + x*s*SP, py: cy + y*s*SP, depth: z, scale: s };
  }

  // Build projected grid
  const pts = [];
  for (let l = 0; l < LAYERS; l++)
    for (let r = 0; r < ROWS; r++)
      for (let c = 0; c < COLS; c++) {
        const [rx, ry, rz] = rotate(
          (c - (COLS-1)/2) * 1.10,
          (r - (ROWS-1)/2) * 1.00,
          (l - (LAYERS-1)/2) * 1.75
        );
        pts.push({ ...project(rx, ry, rz), c, r, l });
      }

  const get = (c,r,l) => pts.find(p => p.c===c && p.r===r && p.l===l);
  const onBound = (c,r) => c===0 || c===COLS-1 || r===0 || r===ROWS-1;

  // ── Edges ─────────────────────────────────────────────────────
  const edges = [];
  for (let l = 0; l < LAYERS; l++)
    for (let r = 0; r < ROWS; r++)
      for (let c = 0; c < COLS; c++) {
        const p = get(c,r,l);
        if (c < COLS-1) {
          const n = get(c+1,r,l);
          edges.push({ p, n, depth:(p.depth+n.depth)/2,
            frame: onBound(c,r) && onBound(c+1,r), dir:'h' });
        }
        if (r < ROWS-1) {
          const n = get(c,r+1,l);
          edges.push({ p, n, depth:(p.depth+n.depth)/2,
            frame: onBound(c,r) && onBound(c,r+1), dir:'v' });
        }
        if (l < LAYERS-1) {
          const n = get(c,r,l+1);
          edges.push({ p, n, depth:(p.depth+n.depth)/2,
            frame: onBound(c,r), dir:'d' });
        }
      }

  edges.sort((a,b) => a.depth - b.depth);

  // Pass 1 — interior edges only (drawn behind spheres)
  edges.forEach(({ p, n, frame, dir }) => {
    if (frame) return;
    ctx.beginPath(); ctx.moveTo(p.px, p.py); ctx.lineTo(n.px, n.py);
    const isDepth = dir === 'd';
    ctx.strokeStyle = isDepth ? 'rgba(54,26,158,0.85)' : 'rgba(46,22,140,0.68)';
    ctx.lineWidth = isDepth ? 3.0 : 2.0;
    ctx.stroke();
  });

  // ── Spheres (back → front) ─────────────────────────────────────
  // SR = 0.42 → spheres nearly touch without fully overlapping (cage visible)
  const SR = SP * 0.42;
  [...pts].sort((a,b) => a.depth - b.depth).forEach(({ px, py, scale }) => {
    const r = Math.max(SR * (scale || 1), 7);

    // Soft green glow — kept tight so gaps between spheres stay dark
    const glow = ctx.createRadialGradient(px, py, r*0.5, px, py, r*1.55);
    glow.addColorStop(0,   'rgba(100,210,80,0.14)');
    glow.addColorStop(0.6, 'rgba(50,160,60,0.05)');
    glow.addColorStop(1,   'rgba(0,0,0,0)');
    ctx.fillStyle = glow;
    ctx.beginPath(); ctx.arc(px, py, r*1.55, 0, Math.PI*2); ctx.fill();

    // Sphere: bright yellow-green center → green → dark teal rim
    const g = ctx.createRadialGradient(px-r*0.12, py-r*0.12, r*0.02, px, py, r);
    g.addColorStop(0,    '#e4f418');   // bright yellow-green core
    g.addColorStop(0.14, '#b8e010');   // yellow-green
    g.addColorStop(0.32, '#5ec050');   // green
    g.addColorStop(0.58, '#2a9e7a');   // green-teal
    g.addColorStop(0.80, '#1a6878');   // dark teal
    g.addColorStop(1,    '#0e3845');   // deep blue-teal rim
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.arc(px, py, r, 0, Math.PI*2); ctx.fill();
  });

  // Pass 2 — outer frame cage drawn ON TOP of spheres so it's always visible
  edges.forEach(({ p, n, frame }) => {
    if (!frame) return;
    ctx.beginPath(); ctx.moveTo(p.px, p.py); ctx.lineTo(n.px, n.py);
    ctx.strokeStyle = 'rgba(65,32,178,0.96)';
    ctx.lineWidth = 4.5;
    ctx.stroke();
  });

  // ── Corner rings (on top) ──────────────────────────────────────
  [[0,0,0],[COLS-1,0,0],[0,ROWS-1,0],[COLS-1,ROWS-1,0],
   [0,0,LAYERS-1],[COLS-1,0,LAYERS-1],[0,ROWS-1,LAYERS-1],[COLS-1,ROWS-1,LAYERS-1]]
    .forEach(([c,r,l]) => {
      const p = get(c,r,l);
      if (!p) return;
      ctx.beginPath();
      ctx.arc(p.px, p.py, Math.max(10 * (p.scale || 0.8), 6), 0, Math.PI*2);
      ctx.strokeStyle = 'rgba(72,38,188,0.92)';
      ctx.lineWidth = 2.5;
      ctx.stroke();
    });

  // ── Axes ──────────────────────────────────────────────────────
  const aox = 50, aoy = H - 48, AL = 32;
  [[AL,0,'#ef4444','x'],[0,-AL,'#22c55e','y'],[AL*.55,-AL*.55,'#3b82f6','z']]
    .forEach(([dx,dy,col,lbl]) => {
      ctx.strokeStyle = col; ctx.lineWidth = 2;
      ctx.beginPath(); ctx.moveTo(aox,aoy); ctx.lineTo(aox+dx,aoy+dy); ctx.stroke();
      ctx.fillStyle = col; ctx.font = '11px sans-serif';
      ctx.fillText(lbl, aox+dx+(dx>0?5:-12), aoy+dy+(dy<0?-5:14));
    });
}

