function TerminalLine({ entry }) {
  if (entry.type === 'prompt') {
    return (
      <div className="term-line">
        <span className="term-py">{PY}</span>
        <span className="term-host">{HOST}</span>
        <span className="term-sep">:</span>
        <span className="term-cwd">{CWD}</span>
        <span className="term-dollar">$</span>
        <span className="term-cmd"> {entry.text}</span>
      </div>
    );
  }
  const cls = {
    warn: 'term-line term-line--warn',
    url:  'term-line term-line--url',
    ok:   'term-line term-line--ok',
    err:  'term-line term-line--err',
    dim:  'term-line term-line--dim',
  }[entry.type] || 'term-line term-line--dim';
  return <div className={cls}>{entry.text}</div>;
}

function TerminalPanel({ jobs }) {
  const [activeTab,    setActiveTab]    = useState('TERMINAL');
  const [activeSession, setActiveSession] = useState(2);
  const [log, setLog] = useState(() => {
    // Flatten initial log into a list of line entries
    const lines = [];
    INITIAL_TERMINAL_LOG.forEach(entry => {
      lines.push({ type: 'prompt', text: entry.cmd });
      entry.lines.forEach(l => lines.push(l));
      lines.push({ type: 'spacer' });
    });
    return lines;
  });
  const [input, setInput] = useState('');
  const [histIdx, setHistIdx] = useState(-1);
  const history = useRef(INITIAL_TERMINAL_LOG.map(e => e.cmd));
  const scrollRef = useRef(null);
  const inputRef  = useRef(null);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [log]);

  function handleKeyDown(e) {
    if (e.key === 'Enter') {
      const cmd = input.trim();
      setInput('');
      setHistIdx(-1);
      if (!cmd) return;
      history.current = [cmd, ...history.current];
      const newLines = [{ type: 'prompt', text: cmd }];
      const resp = TERM_MOCK_RESPONSES[cmd] || TERM_MOCK_RESPONSES.default(cmd);
      if (resp.clear) { setLog([]); return; }
      (resp.lines || []).forEach(l => newLines.push(l));
      newLines.push({ type: 'spacer' });
      setLog(prev => [...prev, ...newLines]);
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      const next = Math.min(histIdx + 1, history.current.length - 1);
      setHistIdx(next);
      setInput(history.current[next] || '');
    } else if (e.key === 'ArrowDown') {
      e.preventDefault();
      const next = Math.max(histIdx - 1, -1);
      setHistIdx(next);
      setInput(next === -1 ? '' : history.current[next] || '');
    }
  }

  const problemCount = 0;

  return (
    <div className="term-panel" onClick={() => inputRef.current?.focus()}>

      {/* ── Tab bar ── */}
      <div className="term-tabbar">
        <div className="term-tabs">
          {TERM_TABS.map(t => (
            <button
              key={t}
              className={`term-tab${activeTab === t ? ' term-tab--active' : ''}`}
              onClick={e => { e.stopPropagation(); setActiveTab(t); }}
            >
              {t}
              {t === 'PROBLEMS' && problemCount > 0 && (
                <span className="term-tab__badge">{problemCount}</span>
              )}
            </button>
          ))}
        </div>
        <div style={{ flex: 1 }} />
        {/* Terminal controls */}
        <div className="term-controls">
          <button className="term-ctrl-btn" title="New terminal" onClick={e => e.stopPropagation()}>
            <svg width="13" height="13" viewBox="0 0 13 13" fill="none">
              <path d="M6.5 2v9M2 6.5h9" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round"/>
            </svg>
          </button>
          <button className="term-ctrl-btn" title="Split terminal" onClick={e => e.stopPropagation()}>
            <svg width="13" height="13" viewBox="0 0 13 13" fill="none">
              <rect x="1" y="1" width="11" height="11" rx="1.5" stroke="currentColor" strokeWidth="1.1"/>
              <line x1="6.5" y1="1" x2="6.5" y2="12" stroke="currentColor" strokeWidth="1.1"/>
            </svg>
          </button>
          <button className="term-ctrl-btn" title="Clear" onClick={e => { e.stopPropagation(); setLog([]); }}>
            <svg width="13" height="13" viewBox="0 0 13 13" fill="none">
              <path d="M2 10L5 4M8 4L11 10M3.5 7.5h6" stroke="currentColor" strokeWidth="1.1" strokeLinecap="round" strokeLinejoin="round"/>
            </svg>
          </button>
          <button className="term-ctrl-btn term-ctrl-btn--close" title="Close" onClick={e => e.stopPropagation()}>
            <svg width="11" height="11" viewBox="0 0 11 11" fill="none">
              <path d="M2 2L9 9M9 2L2 9" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round"/>
            </svg>
          </button>
        </div>
      </div>

      {/* ── Body ── */}
      <div className="term-body">

        {/* Output area */}
        <div className="term-output" ref={scrollRef}>
          {activeTab === 'TERMINAL' ? (
            <>
              {log.map((line, i) =>
                line.type === 'spacer'
                  ? <div key={i} style={{ height: 6 }} />
                  : <TerminalLine key={i} entry={line} />
              )}

              {/* Live prompt */}
              <div className="term-line term-prompt-live">
                <span className="term-py">{PY}</span>
                <span className="term-host">{HOST}</span>
                <span className="term-sep">:</span>
                <span className="term-cwd">{CWD}</span>
                <span className="term-dollar">$</span>
                <span className="term-input-wrap">
                  <input
                    ref={inputRef}
                    className="term-input"
                    value={input}
                    onChange={e => setInput(e.target.value)}
                    onKeyDown={handleKeyDown}
                    spellCheck={false}
                    autoCapitalize="off"
                    autoCorrect="off"
                  />
                  <span className="term-cursor" />
                </span>
              </div>
            </>
          ) : (
            <div className="term-empty-tab">No {activeTab.toLowerCase()} output</div>
          )}
        </div>

        {/* Sessions sidebar */}
        <div className="term-sessions">
          <div className="term-sessions__title">BASH</div>
          {TERMINAL_SESSIONS.map(s => (
            <button
              key={s.id}
              className={`term-session${activeSession === s.id ? ' term-session--active' : ''}`}
              onClick={e => { e.stopPropagation(); setActiveSession(s.id); }}
            >
              <svg width="11" height="11" viewBox="0 0 11 11" fill="none" style={{ flexShrink: 0, opacity: 0.5 }}>
                <rect x="1" y="1" width="9" height="9" rx="1.5" stroke="currentColor" strokeWidth="1.1"/>
                <path d="M3 4L5 5.5L3 7" stroke="currentColor" strokeWidth="1.1" strokeLinecap="round" strokeLinejoin="round"/>
                <line x1="6" y1="7" x2="8" y2="7" stroke="currentColor" strokeWidth="1.1" strokeLinecap="round"/>
              </svg>
              <span className="term-session__label">{s.sub}</span>
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

