/* ── Custom Component — Python tokenizer ───────────────────────── */

const PY_KEYWORDS = new Set([
  'def','import','from','return','if','else','elif','for','while','class',
  'True','False','None','and','or','not','in','is','pass','raise','try',
  'except','finally','with','as','lambda','yield','break','continue',
  'global','nonlocal','assert','del','async','await',
]);
const PY_BUILTINS = new Set([
  'print','len','range','list','dict','str','int','float','bool','tuple',
  'set','type','isinstance','hasattr','getattr','setattr','enumerate','zip',
  'map','filter','sorted','reversed','any','all','min','max','sum','abs',
  'round','open','super','object','property','staticmethod','classmethod',
]);

function tokenizePython(code) {
  const tokens = [];
  let i = 0;
  while (i < code.length) {
    // Comment
    if (code[i] === '#') {
      let j = i;
      while (j < code.length && code[j] !== '\n') j++;
      tokens.push({ type: 'comment', text: code.slice(i, j) }); i = j; continue;
    }
    // Triple-quoted string
    if ((code[i] === '"' || code[i] === "'") && code.slice(i, i+3) === code[i].repeat(3)) {
      const q = code[i].repeat(3); let j = i + 3;
      while (j < code.length && code.slice(j, j+3) !== q) {
        if (code[j] === '\\') j += 2; else j++;
      }
      tokens.push({ type: 'string', text: code.slice(i, j + 3) }); i = j + 3; continue;
    }
    // Single-quoted string
    if (code[i] === '"' || code[i] === "'") {
      const q = code[i]; let j = i + 1;
      while (j < code.length && code[j] !== q && code[j] !== '\n') {
        if (code[j] === '\\') j += 2; else j++;
      }
      tokens.push({ type: 'string', text: code.slice(i, j + 1) }); i = j + 1; continue;
    }
    // Decorator
    if (code[i] === '@') {
      let j = i + 1;
      while (j < code.length && /[\w.]/.test(code[j])) j++;
      tokens.push({ type: 'decorator', text: code.slice(i, j) }); i = j; continue;
    }
    // Number
    if (/[0-9]/.test(code[i])) {
      let j = i;
      while (j < code.length && /[0-9._eExXabcdefABCDEF]/.test(code[j])) j++;
      tokens.push({ type: 'number', text: code.slice(i, j) }); i = j; continue;
    }
    // Identifier / keyword / builtin
    if (/[a-zA-Z_]/.test(code[i])) {
      let j = i;
      while (j < code.length && /\w/.test(code[j])) j++;
      const word = code.slice(i, j);
      const type = PY_KEYWORDS.has(word) ? 'keyword' : PY_BUILTINS.has(word) ? 'builtin' : 'ident';
      tokens.push({ type, text: word }); i = j; continue;
    }
    // Arrow / operator / punctuation
    if (code.slice(i, i+2) === '->') {
      tokens.push({ type: 'punct', text: '->' }); i += 2; continue;
    }
    tokens.push({ type: /[+\-*/%=<>!&|^~:,.\[\]{}()]/.test(code[i]) ? 'punct' : 'plain', text: code[i] });
    i++;
  }
  return tokens;
}

const TOKEN_CLASS = { keyword:'py-kw', builtin:'py-bi', string:'py-str',
  comment:'py-cm', number:'py-num', decorator:'py-dc', punct:'py-pt' };

function highlightPython(code) {
  return tokenizePython(code).map((t, i) => {
    const cls = TOKEN_CLASS[t.type];
    return cls ? <span key={i} className={cls}>{t.text}</span> : t.text;
  });
}

/* ── Custom Component — linter ──────────────────────────────────── */

function lintPython(code) {
  const issues = [];
  const lines = code.split('\n');
  let bracketStack = [], inStr = false, strChar = '', tripleStr = false;

  lines.forEach((line, li) => {
    const trimmed = line.trim();
    // Compound statement without colon
    if (/^\s*(def|if|elif|else|for|while|class|try|except|finally|with)\b/.test(line)) {
      const stripped = line.replace(/#.*$/, '').trimEnd();
      if (bracketStack.length === 0 &&
          !stripped.endsWith(':') && !stripped.endsWith('\\') &&
          !stripped.endsWith(',') && !stripped.endsWith('(')) {
        issues.push({ line: li, type: 'warning', msg: 'Statement may be missing a trailing colon' });
      }
    }
    // Bracket tracking
    for (let ci = 0; ci < line.length; ci++) {
      const ch = line[ci];
      if (!inStr) {
        if (ch === '#') break;
        if ((ch === '"' || ch === "'") && line.slice(ci, ci+3) === ch.repeat(3)) {
          inStr = true; strChar = ch.repeat(3); tripleStr = true; ci += 2; continue;
        }
        if (ch === '"' || ch === "'") { inStr = true; strChar = ch; tripleStr = false; continue; }
        if ('([{'.includes(ch)) bracketStack.push({ ch, line: li, col: ci });
        if (')]}'.includes(ch)) {
          if (bracketStack.length > 0) bracketStack.pop();
          else issues.push({ line: li, type: 'error', msg: `Unexpected '${ch}'` });
        }
      } else {
        const endQ = tripleStr ? strChar : strChar;
        const endLen = tripleStr ? 3 : 1;
        if (line.slice(ci, ci + endLen) === endQ && (ci === 0 || line[ci-1] !== '\\')) {
          inStr = false; if (tripleStr) ci += 2;
        }
      }
    }
    // Bare except
    if (trimmed === 'except:')
      issues.push({ line: li, type: 'warning', msg: "Bare 'except' catches all — specify the exception type" });
    // Python 2 print
    if (/^\s*print\s+[^(=]/.test(line))
      issues.push({ line: li, type: 'error', msg: 'Use print() with parentheses (Python 3)' });
    // == None
    if (/[=!]=\s*None/.test(line))
      issues.push({ line: li, type: 'warning', msg: "Prefer 'is None' / 'is not None' over == / !=" });
    // mutable default
    if (/def\s+\w+\s*\([^)]*=\s*[\[{]/.test(line))
      issues.push({ line: li, type: 'warning', msg: 'Avoid mutable default argument (use None and assign inside)' });
  });
  bracketStack.forEach(o =>
    issues.push({ line: o.line, type: 'error', msg: `Unclosed '${o.ch}'` })
  );
  return issues;
}

/* ── Custom Component — param parser ───────────────────────────── */

function parseOneParam(str, out) {
  str = str.trim();
  if (!str) return;

  // Extract inline annotation comments before stripping them
  const editorM  = str.match(/#\s*editor:\s*(\S+)/);
  const optionsM = str.match(/#\s*options:\s*([^\n]+)/);
  const rangeM   = str.match(/#\s*range:\s*([\d.]+)\s*[,–0-]\s*([\d.]+)/);
  const editor   = editorM  ? editorM[1].trim()  : null;
  const rangeAnn = rangeM   ? { min: parseFloat(rangeM[1]), max: parseFloat(rangeM[2]) } : null;
  const optionsFromComment = optionsM
    ? optionsM[1].trim().split('|').map(s => s.trim()).filter(Boolean)
    : null;

  // Strip leading-only comment lines (e.g. "# ── Config schema ──")
  str = str.split('\n').filter(l => !l.trim().startsWith('#')).join('\n').trim();
  // Strip inline comments
  str = str.replace(/#[^\n]*/, '').trim();

  if (!str || str.startsWith('*') || str.startsWith('/') || str.startsWith('**')) return;
  const m = str.match(/^(\w+)(?:\s*:\s*([^=]+?))?(?:\s*=\s*(.+))?$/s);
  if (!m) return;
  const [, name, rawType, defaultVal] = m;
  const typeHint = rawType?.trim() || null;

  let inputType = 'text';
  if (typeHint) {
    const t = typeHint.toLowerCase().replace(/\s/g,'');
    if (t === 'bool') inputType = 'bool';
    else if (t === 'int') inputType = 'int';
    else if (t === 'float') inputType = 'float';
    else if (t.startsWith('list') || t.startsWith('tuple')) inputType = 'list';
    else if (t.startsWith('literal[')) inputType = 'literal';
  }
  if (defaultVal === 'True' || defaultVal === 'False') inputType = 'bool';

  let options = optionsFromComment || null;
  if (!options && typeHint) {
    const lit = typeHint.match(/Literal\[([^\]]+)\]/i);
    if (lit) {
      options = lit[1].split(',').map(s => s.trim().replace(/^['"]|['"]$/g,''));
      inputType = 'literal';
    }
  }
  out.push({ name, typeHint, defaultVal: defaultVal?.trim() ?? null, inputType, options, required: defaultVal === undefined, editor, range: rangeAnn });
}

function parsePythonParams(code) {
  // Extract typed I/O from top-of-file comments
  const ioInputM  = code.match(/#\s*Input:\s*(\w+)\s*[-]+\s*(\w+)/);
  const ioOutputM = code.match(/#\s*Output:\s*(\w+)\s*[-]+\s*(\w+)/);
  const ioInput   = ioInputM  ? { name: ioInputM[1],  type: ioInputM[2]  } : null;
  const ioOutput  = ioOutputM ? { name: ioOutputM[1], type: ioOutputM[2] } : null;

  const fnM = code.match(/def\s+(\w+)\s*\(([\s\S]*?)\)\s*(?:->\s*([\w\[\], |.]+?))?\s*:/);
  if (!fnM) return null;
  const fnName = fnM[1];
  const paramsRaw = fnM[2];
  const returnType = fnM[3]?.trim() || null;
  const docM = code.match(/"""([\s\S]*?)"""/);
  const docstring = docM ? docM[1].split('\n').find(l => l.trim())?.trim() || null : null;

  const params = [];
  let depth = 0, cur = '', inS = false, sq = '', inCmt = false;
  for (const ch of paramsRaw) {
    if (ch === '\n') { inCmt = false; cur += ch; continue; }
    if (ch === '#' && !inS) { inCmt = true; cur += ch; continue; }
    if (inCmt) { cur += ch; continue; }
    if (!inS) {
      if (ch === '"' || ch === "'") { inS = true; sq = ch; cur += ch; continue; }
      if ('([{'.includes(ch)) { depth++; cur += ch; continue; }
      if (')]}'.includes(ch)) { depth--; cur += ch; continue; }
      if (ch === ',' && depth === 0) { parseOneParam(cur, params); cur = ''; continue; }
    } else { if (ch === sq) inS = false; }
    cur += ch;
  }
  parseOneParam(cur, params);
  return { fnName, params, returnType, docstring, ioInput, ioOutput };
}

