// Identify data-source params: str type with path/url/feed/data/file/source in name
function extractDataSources(parsed) {
  if (!parsed?.params) return [];
  return parsed.params.filter(p => {
    if (p.typeHint !== 'str') return false;
    const n = p.name.toLowerCase();
    return /path|url|feed|data|file|source|input/.test(n);
  });
}

