function DataTab({ parsed, connected, onToggleConnect, schemaMapping, onSchemaChange, onGoToConfig }) {
  const sources = extractDataSources(parsed);
  const [previewSource, setPreviewSource] = useState(null);

  const connectedSources = sources.filter(s => connected[s.name]);
  const previewData      = previewSource ? MOCK_DATA_SOURCES[previewSource] : null;

  const allColumns = connectedSources
    .flatMap(s => MOCK_DATA_SOURCES[s.name]?.columns ?? [])
    .filter((c, i, a) => a.indexOf(c) === i);

  const mappedCount = Object.values(schemaMapping).filter(v => v && allColumns.includes(v)).length;

  function toggleConnect(name) {
    const nowConnecting = !connected[name];
    onToggleConnect(name, nowConnecting);
    if (nowConnecting && !previewSource) setPreviewSource(name);
    if (!nowConnecting && previewSource === name) {
      const next = connectedSources.find(s => s.name !== name);
      setPreviewSource(next ? next.name : null);
    }
  }

  if (sources.length === 0) {
    return (
      <div style={{ padding: '32px 16px', color: 'rgba(255,255,255,0.28)', fontSize: 12, textAlign: 'center', lineHeight: 1.8 }}>
        No data source parameters detected.<br />
        Add <code style={{ fontFamily: 'monospace', color: 'rgba(255,255,255,0.4)' }}>str</code> parameters whose<br />
        names contain <code style={{ fontFamily: 'monospace', color: 'rgba(255,255,255,0.4)' }}>_path</code> or <code style={{ fontFamily: 'monospace', color: 'rgba(255,255,255,0.4)' }}>_url</code>.
      </div>
    );
  }

  return (
    <div className="data-tab">

      {/* ── 1. Sources ── */}
      <div className="data-tab__section">
        <div className="data-tab__section-title">Data sources</div>
        <div className="data-tab__sources">
          {sources.map(s => {
            const mock   = MOCK_DATA_SOURCES[s.name];
            const isConn = !!connected[s.name];
            return (
              <div key={s.name} className={`ds-card${isConn ? ' ds-card--connected' : ''}`}>
                <div className="ds-card__icon">
                  {mock?.icon === 'api' ? (
                    <svg width="14" height="14" viewBox="0 0 14 14" fill="none">
                      <rect x="1" y="4" width="12" height="6" rx="1.5" stroke="currentColor" strokeWidth="1.1"/>
                      <path d="M4 7h6M9 5.5L10.5 7L9 8.5" stroke="currentColor" strokeWidth="1.1" strokeLinecap="round" strokeLinejoin="round"/>
                    </svg>
                  ) : (
                    <svg width="14" height="14" viewBox="0 0 14 14" fill="none">
                      <path d="M2 2.5a1 1 0 011-1h5l3 3V11.5a1 1 0 01-1 1H3a1 1 0 01-1-1V2.5z" stroke="currentColor" strokeWidth="1.1" strokeLinejoin="round"/>
                      <path d="M8 1.5V5h3.5" stroke="currentColor" strokeWidth="1.1" strokeLinejoin="round"/>
                    </svg>
                  )}
                </div>
                <div className="ds-card__body">
                  <div className="ds-card__name">{mock?.label || s.name.replace(/_/g, ' ')}</div>
                  <div className="ds-card__param">{s.name}</div>
                </div>
                <div className={`ds-status-dot${isConn ? ' ds-status-dot--on' : ''}`} />
                <button
                  className={`ds-card__btn${isConn ? ' ds-card__btn--on' : ''}`}
                  onClick={() => toggleConnect(s.name)}
                >
                  {isConn ? 'Configured' : 'Connect'}
                </button>
              </div>
            );
          })}
        </div>
      </div>

      {/* ── 2. Preview ── */}
      <div className="data-tab__section">
        <div className="data-tab__section-header">
          <div className="data-tab__section-title">Preview</div>
          {connectedSources.length > 1 && (
            <div className="ds-source-select-wrap">
              <select
                className="ds-source-select"
                value={previewSource || ''}
                onChange={e => setPreviewSource(e.target.value)}
              >
                {connectedSources.map(s => {
                  const mock = MOCK_DATA_SOURCES[s.name];
                  return <option key={s.name} value={s.name}>{mock?.label || s.name}</option>;
                })}
              </select>
            </div>
          )}
        </div>
        {previewData ? (
          <>
            <div className="ds-preview-wrap">
              <table className="ds-table">
                <thead>
                  <tr>{previewData.columns.map(c => <th key={c}>{c}</th>)}</tr>
                </thead>
                <tbody>
                  {previewData.rows.map((row, i) => (
                    <tr key={i}>{row.map((cell, j) => <td key={j}>{cell}</td>)}</tr>
                  ))}
                </tbody>
              </table>
            </div>
            <div className="ds-preview-stats">
              <span>{previewData.stats.rows} rows</span>
              <span className="ds-dot">·</span>
              <span>{previewData.stats.cols} columns</span>
              <span className="ds-dot">·</span>
              <span>synced {previewData.stats.sync}</span>
            </div>
          </>
        ) : (
          <div className="ds-empty">Connect a data source above to preview data</div>
        )}
      </div>

      {/* ── 3. Schema mapping ── */}
      <div className="data-tab__section data-tab__section--last">
        <div className="data-tab__section-header">
          <div className="data-tab__section-title">Schema mapping</div>
          {allColumns.length > 0 && (
            <span className="data-tab__badge">{mappedCount}/{SCHEMA_SLOTS.length} mapped</span>
          )}
        </div>
        {allColumns.length === 0 ? (
          <div className="ds-empty">Connect a source first to map schema fields</div>
        ) : (
          <div className="ds-schema">
            {SCHEMA_SLOTS.map(slot => {
              const val     = schemaMapping[slot.slot] || '';
              const isMapped = val && allColumns.includes(val);
              return (
                <div key={slot.slot} className="ds-schema-row">
                  <div className="ds-schema-row__label">
                    {slot.label}
                    {slot.required && <span className="tf-panel__req">*</span>}
                  </div>
                  <div className={`ds-schema-sel-wrap${isMapped ? ' ds-schema-sel-wrap--mapped' : ''}`}>
                    <select
                      className="ds-schema-sel"
                      value={val}
                      onChange={e => onSchemaChange(slot.slot, e.target.value)}
                    >
                      <option value="">— not mapped —</option>
                      {allColumns.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                    <svg width="9" height="9" viewBox="0 0 9 9" fill="none" className="ds-schema-chevron">
                      <path d="M1.5 3L4.5 6L7.5 3" stroke="currentColor" strokeWidth="1.1" strokeLinecap="round" strokeLinejoin="round"/>
                    </svg>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

/* ── Custom Config Panel — right panel ──────────────────────────── */

function CustomConfigPanel({ comp, onClose, onRename, width }) {
  const code   = comp.code ?? CUSTOM_DEFAULT_CODE;
  const parsed = useMemo(() => parsePythonParams(code), [code]);

  const [activeTab, setActiveTab] = useState('config');

  // ── Shared state lifted here so Config and Data stay in sync ──
  const [vals, setVals] = useState(() => {
    const v = {};
    parsed?.params?.forEach(p => {
      if (p.defaultVal !== null) {
        if (p.inputType === 'bool') v[p.name] = p.defaultVal === 'True';
        else v[p.name] = p.defaultVal.replace(/^['"]|['"]$/g, '');
      }
    });
    return v;
  });
  const [connected, setConnected]       = useState({});
  const [schemaMapping, setSchemaMapping] = useState(SLOT_DEFAULTS);

  const dataSrcs     = extractDataSources(parsed);
  const dataSrcNames = dataSrcs.map(s => s.name);
  const connCount    = Object.values(connected).filter(Boolean).length;

  // When a source is connected/disconnected, reflect it in the config values
  function handleToggleConnect(name, nowOn) {
    setConnected(c => ({ ...c, [name]: nowOn }));
    if (nowOn) {
      // Fill the param value with the mock label so Config shows it as resolved
      const mock = MOCK_DATA_SOURCES[name];
      setVals(v => ({ ...v, [name]: mock?.label || name }));
    } else {
      // Clear back to empty so it shows "Connect in Data tab" again
      setVals(v => ({ ...v, [name]: '' }));
    }
  }

  const nonSrcParamCount = (parsed?.params?.length ?? 0) - dataSrcNames.length;

  return (
    <aside className="right-panel custom-comp-panel" style={width ? { width, minWidth: width } : {}}>

      {/* Header */}
      <div className="custom-comp-panel__header">
        <div className="panel-header__row" style={{ marginBottom: 0 }}>
          <div className="component-block__icon-wrap" style={{ marginRight: 6 }}>
            <IconBox size={12} />
          </div>
          <input
            className="custom-comp-panel__name-input"
            value={comp.name}
            onChange={e => onRename?.(e.target.value)}
            placeholder="Name your component…"
          />
          <button onClick={onClose} style={{ background:'none',border:'none',padding:2,cursor:'pointer',display:'flex',alignItems:'center',borderRadius:4,opacity:0.55,marginLeft:8 }}>
            <svg width="12" height="12" viewBox="0 0 12 12" fill="none">
              <path d="M2 2L10 10M10 2L2 10" stroke="rgba(255,255,255,0.8)" strokeWidth="1.3" strokeLinecap="round"/>
            </svg>
          </button>
        </div>

        {/* Tabs */}
        <div className="ccp-tabs">
          <button
            className={`ccp-tab${activeTab === 'config' ? ' ccp-tab--active' : ''}`}
            onClick={() => setActiveTab('config')}
          >
            Config
            {nonSrcParamCount > 0 && (
              <span className="ccp-tab__count">{nonSrcParamCount}</span>
            )}
          </button>
          <button
            className={`ccp-tab${activeTab === 'data' ? ' ccp-tab--active' : ''}`}
            onClick={() => setActiveTab('data')}
          >
            Data
            {dataSrcs.length > 0 && (
              <span className={`ccp-tab__count${connCount > 0 ? ' ccp-tab__count--on' : ''}`}>
                {connCount > 0 ? `${connCount}/${dataSrcs.length}` : dataSrcs.length}
              </span>
            )}
          </button>
        </div>
      </div>

      {/* Body */}
      <div className="ccp-config-scroll">
        {activeTab === 'config' ? (
          <AutoConfigForm
            parsed={parsed}
            vals={vals}
            onChange={(name, val) => setVals(v => ({ ...v, [name]: val }))}
            dataSrcNames={dataSrcNames}
            connected={connected}
            onGoToData={() => setActiveTab('data')}
            key={parsed?.params?.map(p => p.name).join(',')}
          />
        ) : (
          <DataTab
            parsed={parsed}
            connected={connected}
            onToggleConnect={handleToggleConnect}
            schemaMapping={schemaMapping}
            onSchemaChange={(slot, val) => setSchemaMapping(m => ({ ...m, [slot]: val }))}
            onGoToConfig={() => setActiveTab('config')}
          />
        )}
      </div>
    </aside>
  );
}

