import React, { useState, useMemo } from "react";
import {
  Lock, Unlock, RotateCcw, Copy, Check, ChevronDown,
  CheckCircle2, AlertTriangle, Grid3x3, Layers, Box, Gauge, FileOutput, Shapes
} from "lucide-react";

// ─── Constants ────────────────────────────────────────────────────────────────
const DENSITIES      = ["coarse", "medium", "fine"];
const ELEMENT_TYPES  = ["solid hexahedral", "tetrahedral"];
const FAIL_ACTIONS   = ["error", "warn"];
const OUT_FORMATS    = [
  { id: "BDF", label: "BDF", note: "Nastran" },
  { id: "INP", label: "INP", note: "Abaqus"  },
];

const DENSITY_DOT  = { coarse: 1, medium: 2, fine: 3 };
const DENSITY_COLOR = { coarse: "#6b7280", medium: "#f59e0b", fine: "#10b981" };

const REFINEMENT_ZONES = [
  { id: "root_attachment", label: "Root attachment", default: "fine"   },
  { id: "winglet_body",    label: "Winglet body",    default: "medium" },
  { id: "tip_cap",         label: "Tip cap",         default: "medium" },
];

const MATERIALS = ["CFRP", "GFRP", "aluminium alloy", "titanium", "steel"];

const MATERIAL_ZONES = [
  { id: "winglet_body", label: "Winglet body",  default: "CFRP"           },
  { id: "root_bracket", label: "Root bracket",  default: "aluminium alloy" },
];

const DEFAULTS = {
  density:       "medium",
  refinement:    { root_attachment: "fine", winglet_body: "medium", tip_cap: "medium" },
  element_type:  "solid hexahedral",
  materials:     { winglet_body: "CFRP", root_bracket: "aluminium alloy" },
  max_aspect:    5.0,
  min_jacobian:  0.3,
  fail_action:   "warn",
  out_format:    "BDF",
};

// ─── Serialisers ─────────────────────────────────────────────────────────────
function toYAML(cfg) {
  return `# Structural Mesher Configuration
# Generated by Flux Pipelines — ${new Date().toISOString().slice(0, 10)}

global_mesh:
  density: ${cfg.density}

local_refinement:
  root_attachment: ${cfg.refinement.root_attachment}
  winglet_body:    ${cfg.refinement.winglet_body}
  tip_cap:         ${cfg.refinement.tip_cap}

element_type: ${cfg.element_type}

material_zones:
  winglet_body: ${cfg.materials.winglet_body}
  root_bracket: ${cfg.materials.root_bracket}

quality:
  max_aspect_ratio: ${cfg.max_aspect}
  min_jacobian:     ${cfg.min_jacobian}
  on_failure:       ${cfg.fail_action}

output:
  format: ${cfg.out_format}
`;
}

function toAPIJson(cfg) {
  return JSON.stringify({
    global_mesh:      { density: cfg.density },
    local_refinement: cfg.refinement,
    element_type:     cfg.element_type,
    material_zones:   cfg.materials,
    quality:          { max_aspect_ratio: cfg.max_aspect, min_jacobian: cfg.min_jacobian, on_failure: cfg.fail_action },
    output:           { format: cfg.out_format },
  }, null, 2);
}

// ─── Sub-components ───────────────────────────────────────────────────────────
function SectionHeader({ icon: Icon, label }) {
  return (
    <div className="flex items-center gap-2 mb-3">
      <Icon size={13} className="text-[#aaabb1] shrink-0" />
      <span className="text-[11px] font-semibold uppercase tracking-widest text-[#aaabb1] opacity-60">
        {label}
      </span>
    </div>
  );
}

function Field({ label, hint, children }) {
  return (
    <div className="mb-3">
      <div className="flex items-baseline justify-between mb-1">
        <label className="text-[11px] text-[#aaabb1]">{label}</label>
        {hint && <span className="text-[10px] text-[#aaabb1] opacity-40">{hint}</span>}
      </div>
      {children}
    </div>
  );
}

function Pills({ value, options, onChange, disabled }) {
  return (
    <div className="flex gap-1.5">
      {options.map(opt => {
        const id    = opt.id    ?? opt;
        const label = opt.label ?? opt;
        const note  = opt.note;
        return (
          <button key={id} disabled={disabled} onClick={() => !disabled && onChange(id)}
            className={`flex-1 py-1.5 rounded border text-[12px] transition-all
              disabled:opacity-40 disabled:cursor-not-allowed
              ${value === id
                ? "border-[#aaabb1]/40 bg-[#2e3035] text-white"
                : "border-[#2e3035] text-[#aaabb1] hover:border-[#aaabb1]/30 hover:text-white"}`}>
            <span className="capitalize">{label}</span>
            {note && <span className="ml-1 text-[10px] opacity-50">({note})</span>}
          </button>
        );
      })}
    </div>
  );
}

function DensityDots({ density }) {
  const count = DENSITY_DOT[density];
  const color = DENSITY_COLOR[density];
  return (
    <div className="flex items-center gap-1">
      {[1,2,3].map(i => (
        <div key={i} className="rounded-full"
          style={{ width: 6, height: 6, background: i <= count ? color : '#2e3035' }} />
      ))}
    </div>
  );
}

function ZoneRow({ label, value, onChange, disabled, options = DENSITIES, showDots = true }) {
  return (
    <div className="flex items-center justify-between py-2 border-b border-[#2e3035]/60 last:border-0">
      <span className="text-[12px] text-white shrink-0 mr-3">{label}</span>
      <div className="flex items-center gap-3">
        {showDots && <DensityDots density={value} />}
        <div className="flex gap-1">
          {options.map(opt => (
            <button key={opt} disabled={disabled} onClick={() => !disabled && onChange(opt)}
              className={`px-2 py-0.5 rounded text-[11px] capitalize transition-all whitespace-nowrap
                disabled:opacity-40 disabled:cursor-not-allowed
                ${value === opt
                  ? "bg-[#2e3035] text-white border border-[#aaabb1]/30"
                  : "text-[#aaabb1] hover:text-white border border-transparent"}`}>
              {opt}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

function NumberInput({ value, onChange, min, max, step, disabled, suffix }) {
  return (
    <div className="flex items-center gap-1.5">
      <input type="number" value={value} min={min} max={max} step={step} disabled={disabled}
        onChange={e => { const n = parseFloat(e.target.value); if (!isNaN(n)) onChange(n); }}
        className="w-full bg-[#1d2024] border border-[#2e3035] rounded px-2.5 py-1.5 text-[12px] text-white
          focus:outline-none focus:border-[#aaabb1]/40 disabled:opacity-40 disabled:cursor-not-allowed
          [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none
          [&::-webkit-inner-spin-button]:appearance-none transition-colors" />
      {suffix && <span className="text-[11px] text-[#aaabb1] opacity-40 shrink-0">{suffix}</span>}
    </div>
  );
}

function CodeBlock({ code, lang }) {
  const [copied, setCopied] = useState(false);
  return (
    <div className="rounded border border-[#2e3035] bg-[#0c0e13] overflow-hidden">
      <div className="flex items-center justify-between px-3 py-1.5 border-b border-[#2e3035]">
        <span className="text-[10px] text-[#aaabb1] opacity-40 font-mono">{lang}</span>
        <button onClick={() => { navigator.clipboard.writeText(code); setCopied(true); setTimeout(() => setCopied(false), 1500); }}
          className="text-[#aaabb1] hover:text-white transition-colors">
          {copied ? <Check size={12} className="text-green-400" /> : <Copy size={12} />}
        </button>
      </div>
      <pre className="p-3 text-[11px] font-mono text-[#aaabb1] overflow-x-auto whitespace-pre leading-relaxed">{code}</pre>
    </div>
  );
}

// ─── Main ─────────────────────────────────────────────────────────────────────
export default function StructuralMesherConfig({ locked = false, onClose }) {
  const [cfg, setCfg]         = useState(DEFAULTS);
  const [isLocked, setLocked] = useState(locked);
  const [tab, setTab]         = useState("ui");

  const set    = (key, val) => { if (!isLocked) setCfg(p => ({ ...p, [key]: val })); };
  const setRef = (id,  val) => { if (!isLocked) setCfg(p => ({ ...p, refinement: { ...p.refinement, [id]: val } })); };
  const setMat = (id,  val) => { if (!isLocked) setCfg(p => ({ ...p, materials:  { ...p.materials,  [id]: val } })); };
  const reset  = ()         => { if (!isLocked) setCfg(DEFAULTS); };

  const yaml    = useMemo(() => toYAML(cfg),   [cfg]);
  const apiJson = useMemo(() => toAPIJson(cfg), [cfg]);

  const qualityWarn = cfg.max_aspect > 10 || cfg.min_jacobian < 0.1;

  return (
    <div className="flex flex-col h-full bg-[#111318] text-white overflow-hidden select-none">

      {/* Header */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-[#2e3035] shrink-0">
        <div className="flex items-center gap-2">
          <Shapes size={14} className="text-[#aaabb1]" />
          <span className="text-[13px] font-semibold">Structural Mesher</span>
          <span className="text-[10px] text-[#aaabb1] opacity-50 bg-[#1d2024] px-1.5 py-0.5 rounded border border-[#2e3035]">Altair</span>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={reset} disabled={isLocked}
            className="text-[#aaabb1] hover:text-white disabled:opacity-30 transition-colors" title="Reset">
            <RotateCcw size={13} />
          </button>
          <button onClick={() => setLocked(v => !v)} className="text-[#aaabb1] hover:text-white transition-colors">
            {isLocked ? <Lock size={13} /> : <Unlock size={13} />}
          </button>
          {onClose && (
            <button onClick={onClose} className="text-[#aaabb1] hover:text-white transition-colors ml-1" title="Close">
              <svg width="13" height="13" viewBox="0 0 13 13" fill="none"><path d="M2 2L11 11M11 2L2 11" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round"/></svg>
            </button>
          )}
        </div>
      </div>

      {/* Tabs */}
      <div className="flex border-b border-[#2e3035] shrink-0">
        {["ui", "yaml"].map(t => (
          <button key={t} onClick={() => setTab(t)}
            className={`px-4 py-2 text-[11px] font-medium uppercase tracking-wider transition-colors border-b-2
              ${tab === t ? "border-white text-white" : "border-transparent text-[#aaabb1] hover:text-white"}`}>
            {t === "api" ? "API" : t.toUpperCase()}
          </button>
        ))}
      </div>

      {/* Body */}
      <div className="flex-1 overflow-y-auto px-4 py-4">
        {tab !== "ui" ? (
          <CodeBlock code={yaml} lang="yaml" />
        ) : (
          <div className="space-y-5">

            {/* Global */}
            <div>
              <SectionHeader icon={Grid3x3} label="Global Mesh Size" />
              <Field label="Density">
                <Pills value={cfg.density} options={DENSITIES} onChange={v => set("density", v)} disabled={isLocked} />
              </Field>
            </div>

            <div className="border-t border-[#2e3035]" />

            {/* Local refinement */}
            <div>
              <SectionHeader icon={Layers} label="Local Refinement" />
              <div className="rounded border border-[#2e3035] bg-[#1d2024] px-3 divide-y divide-[#2e3035]/60">
                {REFINEMENT_ZONES.map(z => (
                  <ZoneRow key={z.id} label={z.label}
                    value={cfg.refinement[z.id]} onChange={v => setRef(z.id, v)} disabled={isLocked} />
                ))}
              </div>
            </div>

            <div className="border-t border-[#2e3035]" />

            {/* Element type */}
            <div>
              <SectionHeader icon={Box} label="Element Type" />
              <Pills value={cfg.element_type} options={ELEMENT_TYPES}
                onChange={v => set("element_type", v)} disabled={isLocked} />
            </div>

            <div className="border-t border-[#2e3035]" />

            {/* Material zones */}
            <div>
              <SectionHeader icon={Layers} label="Material Zones" />
              <div className="rounded border border-[#2e3035] bg-[#1d2024] px-3 divide-y divide-[#2e3035]/60">
                {MATERIAL_ZONES.map(z => (
                  <ZoneRow key={z.id} label={z.label}
                    value={cfg.materials[z.id]}
                    onChange={v => setMat(z.id, v)}
                    options={MATERIALS}
                    showDots={false}
                    disabled={isLocked} />
                ))}
              </div>
            </div>

            <div className="border-t border-[#2e3035]" />

            {/* Quality */}
            <div>
              <SectionHeader icon={Gauge} label="Quality Thresholds" />
              {qualityWarn && (
                <div className="flex items-center gap-2 mb-3 px-3 py-2 rounded border border-[#2e3035] bg-[#1d2024] text-[#aaabb1] text-[11px]">
                  <AlertTriangle size={11} className="shrink-0 text-amber-400" />
                  Threshold values outside recommended range
                </div>
              )}
              <div className="grid grid-cols-2 gap-2 mb-3">
                <Field label="Max aspect ratio">
                  <NumberInput value={cfg.max_aspect} onChange={v => set("max_aspect", v)}
                    min={1} max={50} step={0.5} disabled={isLocked} />
                </Field>
                <Field label="Min Jacobian">
                  <NumberInput value={cfg.min_jacobian} onChange={v => set("min_jacobian", v)}
                    min={0} max={1} step={0.01} disabled={isLocked} />
                </Field>
              </div>
              <Field label="Action if failed">
                <Pills value={cfg.fail_action} options={FAIL_ACTIONS}
                  onChange={v => set("fail_action", v)} disabled={isLocked} />
              </Field>
            </div>

            <div className="border-t border-[#2e3035]" />

            {/* Output */}
            <div>
              <SectionHeader icon={FileOutput} label="Output Format" />
              <Pills value={cfg.out_format} options={OUT_FORMATS}
                onChange={v => set("out_format", v)} disabled={isLocked} />
            </div>

            {/* Status */}
            <div className="flex items-center gap-2 text-[11px] text-[#aaabb1] opacity-40 pt-1">
              <CheckCircle2 size={11} className={!qualityWarn ? "text-green-400 opacity-100" : ""} />
              {!qualityWarn
                ? <span className="text-green-400 opacity-100">Ready to run</span>
                : "Review quality thresholds"}
            </div>

          </div>
        )}
      </div>
    </div>
  );
}
