import { Fragment, useEffect, useMemo, useRef, useState } from 'react';
import { Search, Trash2, Copy, ChevronLeft, ChevronRight, ChevronsUpDown, Code2, Loader2, Info, AlertTriangle } from 'lucide-react';

import AppSidebar from './AppSidebar';
import ConfirmDeleteModal from './ConfirmDeleteModal';
import NewComponentModal from './NewComponentModal';
import SimulationComponentDetailPage from './SimulationComponentDetailPage';
import AiComponentDetailPage from './AiComponentDetailPage';
import { getStarterCode } from './PipelineEditorPage';
import { getJupyterMockHtml } from './jupyterMockHtml';
import StartNotebookModal from './StartNotebookModal';
import { useAppData, generateId } from './AppDataContext';
import { useToast } from './ToastContext';
import './PipelinesListPage.css';
import './PipelineEditorPage.css';
import './ComponentsPage.css';

const NOTEBOOK_LOAD_DELAY_MS = 1400;
const NOTEBOOK_CLOSE_POLL_MS = 500;

const COLUMNS = [
  { id: 'name', label: 'Component', sortable: true },
  { id: 'category', label: 'Variant', sortable: true },
  { id: 'version', label: 'Version', sortable: true },
  { id: 'usedIn', label: 'Used in', sortable: true },
  { id: 'updatedBy', label: 'Last edited by', sortable: true },
  { id: 'created', label: 'Created', sortable: true },
  { id: 'updated', label: 'Last updated', sortable: true },
  { id: 'actions', label: 'Actions', sortable: false },
];

const DEFAULT_COLUMN_WIDTHS = {
  name: 280,
  category: 110,
  version: 90,
  usedIn: 90,
  updatedBy: 170,
  created: 150,
  updated: 150,
  actions: 130,
};

const MIN_COLUMN_WIDTH = 70;

const PAGE_SIZE_OPTIONS = [10, 25, 50, 100];

function latestVersion(component) {
  return component.versions[0];
}

function categoryLabel(component) {
  return component.category === 'px' ? 'PX' : 'Custom';
}

function bumpVersion(version) {
  const match = version.match(/^(\D*)(\d+(?:\.\d+)*)$/);
  if (!match) return `${version}.1`;
  const [, prefix, numeric] = match;
  const parts = numeric.split('.');
  const lastIndex = parts.length - 1;
  parts[lastIndex] = String(parseInt(parts[lastIndex], 10) + 1);
  return `${prefix}${parts.join('.')}`;
}

export default function ComponentsPage({ onNavigate, userName }) {
  const { components, setComponents } = useAppData();
  const showToast = useToast();
  const [search, setSearch] = useState('');
  const [sort, setSort] = useState({ column: null, ascending: true });
  const [pageSize, setPageSize] = useState(50);
  const [currentPage, setCurrentPage] = useState(1);
  const [pendingDelete, setPendingDelete] = useState(null);
  const [newComponentOpen, setNewComponentOpen] = useState(false);
  const [cloneSource, setCloneSource] = useState(null);
  const [columnWidths, setColumnWidths] = useState(DEFAULT_COLUMN_WIDTHS);
  const [expandedComponents, setExpandedComponents] = useState(() => new Set());
  const [notebookStatuses, setNotebookStatuses] = useState({});
  const [detailComponent, setDetailComponent] = useState(null);
  const [aiDetailComponent, setAiDetailComponent] = useState(null);
  const [pendingNotebook, setPendingNotebook] = useState(null);
  const [devCenterProfile, setDevCenterProfile] = useState('');
  const resizingColumn = useRef(null);
  const resizeStartX = useRef(0);
  const resizeStartWidth = useRef(0);
  const notebookWindowsRef = useRef({});
  const notebookPollRef = useRef({});

  useEffect(() => {
    return () => {
      Object.values(notebookPollRef.current).forEach(clearInterval);
    };
  }, []);

  useEffect(() => {
    function handleNotebookMessage(event) {
      if (event.origin !== window.location.origin) return;
      const { type } = event.data || {};
      if (type === 'px-notebook-settings-update') {
        const { nodeId, computeProfile } = event.data;
        const separatorIndex = nodeId.lastIndexOf('::');
        if (separatorIndex === -1) return;
        const componentId = nodeId.slice(0, separatorIndex);
        const versionNumber = nodeId.slice(separatorIndex + 2);
        setComponents(prev => prev.map(c => (
          c.id === componentId
            ? { ...c, versions: c.versions.map(v => (v.version === versionNumber ? { ...v, computeProfile } : v)) }
            : c
        )));
      } else if (type === 'px-notebook-save-version') {
        const { nodeId, code } = event.data;
        const separatorIndex = nodeId.lastIndexOf('::');
        if (separatorIndex === -1) return;
        const componentId = nodeId.slice(0, separatorIndex);
        const versionNumber = nodeId.slice(separatorIndex + 2);
        let newVersion = null;
        let componentName = null;
        setComponents(prev => prev.map(c => {
          if (c.id !== componentId) return c;
          const sourceVersion = c.versions.find(v => v.version === versionNumber) || c.versions[0];
          newVersion = bumpVersion(sourceVersion.version);
          componentName = c.name;
          return {
            ...c,
            versions: [
              {
                version: newVersion,
                computeProfile: sourceVersion.computeProfile,
                updatedBy: userName,
                updated: 'Just now',
                usedIn: 0,
                code,
              },
              ...c.versions,
            ],
          };
        }));
        setExpandedComponents(prev => new Set(prev).add(componentId));
        if (newVersion) {
          transferNotebookWindow(nodeId, `${componentId}::${newVersion}`, componentName);
        }
      } else if (type === 'px-notebook-save-as-new') {
        const { nodeId, name, code } = event.data;
        const separatorIndex = nodeId.lastIndexOf('::');
        if (separatorIndex === -1) return;
        const componentId = nodeId.slice(0, separatorIndex);
        const versionNumber = nodeId.slice(separatorIndex + 2);
        const newId = generateId();
        const newKey = `${newId}::v0.1`;
        setComponents(prev => {
          const source = prev.find(c => c.id === componentId);
          if (!source) return prev;
          const sourceVersion = source.versions[0];
          const withTransferMark = prev.map(c => (
            c.id === componentId
              ? { ...c, versions: c.versions.map(v => (v.version === versionNumber ? { ...v, transferredTo: newId, transferredToName: name } : v)) }
              : c
          ));
          return [
            {
              id: newId,
              name,
              description: source.description,
              category: 'shared',
              versions: [
                { version: 'v0.1', computeProfile: sourceVersion.computeProfile, updatedBy: userName, updated: 'Just now', usedIn: 0, code },
              ],
              created: 'Just now',
            },
            ...withTransferMark,
          ];
        });
        setCurrentPage(1);
        transferNotebookWindow(nodeId, newKey, name);
        showToast({ variant: 'success', message: `Saved as new component "${name}"` });
      }
    }
    window.addEventListener('message', handleNotebookMessage);
    return () => window.removeEventListener('message', handleNotebookMessage);
  }, [userName, showToast, setComponents]);

  function keyFor(component, version) {
    return `${component.id}::${version.version}`;
  }

  function watchNotebookWindow(key, win) {
    if (!win) return;
    if (notebookPollRef.current[key]) clearInterval(notebookPollRef.current[key]);
    notebookPollRef.current[key] = setInterval(() => {
      if (win.closed) {
        clearInterval(notebookPollRef.current[key]);
        delete notebookPollRef.current[key];
        delete notebookWindowsRef.current[key];
        setNotebookStatuses(prev => {
          const next = { ...prev };
          delete next[key];
          return next;
        });
      }
    }, NOTEBOOK_CLOSE_POLL_MS);
  }

  function transferNotebookWindow(oldKey, newKey, newName) {
    const win = notebookWindowsRef.current[oldKey];
    if (win) {
      notebookWindowsRef.current[newKey] = win;
      delete notebookWindowsRef.current[oldKey];
      if (notebookPollRef.current[oldKey]) {
        clearInterval(notebookPollRef.current[oldKey]);
        delete notebookPollRef.current[oldKey];
      }
      watchNotebookWindow(newKey, win);
      win.postMessage({ type: 'px-notebook-renamed', newNodeId: newKey, newComponentName: newName }, window.location.origin);
    }
    setNotebookStatuses(prev => {
      const next = { ...prev };
      next[newKey] = prev[oldKey] ?? 'running';
      delete next[oldKey];
      return next;
    });
  }

  function requestComponentNotebook(component, version) {
    setPendingNotebook({ component, version });
  }

  function launchComponentNotebook(component, version, profile) {
    const key = keyFor(component, version);
    const isLatest = version === latestVersion(component);
    const readOnly = component.category === 'px';
    const fileName = `${component.name.toLowerCase().replace(/\s+/g, '_')}.py`;
    const html = getJupyterMockHtml({
      fileName,
      initialCode: version.code || getStarterCode(component.name, component.template),
      nodeId: key,
      pipelineName: 'Components',
      componentName: isLatest ? component.name : `${component.name} (${version.version})`,
      computeProfile: profile,
      readOnly,
      enableVersioning: true,
    });
    const blobUrl = URL.createObjectURL(new Blob([html], { type: 'text/html' }));
    const win = window.open(blobUrl, '_blank');
    if (!win) {
      URL.revokeObjectURL(blobUrl);
      return;
    }
    win.focus();
    notebookWindowsRef.current[key] = win;
    watchNotebookWindow(key, win);
    setNotebookStatuses(prev => ({ ...prev, [key]: 'loading' }));
    setTimeout(() => {
      setNotebookStatuses(prev => (prev[key] === 'loading' ? { ...prev, [key]: 'running' } : prev));
    }, NOTEBOOK_LOAD_DELAY_MS);
    if (profile !== version.computeProfile) {
      setComponents(prev => prev.map(c => (
        c.id !== component.id ? c : { ...c, versions: c.versions.map(v => (v.version === version.version ? { ...v, computeProfile: profile } : v)) }
      )));
    }
  }

  function requestDevCenterNotebook() {
    setPendingNotebook({ devCenter: true });
  }

  function launchDevCenterNotebook(profile) {
    setDevCenterProfile(profile);
    const html = getJupyterMockHtml({
      fileName: 'dev_center.py',
      pipelineName: 'Dev Center',
      componentName: 'Dev Center',
      computeProfile: profile,
    });
    const blobUrl = URL.createObjectURL(new Blob([html], { type: 'text/html' }));
    const win = window.open(blobUrl, '_blank');
    if (!win) URL.revokeObjectURL(blobUrl);
  }

  function handleRowClick(component) {
    if (component.simulation) {
      setDetailComponent(component);
      return;
    }
    setAiDetailComponent(component);
  }

  function handleDeleteSimulationComponent(component) {
    setComponents(prev => prev.filter(c => c.id !== component.id));
    setDetailComponent(null);
    showToast({ variant: 'success', message: `Deleted component "${component.name}"` });
  }

  function fieldFor(component, columnId) {
    if (columnId === 'name' || columnId === 'created') return component[columnId];
    if (columnId === 'category') return categoryLabel(component);
    return latestVersion(component)[columnId];
  }

  const visibleComponents = useMemo(() => {
    let rows = components;
    if (search.trim()) {
      const query = search.trim().toLowerCase();
      rows = rows.filter(c => c.name.toLowerCase().includes(query));
    }
    if (sort.column) {
      rows = [...rows].sort((a, b) => {
        const av = fieldFor(a, sort.column);
        const bv = fieldFor(b, sort.column);
        if (typeof av === 'number' && typeof bv === 'number') {
          return sort.ascending ? av - bv : bv - av;
        }
        const as = String(av || '').toLowerCase();
        const bs = String(bv || '').toLowerCase();
        if (as < bs) return sort.ascending ? -1 : 1;
        if (as > bs) return sort.ascending ? 1 : -1;
        return 0;
      });
    }
    return rows;
  }, [components, search, sort]);

  const totalPages = Math.max(1, Math.ceil(visibleComponents.length / pageSize));
  const pagedComponents = visibleComponents.slice((currentPage - 1) * pageSize, currentPage * pageSize);

  function handleSort(columnId) {
    setSort(prev => ({
      column: columnId,
      ascending: prev.column === columnId ? !prev.ascending : true,
    }));
  }

  function handleDeleteClick(component, e) {
    e.stopPropagation();
    setPendingDelete(component);
  }

  function handleCloneComponent(component, e) {
    e.stopPropagation();
    setCloneSource(component);
    setNewComponentOpen(true);
  }

  function cloneCandidateFor(component) {
    const latest = latestVersion(component);
    return {
      id: component.id,
      name: component.name,
      description: component.description,
      computeProfile: latest.computeProfile,
      code: latest.code || getStarterCode(component.name, component.template),
    };
  }

  function confirmDelete() {
    setComponents(prev => prev.filter(c => c.id !== pendingDelete.id));
    showToast({ variant: 'success', message: `Deleted component "${pendingDelete.name}"` });
    setPendingDelete(null);
  }

  function goToPage(page) {
    setCurrentPage(Math.min(totalPages, Math.max(1, page)));
  }

  function toggleExpanded(componentId, e) {
    e.stopPropagation();
    setExpandedComponents(prev => {
      const next = new Set(prev);
      if (next.has(componentId)) next.delete(componentId); else next.add(componentId);
      return next;
    });
  }

  function handleColumnResizeStart(columnId, e) {
    e.preventDefault();
    resizingColumn.current = columnId;
    resizeStartX.current = e.clientX;
    resizeStartWidth.current = columnWidths[columnId];
  }

  function handleTableMouseMove(e) {
    if (!resizingColumn.current) return;
    const dx = e.clientX - resizeStartX.current;
    setColumnWidths(prev => ({
      ...prev,
      [resizingColumn.current]: Math.max(MIN_COLUMN_WIDTH, resizeStartWidth.current + dx),
    }));
  }

  function handleTableMouseUp() {
    resizingColumn.current = null;
  }

  function handleCreateComponent({ name, description, computeProfile, code }) {
    const now = 'Just now';
    const wasClone = Boolean(cloneSource);
    setComponents(prev => [
      {
        id: generateId(),
        name,
        description,
        category: 'shared',
        versions: [
          { version: 'v0.1', computeProfile, updatedBy: userName, updated: now, usedIn: 0, code },
        ],
        created: now,
      },
      ...prev,
    ]);
    setNewComponentOpen(false);
    setCloneSource(null);
    setCurrentPage(1);
    showToast({ variant: 'success', message: wasClone ? `Cloned component "${name}"` : `Created component "${name}"` });
  }

  const notebookModal = pendingNotebook && (
    <StartNotebookModal
      notebookName={
        pendingNotebook.devCenter
          ? 'Dev Center'
          : pendingNotebook.version === latestVersion(pendingNotebook.component)
            ? pendingNotebook.component.name
            : `${pendingNotebook.component.name} (${pendingNotebook.version.version})`
      }
      defaultProfile={pendingNotebook.devCenter ? devCenterProfile : (pendingNotebook.version.computeProfile || '')}
      onCancel={() => setPendingNotebook(null)}
      onStart={profile => {
        if (pendingNotebook.devCenter) {
          launchDevCenterNotebook(profile);
        } else {
          launchComponentNotebook(pendingNotebook.component, pendingNotebook.version, profile);
        }
        setPendingNotebook(null);
      }}
    />
  );

  if (detailComponent) {
    return (
      <SimulationComponentDetailPage
        component={detailComponent}
        onNavigate={onNavigate}
        userName={userName}
        onBack={() => setDetailComponent(null)}
        onDelete={() => handleDeleteSimulationComponent(detailComponent)}
      />
    );
  }

  if (aiDetailComponent) {
    const aiLatest = latestVersion(aiDetailComponent);
    const aiNotebookKey = keyFor(aiDetailComponent, aiLatest);
    const aiNotebookStatus = notebookStatuses[aiNotebookKey];
    return (
      <>
        <AiComponentDetailPage
          component={aiDetailComponent}
          onNavigate={onNavigate}
          userName={userName}
          onBack={() => setAiDetailComponent(null)}
          notebookStatus={aiNotebookStatus}
          onConnectNotebook={() => requestComponentNotebook(aiDetailComponent, aiLatest)}
          onFocusNotebook={() => notebookWindowsRef.current[aiNotebookKey]?.focus()}
        />
        {notebookModal}
      </>
    );
  }

  return (
    <div className="px-pipelines">
      <AppSidebar activeItem="components" onNavigate={onNavigate} userName={userName} />

      <div className="px-pipelines__main">
        <header className="px-pipelines__header">
          <h1 className="px-pipelines__title">Components</h1>
          <div className="px-pipelines__header-actions">
            <a
              href="https://alpha.platform.physicsx.ai/platform-documentation/ai_workbench/how_to/configuring_standard_components.html"
              target="_blank"
              rel="noopener noreferrer"
              className="px-pipelines__title-doc-link"
              aria-label="Components documentation"
              title="Components documentation"
            >
              <Info size={16} />
            </a>
            <button
              type="button"
              className="px-tertiary-nav-btn"
              title="A workspace for developers to explore — data analysis, plots, and prototyping outside the pipeline flow."
              onClick={requestDevCenterNotebook}
            >
              Dev Center
            </button>
            <button type="button" className="px-pipelines__new-btn" onClick={() => setNewComponentOpen(true)}>
              Create new component
            </button>
          </div>
        </header>

        <div className="px-pipelines__content">
          <div className="px-pipelines__toolbar">
            <label className="px-search" style={{ marginLeft: 'auto' }}>
              <Search size={16} />
              <input
                type="text"
                placeholder="Search components"
                value={search}
                onChange={e => { setSearch(e.target.value); setCurrentPage(1); }}
              />
            </label>
          </div>

          <div className="px-table-scroll" onMouseMove={handleTableMouseMove} onMouseUp={handleTableMouseUp} onMouseLeave={handleTableMouseUp}>
            <table className="px-table px-components-table">
              <colgroup>
                {COLUMNS.map(col => (
                  <col key={col.id} style={{ width: columnWidths[col.id] }} />
                ))}
              </colgroup>
              <thead>
                <tr>
                  {COLUMNS.map((col, index) => (
                    <th key={col.id} className={`px-th-resizable${col.id === 'actions' ? ' px-th-actions' : ''}`}>
                      {col.sortable ? (
                        <button type="button" className="px-sort-th" onClick={() => handleSort(col.id)}>
                          {col.label}
                          <ChevronsUpDown size={14} />
                        </button>
                      ) : col.label}
                      {index < COLUMNS.length - 1 && (
                        <div
                          className="px-col-resize-handle"
                          onMouseDown={e => handleColumnResizeStart(col.id, e)}
                        />
                      )}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {pagedComponents.map(component => {
                  const latest = latestVersion(component);
                  const olderVersions = component.versions.slice(1);
                  const hasHistory = olderVersions.length > 0;
                  const expanded = expandedComponents.has(component.id);
                  const latestKey = keyFor(component, latest);
                  const notebookStatus = notebookStatuses[latestKey];
                  return (
                    <Fragment key={component.id}>
                      <tr onClick={() => handleRowClick(component)}>
                        <td>
                          <div className="px-components__name-cell">
                            {hasHistory ? (
                              <button
                                type="button"
                                className={`px-components__expand-btn${expanded ? ' px-components__expand-btn--open' : ''}`}
                                title={expanded ? `Collapse ${component.name} versions` : `Expand ${component.name} versions`}
                                aria-label={expanded ? `Collapse ${component.name} versions` : `Expand ${component.name} versions`}
                                onClick={e => toggleExpanded(component.id, e)}
                              >
                                <ChevronRight size={14} />
                              </button>
                            ) : (
                              <span className="px-components__expand-spacer" />
                            )}
                            <div className="px-table__name">
                              <span className="px-components__name-row">
                                <span>{component.name}</span>
                                {component.deprecated && (
                                  <span
                                    className="px-components__deprecated-icon"
                                    title="Deprecated"
                                    aria-label="Deprecated"
                                  >
                                    <AlertTriangle size={14} />
                                  </span>
                                )}
                              </span>
                              <span className="px-table__desc">{component.description || ''}</span>
                            </div>
                          </div>
                        </td>
                        <td><span className="px-badge">{categoryLabel(component)}</span></td>
                        <td>{latest.version}</td>
                        <td>{latest.usedIn}</td>
                        <td>{latest.updatedBy}</td>
                        <td>{component.created}</td>
                        <td>{latest.updated}</td>
                        <td>
                          <div className="px-components__actions-cell">
                            {component.simulation ? (
                              <span className="px-components__notebook-spacer" />
                            ) : latest.transferredTo ? (
                              <span
                                className="px-editor__node-icon px-editor__node-icon--transferred"
                                aria-label={`Renamed to ${latest.transferredToName}`}
                                title={`Renamed to "${latest.transferredToName}". Open the new component instead.`}
                              >
                                <Code2 size={12} />
                              </span>
                            ) : notebookStatus === 'loading' ? (
                              <span
                                className="px-editor__node-icon px-editor__node-icon--loading"
                                title={`Opening notebook for ${component.name}`}
                                aria-label={`Opening notebook for ${component.name}`}
                              >
                                <Loader2 size={14} className="px-spin" />
                              </span>
                            ) : notebookStatus === 'running' ? (
                              <button
                                type="button"
                                className="px-editor__node-icon px-editor__node-icon--running"
                                title={`Open notebook tab for ${component.name}`}
                                aria-label={`Open notebook tab for ${component.name}`}
                                onClick={e => { e.stopPropagation(); notebookWindowsRef.current[latestKey]?.focus(); }}
                              >
                                <Code2 size={12} />
                              </button>
                            ) : (
                              <button
                                type="button"
                                className="px-editor__node-icon"
                                title={component.category === 'px' ? `View notebook for ${component.name}` : `Open notebook for ${component.name}`}
                                aria-label={component.category === 'px' ? `View notebook for ${component.name}` : `Open notebook for ${component.name}`}
                                onClick={e => { e.stopPropagation(); requestComponentNotebook(component, latest); }}
                              >
                                <Code2 size={12} />
                              </button>
                            )}
                            <div className="px-table__actions">
                              <button
                                type="button"
                                className="px-icon-btn"
                                title={`Clone ${component.name}`}
                                aria-label={`Clone ${component.name}`}
                                disabled={component.simulation}
                                onClick={e => handleCloneComponent(component, e)}
                              >
                                <Copy size={16} />
                              </button>
                              <button
                                type="button"
                                className="px-icon-btn"
                                title={`Delete ${component.name}`}
                                aria-label={`Delete ${component.name}`}
                                disabled={!component.simulation}
                                onClick={e => handleDeleteClick(component, e)}
                              >
                                <Trash2 size={16} />
                              </button>
                            </div>
                          </div>
                        </td>
                      </tr>
                      {expanded && olderVersions.map(v => {
                        const versionKey = keyFor(component, v);
                        const versionNotebookStatus = notebookStatuses[versionKey];
                        return (
                          <tr
                            key={`${component.id}-${v.version}`}
                            className="px-components__version-row"
                            onClick={() => handleRowClick(component)}
                          >
                            <td>
                              <div className="px-components__name-cell">
                                <span className="px-components__expand-spacer" />
                                <span className="px-components__version-label">{component.name}</span>
                              </div>
                            </td>
                            <td><span className="px-badge">{categoryLabel(component)}</span></td>
                            <td>{v.version}</td>
                            <td>{v.usedIn}</td>
                            <td>{v.updatedBy}</td>
                            <td>—</td>
                            <td>{v.updated}</td>
                            <td>
                              <div className="px-components__actions-cell">
                                {component.simulation ? (
                                  <span className="px-components__notebook-spacer" />
                                ) : v.transferredTo ? (
                                  <span
                                    className="px-editor__node-icon px-editor__node-icon--transferred"
                                    aria-label={`Renamed to ${v.transferredToName}`}
                                    title={`Renamed to "${v.transferredToName}". Open the new component instead.`}
                                  >
                                    <Code2 size={12} />
                                  </span>
                                ) : versionNotebookStatus === 'loading' ? (
                                  <span
                                    className="px-editor__node-icon px-editor__node-icon--loading"
                                    title={`Opening notebook for ${component.name} ${v.version}`}
                                    aria-label={`Opening notebook for ${component.name} ${v.version}`}
                                  >
                                    <Loader2 size={14} className="px-spin" />
                                  </span>
                                ) : versionNotebookStatus === 'running' ? (
                                  <button
                                    type="button"
                                    className="px-editor__node-icon px-editor__node-icon--running"
                                    title={`Open notebook tab for ${component.name} ${v.version}`}
                                    aria-label={`Open notebook tab for ${component.name} ${v.version}`}
                                    onClick={e => { e.stopPropagation(); notebookWindowsRef.current[versionKey]?.focus(); }}
                                  >
                                    <Code2 size={12} />
                                  </button>
                                ) : (
                                  <button
                                    type="button"
                                    className="px-editor__node-icon"
                                    title={component.category === 'px' ? `View notebook for ${component.name} ${v.version}` : `Open notebook for ${component.name} ${v.version}`}
                                    aria-label={component.category === 'px' ? `View notebook for ${component.name} ${v.version}` : `Open notebook for ${component.name} ${v.version}`}
                                    onClick={e => { e.stopPropagation(); requestComponentNotebook(component, v); }}
                                  >
                                    <Code2 size={12} />
                                  </button>
                                )}
                                <div className="px-table__actions">
                                  <button
                                    type="button"
                                    className="px-icon-btn"
                                    title={`Clone ${component.name}`}
                                    aria-label={`Clone ${component.name}`}
                                    disabled={component.simulation}
                                    onClick={e => handleCloneComponent(component, e)}
                                  >
                                    <Copy size={16} />
                                  </button>
                                  <button
                                    type="button"
                                    className="px-icon-btn"
                                    title={`Delete ${component.name}`}
                                    aria-label={`Delete ${component.name}`}
                                    disabled={!component.simulation}
                                    onClick={e => handleDeleteClick(component, e)}
                                  >
                                    <Trash2 size={16} />
                                  </button>
                                </div>
                              </div>
                            </td>
                          </tr>
                        );
                      })}
                    </Fragment>
                  );
                })}
              </tbody>
            </table>
            {visibleComponents.length === 0 && (
              <div className="px-empty-state">No components match your search.</div>
            )}
          </div>

          <div className="px-pagination">
            <div className="px-pagination__rows">
              <select value={pageSize} onChange={e => { setPageSize(Number(e.target.value)); setCurrentPage(1); }}>
                {PAGE_SIZE_OPTIONS.map(size => <option key={size} value={size}>{size}</option>)}
              </select>
              Items per page
            </div>

            <div className="px-pagination__pages">
              <button type="button" className="px-page-btn" disabled={currentPage === 1} onClick={() => goToPage(currentPage - 1)}>
                <ChevronLeft size={14} /> Prev
              </button>
              {Array.from({ length: totalPages }, (_, i) => i + 1).map(page => (
                <button
                  key={page}
                  type="button"
                  className={`px-page-btn${page === currentPage ? ' px-page-btn--active' : ''}`}
                  onClick={() => goToPage(page)}
                >
                  {page}
                </button>
              ))}
              <button type="button" className="px-page-btn" disabled={currentPage === totalPages} onClick={() => goToPage(currentPage + 1)}>
                Next <ChevronRight size={14} />
              </button>
            </div>
          </div>
        </div>
      </div>

      {pendingDelete && (
        <ConfirmDeleteModal
          title="Delete component"
          description={`Are you sure you want to delete "${pendingDelete.name}"? This action cannot be undone.`}
          onCancel={() => setPendingDelete(null)}
          onConfirm={confirmDelete}
        />
      )}

      {newComponentOpen && (
        <NewComponentModal
          existingNames={components.map(c => c.name)}
          cloneFrom={cloneSource ? cloneCandidateFor(cloneSource) : null}
          cloneCandidates={cloneSource ? [] : components.filter(c => !c.deprecated).map(cloneCandidateFor)}
          onCancel={() => { setNewComponentOpen(false); setCloneSource(null); }}
          onCreate={handleCreateComponent}
        />
      )}

      {notebookModal}
    </div>
  );
}
