import { useState } from 'react';
import { ChevronLeft, Code2, Loader2 } from 'lucide-react';

import AppSidebar from './AppSidebar';
import { ConfigCodeBlock, getAiYamlTemplate } from './PipelineEditorPage';
import { buildSchemaYaml, SchemaCodeBlock } from './SimulationComponentDetailPage';
import './PipelinesListPage.css';
import './PipelineEditorPage.css';
import './SimulationComponentDetailPage.css';

function categoryLabel(component) {
  return component.category === 'px' ? 'PX' : 'Custom';
}

export default function AiComponentDetailPage({ component, userName, onNavigate, onBack, notebookStatus, onConnectNotebook, onFocusNotebook }) {
  const [activeSchemaTab, setActiveSchemaTab] = useState('input');
  const latest = component.versions[0];
  const yamlTemplate = getAiYamlTemplate(component.name);
  const detail = component.detail || {};
  const inputFields = detail.inputFields || [];
  const outputFields = detail.outputFields || [];

  return (
    <div className="px-pipelines">
      <AppSidebar activeItem="components" onNavigate={onNavigate} userName={userName} />

      <div className="px-pipelines__main">
        <header className="px-pipelines__header">
          <div className="px-sim-detail__header-left">
            <button type="button" className="px-editor__back" aria-label="Back" title="Back" onClick={onBack}>
              <ChevronLeft size={16} />
            </button>
            <h1 className="px-pipelines__title">{component.name}</h1>
          </div>
          <div className="px-pipelines__header-actions">
            <button
              type="button"
              className="px-pipelines__new-btn"
              title={notebookStatus === 'running' ? 'Open notebook tab' : 'Connect to Notebook'}
              disabled={notebookStatus === 'loading'}
              onClick={() => (notebookStatus === 'running' ? onFocusNotebook() : onConnectNotebook())}
            >
              {notebookStatus === 'loading' ? <Loader2 size={14} className="px-spin" /> : <Code2 size={14} />}
              {notebookStatus === 'running' ? 'Open Notebook' : 'Connect to Notebook'}
            </button>
          </div>
        </header>

        <div className="px-sim-detail__body">
          <div className="px-sim-detail__main">
            <section>
              <h2 className="px-sim-detail__section-title">Component Details</h2>
              <div className="px-sim-detail__grid">
                <div>
                  <div className="px-editor__field">
                    <span className="px-editor__field-label">Display Name</span>
                    <div className="px-editor__field-value">{component.name}</div>
                  </div>
                  <div className="px-editor__field">
                    <span className="px-editor__field-label">Category</span>
                    <div className="px-editor__field-value">{categoryLabel(component)}</div>
                  </div>
                </div>
                <div>
                  <div className="px-editor__field">
                    <span className="px-editor__field-label">Latest Version</span>
                    <div className="px-editor__field-value">{latest.version}</div>
                  </div>
                  <div className="px-editor__field">
                    <span className="px-editor__field-label">Compute Profile</span>
                    <div className="px-editor__field-value">{latest.computeProfile || '--'}</div>
                  </div>
                </div>
              </div>
              <div className="px-editor__field">
                <span className="px-editor__field-label">Description</span>
                <div className="px-editor__field-value">{component.description || '--'}</div>
              </div>
            </section>

            <section>
              <h2 className="px-sim-detail__section-title">Schemas</h2>
              <div className="px-sim-detail__schema-tabs">
                <button
                  type="button"
                  className={`px-sim-detail__schema-tab${activeSchemaTab === 'input' ? ' px-sim-detail__schema-tab--active' : ''}`}
                  onClick={() => setActiveSchemaTab('input')}
                >
                  Input schema
                </button>
                <button
                  type="button"
                  className={`px-sim-detail__schema-tab${activeSchemaTab === 'output' ? ' px-sim-detail__schema-tab--active' : ''}`}
                  onClick={() => setActiveSchemaTab('output')}
                >
                  Output schema
                </button>
              </div>
              <SchemaCodeBlock yaml={buildSchemaYaml(activeSchemaTab === 'input' ? inputFields : outputFields)} />
            </section>
          </div>

          <div className="px-sim-detail__side">
            <h2 className="px-sim-detail__section-title">Configuration</h2>
            <div className="px-sim-detail__side-subtitle">{component.name}</div>
            {yamlTemplate ? (
              <ConfigCodeBlock code={yamlTemplate} />
            ) : (
              <div className="px-editor__tab-empty">No configuration yet.</div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
