import { useState } from 'react';
import { X } from 'lucide-react';
import './ConfirmDeleteModal.css';
import './NewPipelineModal.css';

export default function RunPipelineFormModal({ onCancel, onRun, defaultRunName = 'Demo 1', existingStudies = [] }) {
  const [runName, setRunName] = useState(defaultRunName);
  const [studyName, setStudyName] = useState('');
  const [studyMenuOpen, setStudyMenuOpen] = useState(false);
  const [description, setDescription] = useState('');
  const [runScope, setRunScope] = useState('modified');

  const canRun = runName.trim() && studyName.trim();
  const filteredStudies = existingStudies.filter(name => name.toLowerCase().includes(studyName.trim().toLowerCase()));

  function handleRun() {
    if (!canRun) return;
    onRun({ runName: runName.trim(), studyName: studyName.trim(), description: description.trim(), runScope });
  }

  function selectStudy(name) {
    setStudyName(name);
    setStudyMenuOpen(false);
  }

  return (
    <div className="px-modal-overlay" onClick={onCancel}>
      <div className="px-modal px-modal--form" onClick={e => e.stopPropagation()}>
        <button type="button" className="px-modal__close" aria-label="Close" onClick={onCancel}>
          <X size={18} />
        </button>
        <h2 className="px-modal__title">Run pipeline</h2>
        <p className="px-modal__subtitle">Run all components in the pipeline</p>

        <div className="px-field">
          <label className="px-field__label" htmlFor="run-pipeline-name">
            Run Name <span className="px-field__required">*</span>
          </label>
          <input
            id="run-pipeline-name"
            type="text"
            className="px-field__input"
            placeholder="Enter a run name"
            value={runName}
            onChange={e => setRunName(e.target.value)}
            autoFocus
          />
        </div>

        <div className="px-field">
          <label className="px-field__label" htmlFor="run-study-name">
            Experiment Name <span className="px-field__required">*</span>
          </label>
          <div className="px-clone-search">
            <input
              id="run-study-name"
              type="text"
              className="px-field__input"
              placeholder="Enter or select a study name"
              autoComplete="off"
              value={studyName}
              onChange={e => { setStudyName(e.target.value); setStudyMenuOpen(true); }}
              onFocus={() => setStudyMenuOpen(true)}
              onBlur={() => setStudyMenuOpen(false)}
            />
            {studyMenuOpen && (
              <div className="px-clone-search__menu">
                {filteredStudies.length === 0 ? (
                  <div className="px-clone-search__empty">No matching studies — this will create a new one</div>
                ) : filteredStudies.map(name => (
                  <button
                    key={name}
                    type="button"
                    className={`px-clone-search__item${name === studyName ? ' px-clone-search__item--active' : ''}`}
                    onMouseDown={e => e.preventDefault()}
                    onClick={() => selectStudy(name)}
                  >
                    {name}
                  </button>
                ))}
              </div>
            )}
          </div>
        </div>

        <div className="px-field">
          <label className="px-field__label" htmlFor="run-pipeline-description">
            Run Description
          </label>
          <textarea
            id="run-pipeline-description"
            className="px-field__textarea"
            placeholder="Describe this run (optional)"
            value={description}
            onChange={e => setDescription(e.target.value)}
          />
        </div>

        <div className="px-field">
          <label className="px-field__label">Run scope</label>
          <div className="px-radio-row">
            <label className="px-radio-option">
              <input
                type="radio"
                name="run-scope"
                checked={runScope === 'modified'}
                onChange={() => setRunScope('modified')}
              />
              Run only modified/changed components
            </label>
            <label className="px-radio-option">
              <input
                type="radio"
                name="run-scope"
                checked={runScope === 'all'}
                onChange={() => setRunScope('all')}
              />
              Run full pipeline
            </label>
          </div>
        </div>

        <div className="px-modal__actions">
          <button type="button" className="px-modal__btn px-modal__btn--cancel" onClick={onCancel}>
            Cancel
          </button>
          <button
            type="button"
            className="px-modal__btn px-modal__btn--primary"
            disabled={!canRun}
            onClick={handleRun}
          >
            Run
          </button>
        </div>
      </div>
    </div>
  );
}
