function isAiYamlConfigurableComponentNode(node) {
  return Boolean(AI_YAML_TEMPLATES[node.name]);
}

export function getAiYamlTemplate(name) {
  return AI_YAML_TEMPLATES[name] || '';
}

function getAiYamlValue(node) {
  return node.config?.configYaml ?? node.configYaml ?? AI_YAML_TEMPLATES[node.name] ?? '';
}

function getYamlSyntaxError(yamlText) {
  if (!yamlText.trim()) return null;
  try {
    loadYaml(yamlText);
    return null;
  } catch (err) {
    const line = err.mark ? err.mark.line + 1 : null;
    return line ? `Line ${line}: ${err.reason || err.message}` : (err.reason || err.message);
  }
}

function isNodeReadyToRun(node) {
  if (isCadComponentNode(node)) {
    return (node.config?.sourceFile || '').trim() !== '';
  }
  if (isSimulationComponentName(node.name)) {
    return true;
  }
  if (isAiYamlConfigurableComponentNode(node)) {
    const value = getAiYamlValue(node);
    return value.trim() !== '' && !getYamlSyntaxError(value);
  }
  return null;
}

function allNodesReadyToRun(nodes) {
  return nodes.every(node => {
    if (node.isGroup) {
      return (node.children || []).every(child => isNodeReadyToRun(child) !== false);
    }
    return isNodeReadyToRun(node) !== false;
  });
}
