function getSimComponentDescription(name) {
  return `${name} component used in this study.`;
}

function getAiComponentDescription(name) {
  return `${name} component used in this pipeline.`;
}

function isCadComponentNode(node) {
  return CAD_COMPONENTS.some(c => c.name === node.name);
}

function isSimulationComponentName(name) {
  return CAD_COMPONENTS.some(c => c.name === name) || MESHING_COMPONENTS.some(c => c.name === name) || SOLVING_COMPONENTS.some(c => c.name === name);
}

function getCadComponentDescription(name) {
  const versionMatch = name.match(/v?[\d.]+$/i);
  const version = versionMatch ? versionMatch[0] : '';
  if (name.startsWith('FreeCAD')) return `FreeCAD version ${version} for 3D parametric modeling application`;
  if (name.startsWith('NX Exporter')) return `Siemens NX Exporter version ${version} for CAD export operations`;
  if (name.startsWith('NX')) return `Siemens NX version ${version} for CAD operations`;
  if (name.startsWith('nTop')) return `nTop version ${version} for implicit, field-driven modeling`;
  return `${name} component for CAD operations`;
}

function getComponentDescription(name) {
  if (CAD_COMPONENTS.some(c => c.name === name)) return getCadComponentDescription(name);
  if (isSimulationComponentName(name)) return getSimComponentDescription(name);
  return getAiComponentDescription(name);
}

