const STARTER_CODE_BY_KEYWORD = [
  {
    keyword: 'importer',
    code: name => `# ${name}

import os

def run(inputs):
    """Load raw simulation input files from the given path."""
    file_path = inputs.path
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"No input found at {file_path}")

    print(f"Loading input data from {file_path}")
    with open(file_path, "rb") as f:
        raw_data = f.read()

    return {"raw_data": raw_data, "source": file_path}
`,
  },
  {
    keyword: 'preprocess',
    code: name => `# ${name}

import numpy as np

def run(inputs):
    """Clean and normalize the raw data before modeling."""
    raw_data = inputs.raw_data
    array = np.asarray(raw_data)
    normalized = (array - array.mean()) / (array.std() + 1e-8)

    return {"processed_data": normalized}
`,
  },
  {
    keyword: 'split',
    code: name => `# ${name}

def run(inputs, train_ratio=0.8):
    """Split processed data into train and test sets."""
    data = inputs.processed_data
    split_index = int(len(data) * train_ratio)

    return {"train": data[:split_index], "test": data[split_index:]}
`,
  },
  {
    keyword: 'model',
    code: name => `# ${name}

def run(inputs):
    """Fit a model on the training set and return predictions."""
    train = inputs.train
    test = inputs.test

    model = fit_model(train)
    predictions = model.predict(test)

    return {"model": model, "predictions": predictions}


def fit_model(train_data):
    ...
`,
  },
  {
    keyword: 'evaluat',
    code: name => `# ${name}

def run(inputs):
    """Compute evaluation metrics for the model's predictions."""
    predictions = inputs.predictions
    test = inputs.test

    error = compute_error(predictions, test)
    return {"mean_error": error}


def compute_error(predictions, test_data):
    ...
`,
  },
  {
    keyword: 'optimis',
    code: name => `# ${name}

def run(inputs, iterations=50):
    """Search for the best configuration using the evaluation metric."""
    best_config, best_score = None, None

    for step in range(iterations):
        config = propose_config(step)
        score = evaluate_config(config, inputs)
        if best_score is None or score < best_score:
            best_config, best_score = config, score

    return {"best_config": best_config, "best_score": best_score}


def propose_config(step):
    ...


def evaluate_config(config, inputs):
    ...
`,
  },
];

export function getStarterCode(componentName, template) {
  const lookupName = (template || componentName || '').toLowerCase();
  const match = STARTER_CODE_BY_KEYWORD.find(entry => lookupName.includes(entry.keyword));
  if (match) return match.code(componentName);
  return `# ${componentName}\n\ndef run(inputs):\n    ...\n`;
}

function logTimestamp(offsetSeconds) {
  const base = Date.UTC(2026, 6, 9, 10, 23, 9, 204);
  return new Date(base + offsetSeconds * 1000).toISOString().replace('Z', '+00:00');
}

