function getMockLogLines(componentName, template) {
  const lookupName = (template || componentName || '').toLowerCase();
  const match = LOG_TEMPLATES_BY_KEYWORD.find(entry => lookupName.includes(entry.keyword));
  const bodyLines = match ? match.lines(componentName) : [
    { level: 'debug', text: 'DEBUG: Script is loading...' },
    { level: 'info', text: `INFO: Running ${componentName}` },
    { level: 'info', text: 'INFO: Process complete' },
  ];

  const separator = '='.repeat(80);
  return [
    { level: 'info', text: separator },
    { level: 'info', text: `[${logTimestamp(0)}] Starting subprocess` },
    { level: 'info', text: separator },
    ...bodyLines,
  ];
}

