function CadConfigListField({ label, values, onChange, addLabel, removeIcon: RemoveIcon = Trash2, showGrip, help }) {
  function updateAt(i, value) {
    onChange(values.map((v, idx) => (idx === i ? value : v)));
  }
  function removeAt(i) {
    onChange(values.filter((_, idx) => idx !== i));
  }
  function add() {
    onChange([...values, '']);
  }
  return (
    <div className="px-cad-config__field">
      <div className="px-cad-config__field-label-row">
        <span className="px-cad-config__field-label">{label}</span>
        <Link2 size={14} className="px-cad-config__link-icon" />
      </div>
      {values.map((value, i) => (
        <div className="px-cad-config__row" key={i}>
          {showGrip && <GripVertical size={14} className="px-cad-config__grip" />}
          <input
            type="text"
            className="px-cad-config__input"
            value={value}
            onChange={e => updateAt(i, e.target.value)}
          />
          <button type="button" className="px-icon-btn" aria-label={`Remove ${label}`} title={`Remove ${label}`} onClick={() => removeAt(i)}>
            <RemoveIcon size={14} />
          </button>
        </div>
      ))}
      <button type="button" className={`px-cad-config__add-btn${!showGrip ? ' px-cad-config__add-btn--plus' : ''}`} onClick={add}>
        {!showGrip && <Plus size={14} />}
        {addLabel}
      </button>
      <p className="px-cad-config__help">{help}</p>
    </div>
  );
}

