export default function PipelineEditorPage({ pipeline, userName, onBack, onNavigate, onDeletePipeline, onSaveCanvas, onSaveAndRun }) {
  const [detailsOpen, setDetailsOpen] = useState(true);
  const [moreMenuOpen, setMoreMenuOpen] = useState(false);
  const [canvasNodes, setCanvasNodes] = useState(pipeline.canvasNodes || []);
  const [isDirty, setIsDirty] = useState(false);
  const [openVersionMenuNodeId, setOpenVersionMenuNodeId] = useState(null);
  const { containerRef: canvasFlowRef, setNodeRef, connectors } = useNodeConnectors(canvasNodes.map(n => n.id));
  const [flowDirection, setFlowDirection] = useState('horizontal');
  const [showUnsavedModal, setShowUnsavedModal] = useState(false);
  const [dragOver, setDragOver] = useState(false);
  const [notebookNode, setNotebookNode] = useState(null);
  const [newComponentOpen, setNewComponentOpen] = useState(false);
  const [sharedComponents, setSharedComponents] = useState(INITIAL_SHARED_COMPONENTS);
  const [selectedNodeId, setSelectedNodeId] = useState(null);
  const [detailsWidth, setDetailsWidth] = useState(300);
  const [nodeMenu, setNodeMenu] = useState(null);

  const { notebookWindowsRef, notebookPollRef } = useAppData();
  const resizeDragging = useRef(false);
  const resizeStartX = useRef(0);
  const resizeStartWidth = useRef(0);
  const groupFrameRefs = useRef({});

  function findNodeById(id) {
    for (const n of canvasNodes) {
      if (n.id === id) return n;
      if (n.isGroup) {
        const child = (n.children || []).find(c => c.id === id);
        if (child) return child;
      }
    }
    return null;
  }

  const selectedNode = selectedNodeId ? findNodeById(selectedNodeId) : null;

  useEffect(() => {
    const polls = notebookPollRef.current;
    return () => {
      Object.values(polls).forEach(clearInterval);
    };
  }, [notebookPollRef]);

  useEffect(() => {
    function handleNotebookMessage(event) {
      if (event.origin !== window.location.origin) return;
      if (event.data?.type === 'px-notebook-code-update') {
        const { nodeId, code } = event.data;
        setCanvasNodes(prev => prev.map(n => (n.id === nodeId ? { ...n, code, updatedAt: 'Just now' } : n)));
        setIsDirty(true);
      } else if (event.data?.type === 'px-notebook-settings-update') {
        const { nodeId, computeProfile } = event.data;
        setCanvasNodes(prev => prev.map(n => (n.id === nodeId ? { ...n, computeProfile, updatedAt: 'Just now' } : n)));
        setIsDirty(true);
      }
    }
    window.addEventListener('message', handleNotebookMessage);
    return () => window.removeEventListener('message', handleNotebookMessage);
  }, []);

  function watchNotebookWindow(nodeId, win) {
    if (!win) return;
    if (notebookPollRef.current[nodeId]) clearInterval(notebookPollRef.current[nodeId]);
    notebookPollRef.current[nodeId] = setInterval(() => {
      if (win.closed) {
        clearInterval(notebookPollRef.current[nodeId]);
        delete notebookPollRef.current[nodeId];
        delete notebookWindowsRef.current[nodeId];
        setCanvasNodes(prev => prev.map(n => (n.id === nodeId ? { ...n, notebookStatus: undefined } : n)));
      }
    }, NOTEBOOK_CLOSE_POLL_MS);
  }

  function focusNotebookWindow(nodeId) {
    const win = notebookWindowsRef.current[nodeId];
    if (win && !win.closed) {
      win.focus();
    } else {
      delete notebookWindowsRef.current[nodeId];
      setCanvasNodes(prev => prev.map(n => (n.id === nodeId ? { ...n, notebookStatus: undefined } : n)));
    }
  }

  // Re-attach close-detection whenever this page (re)mounts - e.g. toggling edit/view
  // mode or navigating away and back unmounts/remounts this component, which clears
  // the previous instance's polling interval (see cleanup below) even though the
  // tracked Window reference itself lives on in AppDataContext and stays valid.
  useEffect(() => {
    canvasNodes.forEach(node => {
      if (node.notebookStatus !== 'running' && node.notebookStatus !== 'loading') return;
      const win = notebookWindowsRef.current[node.id];
      if (win && !win.closed) {
        watchNotebookWindow(node.id, win);
      } else {
        delete notebookWindowsRef.current[node.id];
        setCanvasNodes(prev => prev.map(n => (n.id === node.id ? { ...n, notebookStatus: undefined } : n)));
      }
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  function handleResizeMouseDown(e) {
    e.preventDefault();
    resizeDragging.current = true;
    resizeStartX.current = e.clientX;
    resizeStartWidth.current = detailsWidth;
  }

  function handleBodyMouseMove(e) {
    if (!resizeDragging.current) return;
    const dx = e.clientX - resizeStartX.current;
    setDetailsWidth(Math.min(560, Math.max(260, resizeStartWidth.current - dx)));
  }

  function handleBodyMouseUp() {
    resizeDragging.current = false;
  }

  function handleDragStartItem(e, name) {
    e.dataTransfer.setData('text/plain', name);
    e.dataTransfer.effectAllowed = 'copy';
  }

  function addNodeToCanvas(name, template) {
    const isGroup = GROUP_COMPONENT_NAMES.includes(name);
    setCanvasNodes(prev => [
      ...prev,
      isGroup
        ? { id: `${name}-${prev.length}-${Math.random().toString(36).slice(2, 8)}`, name, isGroup: true, children: [], createdAt: 'Just now', updatedAt: 'Just now' }
        : {
            id: `${name}-${prev.length}-${Math.random().toString(36).slice(2, 8)}`,
            name,
            template,
            version: getVersionsFor(name)[0],
            description: getComponentDescription(name),
            createdAt: 'Just now',
            updatedAt: 'Just now',
          },
    ]);
    setIsDirty(true);
  }

  function addChildToGroup(groupId, name) {
    const child = {
      id: `${name}-${Math.random().toString(36).slice(2, 8)}`,
      name,
      version: getVersionsFor(name)[0],
      description: getComponentDescription(name),
      createdAt: 'Just now',
      updatedAt: 'Just now',
    };
    setCanvasNodes(prev => prev.map(n => (n.id === groupId ? { ...n, children: [...(n.children || []), child] } : n)));
    setIsDirty(true);
  }

  function findGroupAtPoint(x, y) {
    for (const node of canvasNodes) {
      if (!node.isGroup) continue;
      const el = groupFrameRefs.current[node.id];
      if (!el) continue;
      const r = el.getBoundingClientRect();
      if (x >= r.left && x <= r.right && y >= r.top && y <= r.bottom) return node.id;
    }
    return null;
  }

  function updateNodeById(prev, nodeId, updater) {
    return prev.map(n => {
      if (n.id === nodeId) return updater(n);
      if (n.isGroup && n.children?.some(c => c.id === nodeId)) {
        return { ...n, children: n.children.map(c => (c.id === nodeId ? updater(c) : c)) };
      }
      return n;
    });
  }

  function handleVersionSelect(nodeId, version) {
    setCanvasNodes(prev => updateNodeById(prev, nodeId, n => ({ ...n, version })));
    setIsDirty(true);
    setOpenVersionMenuNodeId(null);
  }

  function isAiComponentNode(node) {
    return PX_COMPONENTS.some(c => c.name === node.name) || sharedComponents.some(c => c.name === node.name);
  }

  function handleNodeContextMenu(e, node, parentGroupId = null) {
    e.preventDefault();
    e.stopPropagation();
    setSelectedNodeId(node.id);
    setNodeMenu({ nodeId: node.id, x: e.clientX, y: e.clientY, parentGroupId, canClone: !parentGroupId && isAiComponentNode(node) });
  }

  function handleCloneNode(nodeId) {
    setCanvasNodes(prev => {
      const node = prev.find(n => n.id === nodeId);
      if (!node) return prev;
      const clone = { ...node, id: `${node.name}-${prev.length}-${Math.random().toString(36).slice(2, 8)}`, createdAt: 'Just now', updatedAt: 'Just now' };
      return [...prev, clone];
    });
    setIsDirty(true);
    setNodeMenu(null);
  }

  function handleRemoveNode(nodeId, parentGroupId = null) {
    if (parentGroupId) {
      setCanvasNodes(prev => prev.map(n => (n.id === parentGroupId ? { ...n, children: (n.children || []).filter(c => c.id !== nodeId) } : n)));
    } else {
      setCanvasNodes(prev => prev.filter(n => n.id !== nodeId));
    }
    setIsDirty(true);
    setNodeMenu(null);
    setSelectedNodeId(prev => (prev === nodeId ? null : prev));
  }

  function handleCanvasDrop(e) {
    e.preventDefault();
    setDragOver(false);
    const name = e.dataTransfer.getData('text/plain');
    if (!name) return;
    if (!GROUP_COMPONENT_NAMES.includes(name)) {
      const groupId = findGroupAtPoint(e.clientX, e.clientY);
      if (groupId) {
        addChildToGroup(groupId, name);
        return;
      }
    }
    addNodeToCanvas(name);
  }

  function handleSave() {
    onSaveCanvas?.(canvasNodes);
    setIsDirty(false);
  }

  function handleSaveAndRun() {
    onSaveCanvas?.(canvasNodes);
    setIsDirty(false);
    onSaveAndRun?.(canvasNodes);
  }

  function handleBackClick() {
    if (isDirty) {
      setShowUnsavedModal(true);
    } else {
      onBack();
    }
  }

  function openNotebookTab(node) {
    const fileName = `${node.name.toLowerCase().replace(/\s+/g, '_')}.py`;
    const html = getJupyterMockHtml({
      fileName,
      initialCode: node.code ?? getStarterCode(node.name, node.template),
      nodeId: node.id,
      pipelineName: pipeline.name,
      componentName: node.name,
      computeProfile: node.computeProfile || 'Default',
      enableVersioning: true,
    });
    const blobUrl = URL.createObjectURL(new Blob([html], { type: 'text/html' }));
    const win = window.open(blobUrl, '_blank');
    if (!win) {
      URL.revokeObjectURL(blobUrl);
      return null;
    }
    win.focus();
    return win;
  }

  function connectNotebook(node, profile) {
    const nodeId = node.id;
    const win = openNotebookTab(node);
    notebookWindowsRef.current[nodeId] = win;
    watchNotebookWindow(nodeId, win);
    setCanvasNodes(prev => prev.map(n => (
      n.id === nodeId ? { ...n, computeProfile: profile, notebookStatus: 'loading', updatedAt: 'Just now' } : n
    )));
    setIsDirty(true);
    setTimeout(() => {
      setCanvasNodes(prev => prev.map(n => (
        n.id === nodeId && n.notebookStatus === 'loading' ? { ...n, notebookStatus: 'running' } : n
      )));
    }, NOTEBOOK_LOAD_DELAY_MS);
  }

  return (
    <div className="px-editor">
      <header className="px-editor__topbar">
        <div className="px-editor__topbar-left">
          <div className="px-editor__brand">
            <span className="px-editor__logo"><LogoMarkIcon /></span>
            <button type="button" className="px-editor__back" onClick={handleBackClick} aria-label="Back" title="Back">
              <ChevronLeft size={16} />
            </button>
          </div>
          <h1 className="px-editor__title">{pipeline.name}</h1>
        </div>
        <div className="px-editor__topbar-right">
          <div className="px-new-menu-wrap">
            <button
              type="button"
              className="px-icon-btn"
              title="More options"
              aria-label="More options"
              onClick={() => setMoreMenuOpen(o => !o)}
            >
              <MoreHorizontal size={18} />
            </button>
            {moreMenuOpen && (
              <>
                <div className="px-menu-overlay" onClick={() => setMoreMenuOpen(false)} />
                <div className="px-new-menu">
                  {!detailsOpen && !selectedNode && (
                    <button
                      type="button"
                      onClick={() => { setDetailsOpen(true); setSelectedNodeId(null); setMoreMenuOpen(false); }}
                    >
                      Show pipeline details
                    </button>
                  )}
                  <button type="button" onClick={() => setMoreMenuOpen(false)}>
                    View pipeline runs
                  </button>
                  <button type="button" onClick={() => { setMoreMenuOpen(false); onDeletePipeline?.(); }}>
                    Delete pipeline
                  </button>
                </div>
              </>
            )}
          </div>
          <button type="button" className="px-editor__btn px-editor__btn--secondary" onClick={() => { handleSave(); onBack(); }}>
            Save &amp; Exit
          </button>
          <button
            type="button"
            className="px-editor__btn px-editor__btn--primary"
            disabled={!allNodesReadyToRun(canvasNodes)}
            title={allNodesReadyToRun(canvasNodes) ? undefined : 'All components must pass validation before running'}
            onClick={handleSaveAndRun}
          >
            Save &amp; Run
          </button>
        </div>
      </header>

      <div
        className="px-editor__body"
        onMouseMove={handleBodyMouseMove}
        onMouseUp={handleBodyMouseUp}
      >
        <AppSidebar activeItem="pipelines" onNavigate={onNavigate} userName={userName} showLogo={false} defaultCollapsed />

        <div className="px-editor__panel">
          <button type="button" className="px-editor__create-btn" onClick={() => setNewComponentOpen(true)}>
            Create new component
          </button>
          <label className="px-search">
            <Search size={16} />
            <input type="text" placeholder="Search components" />
          </label>
          <ComponentGroup title="Controllers">
            <ComponentSection items={CONTROLLER_COMPONENTS} onDragStartItem={handleDragStartItem} />
          </ComponentGroup>
          <ComponentGroup title="Simulation">
            <ComponentSection title="CAD" items={CAD_COMPONENTS} onDragStartItem={handleDragStartItem} defaultIcon={Package} />
            <ComponentSection title="Meshing" items={MESHING_COMPONENTS} onDragStartItem={handleDragStartItem} defaultIcon={Grid3x3} />
            <ComponentSection title="Solving" items={SOLVING_COMPONENTS} onDragStartItem={handleDragStartItem} defaultIcon={Sigma} />
          </ComponentGroup>
          <ComponentGroup title="Model training">
            <ComponentSection title="PX Components" items={PX_COMPONENTS} onDragStartItem={handleDragStartItem} />
            <ComponentSection title="Custom Components" items={sharedComponents} onDragStartItem={handleDragStartItem} />
          </ComponentGroup>
        </div>

        <div
          className={`px-editor__canvas${dragOver ? ' px-editor__canvas--drag-over' : ''}`}
          onDragOver={e => { e.preventDefault(); setDragOver(true); }}
          onDragLeave={() => setDragOver(false)}
          onDrop={handleCanvasDrop}
          onClick={() => setSelectedNodeId(null)}
        >
          <button
            type="button"
            className="px-editor__flow-toggle"
            title={flowDirection === 'horizontal' ? 'Switch to vertical layout' : 'Switch to horizontal layout'}
            aria-label={flowDirection === 'horizontal' ? 'Switch to vertical layout' : 'Switch to horizontal layout'}
            onClick={e => { e.stopPropagation(); setFlowDirection(d => (d === 'horizontal' ? 'vertical' : 'horizontal')); }}
          >
            {flowDirection === 'horizontal' ? <Rows3 size={16} /> : <Columns3 size={16} />}
          </button>
          {canvasNodes.length === 0 ? (
            <div className="px-editor__canvas-empty">Drag a component here to start building your pipeline</div>
          ) : (
            <div className={`px-editor__canvas-flow${flowDirection === 'vertical' ? ' px-editor__canvas-flow--vertical' : ''}`} ref={canvasFlowRef}>
              <FlowConnectors connectors={connectors} direction={flowDirection} />
              {canvasNodes.map((node) => (
                <div className="px-editor__node-wrap" key={node.id} ref={setNodeRef(node.id)}>
                  {node.isGroup ? (
                    <div
                      className={`px-editor__group-frame${selectedNodeId === node.id ? ' px-editor__group-frame--selected' : ''}`}
                      ref={el => { groupFrameRefs.current[node.id] = el; }}
                      onClick={e => { e.stopPropagation(); setSelectedNodeId(node.id); }}
                      onContextMenu={e => handleNodeContextMenu(e, node)}
                    >
                      {(() => {
                        const ControllerIcon = getControllerIcon(node.name);
                        return (
                          <span className="px-editor__group-frame__pill">
                            <ControllerIcon size={14} />
                            {node.name}
                          </span>
                        );
                      })()}
                      {(!node.children || node.children.length === 0) ? (
                        <div className="px-editor__group-frame__empty">Drag simulation components here</div>
                      ) : (
                        <div className="px-editor__group-frame__children">
                          {node.children.map((child, i) => (
                            <div key={child.id} className="px-editor__group-frame__child-wrap">
                              <div
                                className={`px-editor__group-frame__child${selectedNodeId === child.id ? ' px-editor__group-frame__child--selected' : ''}`}
                                onClick={e => { e.stopPropagation(); setSelectedNodeId(child.id); }}
                                onContextMenu={e => handleNodeContextMenu(e, child, node.id)}
                              >
                                <div className="px-editor__group-frame__child-text">
                                  <span className="px-editor__group-frame__child-name-row">
                                    {(() => {
                                      const ChildIcon = getNodeIcon(child);
                                      return (
                                        <span className="px-editor__component-icon">
                                          <ChildIcon size={12} />
                                        </span>
                                      );
                                    })()}
                                    <span className="px-editor__group-frame__child-name" title={child.name}>{child.name}</span>
                                  </span>
                                  <span className="px-editor__group-frame__child-desc" title={child.description}>{child.description}</span>
                                  <div className="px-editor__node-bottom-row">
                                    <div className="px-editor__node-version-wrap">
                                      <button
                                        type="button"
                                        className="px-editor__node-version-btn"
                                        onClick={e => { e.stopPropagation(); setOpenVersionMenuNodeId(prev => (prev === child.id ? null : child.id)); }}
                                      >
                                        {child.version || getVersionsFor(child.name)[0]}
                                        <ChevronDown size={12} />
                                      </button>
                                      {openVersionMenuNodeId === child.id && (
                                        <>
                                          <div className="px-menu-overlay" onClick={e => { e.stopPropagation(); setOpenVersionMenuNodeId(null); }} />
                                          <div className="px-editor__node-version-menu">
                                            {getVersionsFor(child.name).map(v => (
                                              <button
                                                type="button"
                                                key={v}
                                                className={`px-editor__node-version-item${v === child.version ? ' px-editor__node-version-item--active' : ''}`}
                                                onClick={e => { e.stopPropagation(); handleVersionSelect(child.id, v); }}
                                              >
                                                {v}
                                              </button>
                                            ))}
                                          </div>
                                        </>
                                      )}
                                    </div>
                                    {isNodeReadyToRun(child) !== null && (
                                      <Check
                                        size={14}
                                        className={`px-editor__node-ready-icon${isNodeReadyToRun(child) ? ' px-editor__node-icon--ready' : ''}`}
                                        aria-label={isNodeReadyToRun(child) ? `${child.name} is ready to run` : `${child.name} is missing required configuration`}
                                        title={isNodeReadyToRun(child) ? `${child.name} is ready to run` : `${child.name} is missing required configuration`}
                                      />
                                    )}
                                  </div>
                                </div>
                              </div>
                              {i < node.children.length - 1 && (
                                <div className="px-editor__group-frame__connector">
                                  <span className="px-editor__group-frame__connector-line" />
                                  <svg width="12" height="10" viewBox="0 0 12 10" className="px-editor__group-frame__connector-arrow">
                                    <path d="M1,0 L11,0 L6,9 Z" fill="var(--on-fill-subtle)" />
                                  </svg>
                                </div>
                              )}
                            </div>
                          ))}
                        </div>
                      )}
                    </div>
                  ) : (
                    <div
                      className={`px-editor__node${selectedNodeId === node.id ? ' px-editor__node--selected' : ''}`}
                      onClick={e => { e.stopPropagation(); setSelectedNodeId(node.id); }}
                      onContextMenu={e => handleNodeContextMenu(e, node)}
                    >
                      <div className="px-editor__node-header">
                        {(() => {
                          const NodeIcon = getNodeIcon(node);
                          return (
                            <span className="px-editor__component-icon">
                              <NodeIcon size={12} />
                            </span>
                          );
                        })()}
                        <span className="px-editor__node-name" title={node.name}>{node.name}</span>
                        {!isSimulationComponentName(node.name) && (
                          node.notebookStatus === 'loading' ? (
                            <span className="px-editor__node-icon px-editor__node-icon--loading">
                              <Loader2 size={14} className="px-spin" />
                            </span>
                          ) : node.notebookStatus === 'running' ? (
                            <button
                              type="button"
                              className="px-editor__node-icon px-editor__node-icon--running"
                              title={`Open notebook tab for ${node.name}`}
                              aria-label={`Open notebook tab for ${node.name}`}
                              onClick={e => { e.stopPropagation(); focusNotebookWindow(node.id); }}
                            >
                              <Code2 size={12} />
                            </button>
                          ) : (
                            <button
                              type="button"
                              className="px-editor__node-icon"
                              title={`Open notebook for ${node.name}`}
                              aria-label={`Open notebook for ${node.name}`}
                              onClick={e => { e.stopPropagation(); setNotebookNode(node); }}
                            >
                              <Code2 size={12} />
                            </button>
                          )
                        )}
                      </div>
                      {node.description && (
                        <span className="px-editor__node-desc" title={node.description}>{node.description}</span>
                      )}
                      <div className="px-editor__node-bottom-row">
                        <div className="px-editor__node-version-wrap">
                          <button
                            type="button"
                            className="px-editor__node-version-btn"
                            onClick={e => { e.stopPropagation(); setOpenVersionMenuNodeId(prev => (prev === node.id ? null : node.id)); }}
                          >
                            {node.version || getVersionsFor(node.name)[0]}
                            <ChevronDown size={12} />
                          </button>
                          {openVersionMenuNodeId === node.id && (
                            <>
                              <div className="px-menu-overlay" onClick={e => { e.stopPropagation(); setOpenVersionMenuNodeId(null); }} />
                              <div className="px-editor__node-version-menu">
                                {getVersionsFor(node.name).map(v => (
                                  <button
                                    type="button"
                                    key={v}
                                    className={`px-editor__node-version-item${v === node.version ? ' px-editor__node-version-item--active' : ''}`}
                                    onClick={e => { e.stopPropagation(); handleVersionSelect(node.id, v); }}
                                  >
                                    {v}
                                  </button>
                                ))}
                              </div>
                            </>
                          )}
                        </div>
                        {isNodeReadyToRun(node) !== null && (
                          <Check
                            size={14}
                            className={`px-editor__node-ready-icon${isNodeReadyToRun(node) ? ' px-editor__node-icon--ready' : ''}`}
                            aria-label={isNodeReadyToRun(node) ? `${node.name} is ready to run` : `${node.name} is missing required configuration`}
                            title={isNodeReadyToRun(node) ? `${node.name} is ready to run` : `${node.name} is missing required configuration`}
                          />
                        )}
                      </div>
                    </div>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>

        {nodeMenu && (
          <>
            <div className="px-menu-overlay" onClick={() => setNodeMenu(null)} />
            <div className="px-new-menu px-node-context-menu" style={{ position: 'fixed', top: nodeMenu.y, left: nodeMenu.x }}>
              {nodeMenu.canClone && (
                <button type="button" onClick={() => handleCloneNode(nodeMenu.nodeId)}>
                  Clone
                </button>
              )}
              <button type="button" onClick={() => handleRemoveNode(nodeMenu.nodeId, nodeMenu.parentGroupId)}>
                Remove
              </button>
            </div>
          </>
        )}

        {(selectedNode || detailsOpen) && (
          <div className="resize-handle-v resize-handle-v--bare" onMouseDown={handleResizeMouseDown} />
        )}

        {selectedNode ? (
          <ComponentDetailsPanel
            node={selectedNode}
            pipeline={pipeline}
            userName={userName}
            onClose={() => setSelectedNodeId(null)}
            width={detailsWidth}
            editable
            onVersionChange={version => handleVersionSelect(selectedNode.id, version)}
            onNodeConfigChange={(nodeId, key, value) => {
              setCanvasNodes(prev => updateNodeById(prev, nodeId, n => ({ ...n, config: { ...n.config, [key]: value } })));
              setIsDirty(true);
            }}
          />
        ) : detailsOpen && (
          <PipelineDetailsPanel
            pipeline={pipeline}
            userName={userName}
            onClose={() => setDetailsOpen(false)}
            width={detailsWidth}
          />
        )}
      </div>

      {notebookNode && (
        <StartNotebookModal
          notebookName={notebookNode.name}
          defaultProfile={notebookNode.computeProfile || ''}
          onCancel={() => setNotebookNode(null)}
          onStart={profile => {
            connectNotebook(notebookNode, profile);
            setNotebookNode(null);
          }}
        />
      )}

      {showUnsavedModal && (
        <UnsavedChangesModal
          onClose={() => setShowUnsavedModal(false)}
          onDiscard={() => { setShowUnsavedModal(false); onBack(); }}
          onSave={() => { handleSave(); setShowUnsavedModal(false); onBack(); }}
        />
      )}

      {newComponentOpen && (
        <NewComponentModal
          onCancel={() => setNewComponentOpen(false)}
          existingNames={[...PX_COMPONENTS, ...sharedComponents].map(c => c.name)}
          onCreate={({ name, template }) => {
            setSharedComponents(prev => [{ name, isNew: true }, ...prev]);
            addNodeToCanvas(name, template);
            setNewComponentOpen(false);
          }}
        />
      )}
    </div>
  );
}
