let runs = [...SEED_RUNS];
const listeners = new Set();

function emit() {
  listeners.forEach(fn => fn());
}

export function subscribe(listener) {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

export function getRuns() {
  return runs;
}

export function deleteRun(id) {
  runs = runs.filter(r => r.id !== id);
  emit();
}

export function cloneRun(id) {
  const source = runs.find(r => r.id === id);
  if (!source) return;
  const clone = { ...source, id: generateRunId(), runName: `${source.runName} (copy)`, startTimeLabel: 'Just now' };
  runs = [clone, ...runs];
  emit();
}

export function recordRun({ pipeline, runName, studyName, description, runScope, nodes, runType, userName }) {
  const run = {
    id: generateRunId(),
    runName,
    studyName: studyName || '--',
    description: description || '',
    runScope: runScope || 'all',
    nodes: nodes.map(n => n.name),
    runType,
    pipelineId: pipeline.id,
    pipelineName: pipeline.name,
    pipelineVersion: pipeline.version || 'v0.1',
    pipelineType: pipeline.type,
    status: 'running',
    startTimeLabel: 'Just now',
    durationSeconds: null,
    createdBy: userName,
  };
  runs = [run, ...runs];
  emit();
  setTimeout(() => {
    runs = runs.map(r => (r.id === run.id ? { ...r, status: 'success', durationSeconds: Math.round(RUN_COMPLETE_DELAY_MS / 1000) } : r));
    emit();
  }, RUN_COMPLETE_DELAY_MS);
  return run;
}
