function tile(glyph, glyphBg, glyphColor, label, action) {
  return `
    <div class="tile"${action ? ` data-action="${action}"` : ''}>
      <div class="tile-icon" style="background:${glyphBg};color:${glyphColor}">${glyph}</div>
      <div class="tile-label">${label}</div>
    </div>
  `;
}

function escapeHtml(value) {
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

