function renderSettingsModal(componentName, computeProfile) {
  const profileOptions = COMPUTE_PROFILES.includes(computeProfile)
    ? COMPUTE_PROFILES
    : [computeProfile, ...COMPUTE_PROFILES];
  const optionsHtml = profileOptions.map(profile => (
    `<option value="${escapeHtml(profile)}"${profile === computeProfile ? ' selected' : ''}>${escapeHtml(profile)}</option>`
  )).join('');

  return `
    <div class="px-nb-modal-overlay" id="px-nb-settings-overlay">
      <div class="px-nb-modal">
        <button type="button" class="px-nb-modal__close" id="px-nb-settings-close" aria-label="Close">&times;</button>
        <h2 class="px-nb-modal__title">Notebook settings</h2>
        <div class="px-nb-modal__field">
          <label for="px-nb-settings-name">Notebook Name <span class="px-nb-modal__required">*</span></label>
          <input type="text" id="px-nb-settings-name" value="${escapeHtml(componentName)}" />
        </div>
        <div class="px-nb-modal__field">
          <label for="px-nb-settings-profile">Compute profile <span class="px-nb-modal__required">*</span></label>
          <select id="px-nb-settings-profile">${optionsHtml}</select>
        </div>
        <div class="px-nb-modal__actions">
          <button type="button" class="px-nb-modal__btn px-nb-modal__btn--cancel" id="px-nb-settings-cancel">Cancel</button>
          <button type="button" class="px-nb-modal__btn px-nb-modal__btn--save" id="px-nb-settings-save">Save changes</button>
        </div>
      </div>
    </div>
  `;
}

