import { useState } from 'react';
import { X, ChevronDown } from 'lucide-react';
import { COMPUTE_PROFILES } from './computeProfiles';
import './ConfirmDeleteModal.css';
import './NewPipelineModal.css';
import './StartNotebookModal.css';

export default function StartNotebookModal({ notebookName, defaultProfile, onCancel, onStart }) {
  const [profile, setProfile] = useState(defaultProfile || '');

  return (
    <div className="px-modal-overlay" onClick={onCancel}>
      <div className="px-modal px-modal--form" onClick={e => e.stopPropagation()}>
        <button type="button" className="px-modal__close" aria-label="Close" onClick={onCancel}>
          <X size={18} />
        </button>
        <h2 className="px-modal__title">Open notebook</h2>
        <p className="px-modal__subtitle">Choose a compute profile for this notebook.</p>

        <div className="px-notebook-field">
          <span className="px-notebook-field__label">Notebook name</span>
          <div className="px-notebook-field__value">{notebookName}</div>
        </div>

        <div className="px-notebook-field">
          <label className="px-field__label px-notebook-field__label--required" htmlFor="compute-profile">
            Compute profile <span className="px-field__required">*</span>
          </label>
          <div className="px-notebook-select-wrap">
            <select
              id="compute-profile"
              className="px-notebook-select"
              value={profile}
              onChange={e => setProfile(e.target.value)}
              required
            >
              <option value="" disabled>Select profile</option>
              {COMPUTE_PROFILES.map(option => (
                <option key={option} value={option}>{option}</option>
              ))}
            </select>
            <ChevronDown size={16} className="px-notebook-select-chevron" />
          </div>
        </div>

        <div className="px-modal__actions">
          <button type="button" className="px-modal__btn px-modal__btn--cancel" onClick={onCancel}>
            Cancel
          </button>
          <button
            type="button"
            className="px-modal__btn px-modal__btn--primary"
            disabled={!profile}
            onClick={() => onStart(profile)}
          >
            Open notebook
          </button>
        </div>
      </div>
    </div>
  );
}
