import React, { useState, useMemo } from "react";
import ModelDetailModal from "./ModelDetailModal";
import { MODEL_REGISTRY, STATUS_STYLE } from "./modelRegistryData";

const FILTERS = [
  { id: "all",        label: `All (${MODEL_REGISTRY.length})` },
  { id: "production", label: `Production (${MODEL_REGISTRY.filter(m => m.status === "production").length})` },
  { id: "registered", label: `Registered (${MODEL_REGISTRY.filter(m => m.status === "registered").length})` },
  { id: "archived",   label: `Archived (${MODEL_REGISTRY.filter(m => m.status === "archived").length})` },
];

function SortBtn({ k, label, sortKey, onSort }) {
  return (
    <button onClick={() => onSort(k)} style={{
      background: "none", border: "none", cursor: "pointer", fontSize: 11, fontWeight: 600,
      color: sortKey === k ? "rgba(255,255,255,0.85)" : "rgba(170,171,177,0.5)", padding: 0, textAlign: "left",
    }}>{label}{sortKey === k ? " ↑" : ""}</button>
  );
}

export default function ModelRegistryPage({ onBack }) {
  const [filter, setFilter]     = useState("all");
  const [search, setSearch]     = useState("");
  const [sortKey, setSortKey]   = useState("name");
  const [selected, setSelected] = useState(null);

  const filtered = useMemo(() => {
    let rows = [...MODEL_REGISTRY];
    if (filter !== "all") rows = rows.filter(m => m.status === filter);
    if (search) {
      const q = search.toLowerCase();
      rows = rows.filter(m => m.name.toLowerCase().includes(q) || m.type.toLowerCase().includes(q));
    }
    rows = [...rows].sort((a, b) => {
      const av = a[sortKey], bv = b[sortKey];
      if (typeof av === "string") return av.localeCompare(bv);
      return bv - av;
    });
    return rows;
  }, [filter, search, sortKey]);

  return (
    <div style={{ position: "fixed", inset: 0, zIndex: 500, background: "#0d0f13", display: "flex", flexDirection: "column", overflow: "hidden", color: "#fff" }}>

      {/* Top bar */}
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "14px 24px", borderBottom: "1px solid #252830", flexShrink: 0, background: "#111318" }}>
        <div>
          <div style={{ fontSize: 17, fontWeight: 700, color: "#fff", marginBottom: 3 }}>Model Registry</div>
          <div style={{ fontSize: 11, fontFamily: "monospace", color: "rgba(170,171,177,0.5)" }}>
            {MODEL_REGISTRY.length} models
          </div>
        </div>
        <button onClick={onBack} style={{
          display: "flex", alignItems: "center", gap: 6,
          background: "rgba(255,255,255,0.06)", border: "1px solid #2e3035",
          borderRadius: 8, color: "rgba(255,255,255,0.65)", fontSize: 12, fontWeight: 500,
          padding: "7px 14px", cursor: "pointer",
        }}
          onMouseEnter={e => e.currentTarget.style.background = "rgba(255,255,255,0.1)"}
          onMouseLeave={e => e.currentTarget.style.background = "rgba(255,255,255,0.06)"}
        >← Back</button>
      </div>

      {/* Body */}
      <div style={{ flex: 1, overflowY: "auto", padding: "20px 24px 24px" }}>

        {/* Filter tabs + search */}
        <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap", marginBottom: 16 }}>
          {FILTERS.map(f => (
            <button key={f.id} onClick={() => setFilter(f.id)}
              style={{
                background: filter === f.id ? "rgba(255,255,255,0.1)" : "transparent",
                border: `1px solid ${filter === f.id ? "rgba(255,255,255,0.25)" : "#2e3035"}`,
                borderRadius: 20, padding: "5px 14px", fontSize: 12, fontWeight: 500,
                color: filter === f.id ? "#fff" : "rgba(170,171,177,0.55)",
                cursor: "pointer", transition: "all 0.15s",
              }}
              onMouseEnter={e => { if (filter !== f.id) { e.currentTarget.style.borderColor = "rgba(255,255,255,0.2)"; e.currentTarget.style.color = "rgba(255,255,255,0.7)"; } }}
              onMouseLeave={e => { if (filter !== f.id) { e.currentTarget.style.borderColor = "#2e3035"; e.currentTarget.style.color = "rgba(170,171,177,0.55)"; } }}
            >{f.label}</button>
          ))}
          <input value={search} onChange={e => setSearch(e.target.value)}
            placeholder="search name, type…"
            style={{
              marginLeft: "auto", background: "#161920", border: "1px solid #2e3035",
              borderRadius: 20, padding: "5px 14px", fontSize: 12, color: "#fff",
              outline: "none", fontFamily: "inherit", width: 200,
            }}
          />
        </div>

        {/* Table */}
        <div style={{ background: "#161920", border: "1px solid #252830", borderRadius: 10, overflow: "hidden" }}>
          {/* Header */}
          <div style={{
            display: "grid", gridTemplateColumns: "1.6fr 100px 90px 120px 100px 110px",
            padding: "9px 16px", borderBottom: "1px solid #252830",
            fontSize: 11, background: "#111318",
          }}>
            <SortBtn k="name"      label="Name"      sortKey={sortKey} onSort={setSortKey} />
            <SortBtn k="type"      label="Type"      sortKey={sortKey} onSort={setSortKey} />
            <SortBtn k="version"   label="Version"   sortKey={sortKey} onSort={setSortKey} />
            <span style={{ color: "rgba(170,171,177,0.5)", fontWeight: 600 }}>Status</span>
            <SortBtn k="accuracy"  label="Accuracy"  sortKey={sortKey} onSort={setSortKey} />
            <SortBtn k="updatedAt" label="Updated"   sortKey={sortKey} onSort={setSortKey} />
          </div>
          {/* Rows */}
          <div>
            {filtered.length === 0 && (
              <div style={{ padding: "20px 16px", textAlign: "center", fontSize: 12, color: "rgba(170,171,177,0.4)" }}>
                No models match "{search}"
              </div>
            )}
            {filtered.map(m => {
              const ss = STATUS_STYLE[m.status];
              return (
                <div
                  key={m.name}
                  onClick={() => setSelected(m)}
                  style={{
                    display: "grid", gridTemplateColumns: "1.6fr 100px 90px 120px 100px 110px",
                    padding: "11px 16px", borderBottom: "1px solid rgba(37,40,48,0.7)",
                    fontSize: 12.5, alignItems: "center", cursor: "pointer",
                    transition: "background 0.1s",
                  }}
                  onMouseEnter={e => e.currentTarget.style.background = "rgba(255,255,255,0.04)"}
                  onMouseLeave={e => e.currentTarget.style.background = "transparent"}
                >
                  <span style={{ color: "#fff", fontWeight: 600 }}>{m.name}</span>
                  <span style={{ color: "rgba(255,255,255,0.65)", fontFamily: "monospace" }}>{m.type}</span>
                  <span style={{ color: "rgba(255,255,255,0.65)", fontFamily: "monospace" }}>v{m.version}</span>
                  <span style={{
                    display: "inline-block", fontSize: 10, fontWeight: 600, padding: "2px 8px", borderRadius: 4,
                    background: ss.bg, color: ss.color, border: `1px solid ${ss.border}`, width: "fit-content",
                  }}>{m.status}</span>
                  <span style={{ color: "rgba(255,255,255,0.75)", fontFamily: "monospace" }}>{m.accuracy.toFixed(1)}%</span>
                  <span style={{ color: "rgba(170,171,177,0.5)", fontFamily: "monospace", fontSize: 11 }}>{m.updatedAt}</span>
                </div>
              );
            })}
          </div>
        </div>
      </div>

      {selected && <ModelDetailModal model={selected} onClose={() => setSelected(null)} />}
    </div>
  );
}
