import { X } from 'lucide-react';
import './ConfirmDeleteModal.css';

export default function ConfirmDeleteModal({ title, description, onCancel, onConfirm }) {
  return (
    <div className="px-modal-overlay" onClick={onCancel}>
      <div className="px-modal" onClick={e => e.stopPropagation()}>
        <button type="button" className="px-modal__close" aria-label="Close" onClick={onCancel}>
          <X size={18} />
        </button>
        <h2 className="px-modal__title">{title}</h2>
        <p className="px-modal__body">{description}</p>
        <div className="px-modal__actions">
          <button type="button" className="px-modal__btn px-modal__btn--cancel" onClick={onCancel}>
            Cancel
          </button>
          <button type="button" className="px-modal__btn px-modal__btn--danger" onClick={onConfirm}>
            Yes, Delete
          </button>
        </div>
      </div>
    </div>
  );
}
