import React, { useEffect } from "react";
import { X, Tag } from "lucide-react";
import { STATUS_STYLE } from "./modelRegistryData";

function DetailRow({ label, value, mono }) {
  return (
    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "10px 0", borderBottom: "1px solid #1e2128" }}>
      <span style={{ fontSize: 12, color: "rgba(170,171,177,0.55)" }}>{label}</span>
      <span style={{ fontSize: 13, color: "#fff", fontWeight: 600, fontFamily: mono ? "'Geist Mono', monospace" : "inherit" }}>{value}</span>
    </div>
  );
}

export default function ModelDetailModal({ model, onClose }) {
  useEffect(() => {
    function onKey(e) { if (e.key === "Escape") onClose?.(); }
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);

  if (!model) return null;
  const statusStyle = STATUS_STYLE[model.status];

  return (
    <div
      style={{
        position: "fixed", inset: 0, zIndex: 2000,
        background: "rgba(0,0,0,0.65)", backdropFilter: "blur(3px)",
        display: "flex", alignItems: "center", justifyContent: "center",
      }}
      onClick={e => { if (e.target === e.currentTarget) onClose?.(); }}
    >
      <div style={{
        width: 460, background: "#16191f",
        border: "1px solid #2e3035", borderRadius: 14,
        boxShadow: "0 24px 80px rgba(0,0,0,0.6)",
        display: "flex", flexDirection: "column", overflow: "hidden",
      }}>

        {/* Header */}
        <div style={{
          display: "flex", alignItems: "flex-start", justifyContent: "space-between",
          padding: "18px 20px 14px", borderBottom: "1px solid #2e3035",
        }}>
          <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
            <div style={{
              width: 34, height: 34, borderRadius: 8, flexShrink: 0,
              background: "rgba(99,102,241,0.15)", border: "1px solid rgba(99,102,241,0.25)",
              display: "flex", alignItems: "center", justifyContent: "center",
            }}>
              <Tag size={15} style={{ color: "#a5b4fc" }} />
            </div>
            <div>
              <div style={{ fontSize: 15, fontWeight: 700, color: "#fff" }}>{model.name}</div>
              <div style={{ fontSize: 11, color: "rgba(170,171,177,0.45)", fontFamily: "monospace", marginTop: 1 }}>
                {model.type} · v{model.version}
              </div>
            </div>
          </div>
          <button
            onClick={onClose}
            style={{ background: "none", border: "none", cursor: "pointer", color: "rgba(170,171,177,0.5)", padding: 4, display: "flex" }}
            onMouseEnter={e => e.currentTarget.style.color = "#fff"}
            onMouseLeave={e => e.currentTarget.style.color = "rgba(170,171,177,0.5)"}
          >
            <X size={16} />
          </button>
        </div>

        {/* Body */}
        <div style={{ padding: "18px 20px" }}>

          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 4 }}>
            <span style={{
              display: "inline-block", fontSize: 10, fontWeight: 600, padding: "2px 8px", borderRadius: 4,
              background: statusStyle.bg, color: statusStyle.color, border: `1px solid ${statusStyle.border}`,
            }}>
              {model.status}
            </span>
          </div>

          <DetailRow label="Accuracy" value={`${model.accuracy.toFixed(1)}%`} mono />
          <DetailRow label="Created by" value={model.createdBy} />
          <DetailRow label="Last updated" value={model.updatedAt} mono />

          {model.tags && model.tags.length > 0 && (
            <div style={{ paddingTop: 14 }}>
              <div style={{ fontSize: 11, fontWeight: 600, letterSpacing: "0.06em", textTransform: "uppercase", color: "rgba(170,171,177,0.45)", marginBottom: 8 }}>
                Tags
              </div>
              <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
                {model.tags.map(t => (
                  <span key={t} style={{
                    fontSize: 12, fontFamily: "monospace", color: "#a5b4fc",
                    background: "rgba(99,102,241,0.15)", border: "1px solid rgba(99,102,241,0.3)",
                    borderRadius: 5, padding: "2px 8px",
                  }}>{t}</span>
                ))}
              </div>
            </div>
          )}
        </div>

        {/* Footer */}
        <div style={{
          padding: "12px 20px 16px", borderTop: "1px solid #2e3035",
          display: "flex", justifyContent: "flex-end",
        }}>
          <button
            onClick={onClose}
            style={{
              background: "#1a1d23", border: "1px solid #2e3035", borderRadius: 8,
              color: "rgba(255,255,255,0.75)", fontSize: 13, fontWeight: 500,
              padding: "8px 18px", cursor: "pointer",
            }}
            onMouseEnter={e => e.currentTarget.style.borderColor = "#aaabb1"}
            onMouseLeave={e => e.currentTarget.style.borderColor = "#2e3035"}
          >Close</button>
        </div>

      </div>
    </div>
  );
}
