import { createContext, useCallback, useContext, useState } from 'react';
import { CheckCircle2, AlertTriangle, XCircle } from 'lucide-react';
import './Toast.css';

const TOAST_DURATION_MS = 4000;

const VARIANT_ICON = {
  success: CheckCircle2,
  warning: AlertTriangle,
  failure: XCircle,
};

let toastIdCounter = 0;

const ToastContext = createContext(null);

export function ToastProvider({ children }) {
  const [toasts, setToasts] = useState([]);

  const showToast = useCallback(({ variant = 'success', message }) => {
    const id = ++toastIdCounter;
    setToasts(prev => [...prev, { id, variant, message }]);
    setTimeout(() => {
      setToasts(prev => prev.filter(t => t.id !== id));
    }, TOAST_DURATION_MS);
  }, []);

  const dismissToast = useCallback(id => {
    setToasts(prev => prev.filter(t => t.id !== id));
  }, []);

  return (
    <ToastContext.Provider value={showToast}>
      {children}
      <div className="px-toast-stack">
        {toasts.map(t => {
          const Icon = VARIANT_ICON[t.variant] || CheckCircle2;
          return (
            <div key={t.id} className={`px-toast px-toast--${t.variant}`} onClick={() => dismissToast(t.id)}>
              <Icon size={16} className="px-toast__icon" />
              <span className="px-toast__message">{t.message}</span>
            </div>
          );
        })}
      </div>
    </ToastContext.Provider>
  );
}

export function useToast() {
  const showToast = useContext(ToastContext);
  if (!showToast) throw new Error('useToast must be used within a ToastProvider');
  return showToast;
}
