import { useMemo, useState, useSyncExternalStore } from 'react';
import { Search, ChevronLeft, ChevronRight, ChevronsUpDown, Copy, Trash2 } from 'lucide-react';

import AppSidebar from './AppSidebar';
import ConfirmDeleteModal from './ConfirmDeleteModal';
import { subscribe, getRuns, deleteRun, cloneRun } from './runsStore';
import './PipelinesListPage.css';
import './PipelineEditorPage.css';
import './PipelineRunPage.css';

const COLUMNS = [
  { id: 'runName', label: 'Run', sortable: true },
  { id: 'runType', label: 'Type', sortable: true },
  { id: 'status', label: 'Status', sortable: true },
  { id: 'pipelineName', label: 'Pipeline', sortable: true },
  { id: 'startTimeLabel', label: 'Started', sortable: true },
  { id: 'durationSeconds', label: 'Duration', sortable: true },
  { id: 'actions', label: 'Actions', sortable: false },
];

const RUN_STATUS_LABELS = { running: 'Running', success: 'Completed' };

function RunStatusBadge({ status }) {
  const colorVariant = status === 'running' ? 'running' : 'success';
  return (
    <span className={`px-run-badge px-run-badge--${colorVariant}`}>
      <span className="px-run-badge__dot" />
      {RUN_STATUS_LABELS[status] || 'Success'}
    </span>
  );
}

function getRunTypeLabel(run) {
  if (run.pipelineType === 'Study') return 'Sim Experiment';
  if (run.pipelineType === 'Single run') return 'Sim Single Run';
  return 'AI';
}

function formatDuration(seconds) {
  if (seconds == null) return '--';
  if (seconds < 60) return `${seconds}s`;
  const minutes = Math.floor(seconds / 60);
  const rest = seconds % 60;
  return `${minutes}m ${rest}s`;
}

function useRuns() {
  return useSyncExternalStore(subscribe, getRuns);
}

export default function RunsPage({ onNavigate, userName }) {
  const runs = useRuns();
  const [search, setSearch] = useState('');
  const [sort, setSort] = useState({ column: null, ascending: true });
  const [pageSize, setPageSize] = useState(50);
  const [currentPage, setCurrentPage] = useState(1);
  const [checkedRows, setCheckedRows] = useState(() => new Set());
  const [pendingDelete, setPendingDelete] = useState(null);

  const visibleRuns = useMemo(() => {
    let rows = runs;
    if (search.trim()) {
      const query = search.trim().toLowerCase();
      rows = rows.filter(r => (
        r.runName.toLowerCase().includes(query) ||
        r.pipelineName.toLowerCase().includes(query) ||
        r.nodes.join(', ').toLowerCase().includes(query)
      ));
    }
    if (sort.column) {
      rows = [...rows].sort((a, b) => {
        const av = sort.column === 'pipelineName' ? a.pipelineName : sort.column === 'runType' ? getRunTypeLabel(a) : a[sort.column];
        const bv = sort.column === 'pipelineName' ? b.pipelineName : sort.column === 'runType' ? getRunTypeLabel(b) : b[sort.column];
        if (typeof av === 'number' && typeof bv === 'number') {
          return sort.ascending ? av - bv : bv - av;
        }
        const as = String(av ?? '').toLowerCase();
        const bs = String(bv ?? '').toLowerCase();
        if (as < bs) return sort.ascending ? -1 : 1;
        if (as > bs) return sort.ascending ? 1 : -1;
        return 0;
      });
    }
    return rows;
  }, [runs, search, sort]);

  const totalPages = Math.max(1, Math.ceil(visibleRuns.length / pageSize));
  const pagedRuns = visibleRuns.slice((currentPage - 1) * pageSize, currentPage * pageSize);
  const allChecked = checkedRows.size === pagedRuns.length && pagedRuns.length > 0;

  function handleSort(columnId) {
    setSort(prev => ({
      column: columnId,
      ascending: prev.column === columnId ? !prev.ascending : true,
    }));
  }

  function toggleRow(id) {
    setCheckedRows(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id); else next.add(id);
      return next;
    });
  }

  function toggleAll() {
    setCheckedRows(prev => (
      prev.size === pagedRuns.length ? new Set() : new Set(pagedRuns.map(r => r.id))
    ));
  }

  function goToPage(page) {
    setCurrentPage(Math.min(totalPages, Math.max(1, page)));
  }

  function handleCloneClick(run, e) {
    e.stopPropagation();
    cloneRun(run.id);
  }

  function handleDeleteClick(run, e) {
    e.stopPropagation();
    setPendingDelete(run);
  }

  function confirmDelete() {
    deleteRun(pendingDelete.id);
    setCheckedRows(prev => {
      const next = new Set(prev);
      next.delete(pendingDelete.id);
      return next;
    });
    setPendingDelete(null);
  }

  return (
    <div className="px-pipelines">
      <AppSidebar activeItem="runs" onNavigate={onNavigate} userName={userName} />

      <div className="px-pipelines__main">
        <header className="px-pipelines__header">
          <h1 className="px-pipelines__title">Runs</h1>
        </header>

        <div className="px-pipelines__content">
          <div className="px-pipelines__toolbar">
            <label className="px-search" style={{ marginLeft: 'auto' }}>
              <Search size={16} />
              <input
                type="text"
                placeholder="Search runs"
                value={search}
                onChange={e => { setSearch(e.target.value); setCurrentPage(1); }}
              />
            </label>
          </div>

          <div className="px-table-scroll">
            <table className="px-table">
              <thead>
                <tr>
                  <th className="px-table__checkbox-cell">
                    <input
                      type="checkbox"
                      className="px-checkbox"
                      title="Select all runs"
                      aria-label="Select all runs"
                      checked={allChecked}
                      onChange={toggleAll}
                    />
                  </th>
                  {COLUMNS.map(col => (
                    <th key={col.id}>
                      {col.sortable ? (
                        <button type="button" className="px-sort-th" onClick={() => handleSort(col.id)}>
                          {col.label}
                          <ChevronsUpDown size={14} />
                        </button>
                      ) : col.label}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {pagedRuns.map(run => (
                  <tr key={run.id}>
                    <td className="px-table__checkbox-cell">
                      <input
                        type="checkbox"
                        className="px-checkbox"
                        title={`Select run ${run.runName}`}
                        aria-label={`Select run ${run.runName}`}
                        checked={checkedRows.has(run.id)}
                        onChange={() => toggleRow(run.id)}
                      />
                    </td>
                    <td>
                      <div className="px-table__name">
                        <span>{run.runName}</span>
                        <span className="px-table__desc">{run.studyName && run.studyName !== run.pipelineName ? run.studyName : ''}</span>
                      </div>
                    </td>
                    <td><span className="px-badge">{getRunTypeLabel(run)}</span></td>
                    <td><RunStatusBadge status={run.status} /></td>
                    <td>
                      <div className="px-table__name">
                        <span>{run.pipelineName}</span>
                        <span className="px-table__desc">{run.pipelineVersion}</span>
                      </div>
                    </td>
                    <td>{run.startTimeLabel}</td>
                    <td>{run.status === 'running' ? '--' : formatDuration(run.durationSeconds)}</td>
                    <td>
                      <div className="px-table__actions">
                        <button
                          type="button"
                          className="px-icon-btn"
                          title={`Duplicate ${run.runName}`}
                          aria-label={`Duplicate ${run.runName}`}
                          onClick={e => handleCloneClick(run, e)}
                        >
                          <Copy size={16} />
                        </button>
                        <button
                          type="button"
                          className="px-icon-btn"
                          title={`Delete ${run.runName}`}
                          aria-label={`Delete ${run.runName}`}
                          onClick={e => handleDeleteClick(run, e)}
                        >
                          <Trash2 size={16} />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
            {visibleRuns.length === 0 && (
              <div className="px-empty-state">No runs match your search.</div>
            )}
          </div>

          <div className="px-pagination">
            <div className="px-pagination__rows">
              <select value={pageSize} onChange={e => { setPageSize(Number(e.target.value)); setCurrentPage(1); }}>
                {[10, 25, 50, 100].map(size => <option key={size} value={size}>{size}</option>)}
              </select>
              Items per page
            </div>

            <div className="px-pagination__pages">
              <button type="button" className="px-page-btn" disabled={currentPage === 1} onClick={() => goToPage(currentPage - 1)}>
                <ChevronLeft size={14} /> Prev
              </button>
              {Array.from({ length: totalPages }, (_, i) => i + 1).map(page => (
                <button
                  key={page}
                  type="button"
                  className={`px-page-btn${page === currentPage ? ' px-page-btn--active' : ''}`}
                  onClick={() => goToPage(page)}
                >
                  {page}
                </button>
              ))}
              <button type="button" className="px-page-btn" disabled={currentPage === totalPages} onClick={() => goToPage(currentPage + 1)}>
                Next <ChevronRight size={14} />
              </button>
            </div>
          </div>
        </div>
      </div>

      {pendingDelete && (
        <ConfirmDeleteModal
          title="Delete run"
          description={`Are you sure you want to delete "${pendingDelete.runName}"? This action cannot be undone.`}
          onCancel={() => setPendingDelete(null)}
          onConfirm={confirmDelete}
        />
      )}
    </div>
  );
}
