import React, { useState, useEffect, useRef } from "react";
import { CheckCircle2 } from "lucide-react";

// 50 deterministic sweep trials (cant 26–40°, Cd trends down then back up, some constraint violations)
function genTrials() {
  const rows = [];
  const cants    = [28,35,26,33,38,30,29,36,31,32,27,34,37,26,31,33,28,35,30,32,
                    29,36,27,34,38,31,30,35,28,33,26,37,32,29,34,30,28,36,31,33,
                    27,35,29,32,38,30,26,34,31,37];
  const cdBase   = [0.033,0.031,0.035,0.030,0.032,0.029,0.031,0.030,0.029,0.028,
                    0.032,0.031,0.033,0.035,0.030,0.029,0.033,0.032,0.031,0.030,
                    0.031,0.032,0.034,0.030,0.033,0.029,0.031,0.031,0.033,0.030,
                    0.035,0.032,0.030,0.031,0.030,0.031,0.033,0.031,0.029,0.030,
                    0.034,0.031,0.031,0.030,0.032,0.031,0.035,0.030,0.029,0.032];
  for (let i = 0; i < 50; i++) {
    const cant   = cants[i];
    const cd     = cdBase[i];
    const moment = 1900 + cant * 18 + (i % 5) * 80;
    rows.push({ cant, cd, moment });
  }
  return rows;
}
const ALL_TRIALS = genTrials();
const BEST_TRIAL = ALL_TRIALS.reduce((b, t) => t.cd < b.cd ? t : b, ALL_TRIALS[0]);

const CONSTRAINT_MOMENT = 2500; // Nm — must be below this

export default function SweepRunPanel({ onClose }) {
  const [visibleRows, setVisibleRows] = useState([]);
  const [done, setDone]               = useState(false);
  const bottomRef                     = useRef(null);

  // Reveal one row every 200 ms → 50 rows in 10 s
  useEffect(() => {
    let idx = 0;
    const interval = setInterval(() => {
      idx += 1;
      setVisibleRows(ALL_TRIALS.slice(0, idx));
      if (idx >= ALL_TRIALS.length) {
        clearInterval(interval);
        setDone(true);
      }
    }, 100);
    return () => clearInterval(interval);
  }, []);

  // Auto-scroll to bottom as rows appear
  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [visibleRows.length]);

  const bestCdSoFar  = visibleRows.length > 0 ? Math.min(...visibleRows.map(t => t.cd)) : null;
  // Index of first occurrence of best cd in visible rows
  const bestRowIdx   = bestCdSoFar !== null ? visibleRows.findIndex(t => t.cd === bestCdSoFar) : -1;

  return (
    <div style={{ display: "flex", flexDirection: "column", height: "100%", background: "#111318", color: "#fff", overflow: "hidden", userSelect: "none" }}>

      {/* Header */}
      <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", padding: "12px 16px", borderBottom: "1px solid #2e3035", flexShrink: 0 }}>
        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
          <svg width="14" height="14" viewBox="0 0 14 14" fill="none">
            <rect x="1" y="1" width="12" height="12" rx="2" stroke="rgba(170,171,177,0.6)" strokeWidth="1.2"/>
            <path d="M4 7h6M7 4v6" stroke="rgba(170,171,177,0.6)" strokeWidth="1.2" strokeLinecap="round"/>
          </svg>
          <span style={{ fontSize: 13, fontWeight: 600 }}>Sweep Run</span>
          <span style={{
            fontSize: 10, color: "rgba(170,171,177,0.5)", background: "#1d2024",
            padding: "2px 6px", borderRadius: 4, border: "1px solid #2e3035",
          }}>Run</span>
          {done
            ? <span style={{ display: "flex", alignItems: "center", gap: 4, fontSize: 10, color: "#4ade80" }}>
                <CheckCircle2 size={10} /> Completed
              </span>
            : <span style={{ display: "flex", alignItems: "center", gap: 4, fontSize: 10, color: "#fbbf24" }}>
                <span style={{
                  width: 7, height: 7, borderRadius: "50%", background: "#fbbf24",
                  display: "inline-block", animation: "sweepPulse 1.2s ease-in-out infinite",
                  marginRight: 4,
                }} />
                Running…
              </span>
          }
        </div>
        {onClose && (
          <button onClick={onClose} style={{ background: "none", border: "none", color: "rgba(170,171,177,0.6)", cursor: "pointer" }}
            onMouseEnter={e => e.currentTarget.style.color = "#fff"}
            onMouseLeave={e => e.currentTarget.style.color = "rgba(170,171,177,0.6)"}
          >
            <svg width="13" height="13" viewBox="0 0 13 13" fill="none">
              <path d="M2 2L11 11M11 2L2 11" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round"/>
            </svg>
          </button>
        )}
      </div>

      {/* Connection bar */}
      <div style={{
        display: "flex", alignItems: "center", justifyContent: "space-between",
        padding: "8px 16px", borderBottom: "1px solid #2e3035", flexShrink: 0,
        background: "#0e1014",
      }}>
        <span style={{ fontSize: 11, fontFamily: "monospace", color: "rgba(255,255,255,0.5)" }}>
          Winglet · CFRP cruise
        </span>
        <span style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 11, fontFamily: "monospace", color: "#4ade80" }}>
          <span style={{ width: 6, height: 6, borderRadius: "50%", background: "#4ade80", display: "inline-block" }} />
          Connected to 3DX
        </span>
      </div>

      {/* Trial log header */}
      <div style={{
        display: "flex", alignItems: "center", justifyContent: "space-between",
        padding: "12px 16px 8px", flexShrink: 0,
      }}>
        <span style={{ fontSize: 11, fontWeight: 700, letterSpacing: "0.1em", color: "rgba(255,255,255,0.85)", textTransform: "uppercase" }}>
          Trial Log
        </span>
        {bestCdSoFar !== null && (
          <span style={{ fontSize: 11, fontFamily: "monospace", color: "#4ade80" }}>
            best: Cd {bestCdSoFar.toFixed(3)}
          </span>
        )}
      </div>

      {/* Table */}
      <div style={{ flex: 1, overflowY: "auto" }}>
        {/* Column headers */}
        <div style={{
          display: "grid", gridTemplateColumns: "40px 80px 80px 90px 40px",
          padding: "6px 16px", borderBottom: "1px solid #2e3035",
          fontSize: 11, color: "rgba(170,171,177,0.45)", fontFamily: "monospace",
          position: "sticky", top: 0, background: "#111318", zIndex: 1,
        }}>
          <span>#</span>
          <span>Cant</span>
          <span>Cd</span>
          <span>Moment</span>
          <span>OK</span>
        </div>

        {/* Rows */}
        {visibleRows.map((trial, i) => {
          const isBest     = i === bestRowIdx;
          const constraint = trial.moment > CONSTRAINT_MOMENT;
          return (
            <div
              key={i}
              style={{
                display: "grid", gridTemplateColumns: "40px 80px 80px 90px 40px",
                padding: "10px 16px", borderBottom: "1px solid rgba(46,48,53,0.6)",
                fontSize: 12, fontFamily: "monospace",
                borderLeft: isBest ? "2px solid #4ade80" : "2px solid transparent",
                background: isBest ? "rgba(74,222,128,0.04)" : "transparent",
                animation: "rowFadeIn 0.3s ease",
              }}
            >
              <span style={{ color: "rgba(255,255,255,0.35)" }}>{i + 1}</span>
              <span style={{ color: "#fff", fontWeight: 600 }}>{trial.cant}°</span>
              <span style={{ color: isBest ? "#4ade80" : "#fff", fontWeight: isBest ? 700 : 400 }}>
                {trial.cd.toFixed(3)}
              </span>
              <span style={{ color: constraint ? "rgba(255,255,255,0.4)" : "rgba(255,255,255,0.75)" }}>
                {trial.moment}
              </span>
              <span style={{ color: constraint ? "rgba(239,68,68,0.8)" : "rgba(255,255,255,0.6)", fontSize: 13 }}>
                {constraint ? "✗" : "✓"}
              </span>
            </div>
          );
        })}

        {/* Running cursor row */}
        {!done && visibleRows.length < 50 && (
          <div style={{
            display: "grid", gridTemplateColumns: "40px 80px 80px 90px 40px",
            padding: "10px 16px", borderBottom: "1px solid rgba(46,48,53,0.6)",
            fontSize: 12, fontFamily: "monospace", color: "rgba(170,171,177,0.3)",
          }}>
            <span>{visibleRows.length + 1}</span>
            <span style={{ display: "flex", alignItems: "center", gap: 4 }}>
              <span style={{ width: 14, height: 2, background: "rgba(170,171,177,0.2)", borderRadius: 1, display: "inline-block" }} />
            </span>
            <span>…</span>
            <span>…</span>
            <span>…</span>
          </div>
        )}

        <div ref={bottomRef} />
      </div>

      {/* Completion summary */}
      {done && (
        <div style={{
          padding: "12px 16px", borderTop: "1px solid #2e3035", flexShrink: 0,
          background: "rgba(74,222,128,0.05)",
          display: "flex", alignItems: "center", gap: 8,
        }}>
          <CheckCircle2 size={13} color="#4ade80" />
          <span style={{ fontSize: 12, color: "rgba(255,255,255,0.6)" }}>
            50 trials complete ·{" "}
            <span style={{ color: "#4ade80", fontFamily: "monospace" }}>
              best Cd {BEST_TRIAL.cd.toFixed(3)} at {BEST_TRIAL.cant}°
            </span>
          </span>
        </div>
      )}

      <style>{`
        @keyframes rowFadeIn {
          from { opacity: 0; transform: translateY(4px); }
          to   { opacity: 1; transform: translateY(0); }
        }
        @keyframes sweepPulse {
          0%, 100% { opacity: 1; }
          50%       { opacity: 0.3; }
        }
      `}</style>
    </div>
  );
}
