import { useEffect, useRef, useState } from 'react';
import { ChevronLeft, ChevronRight, ChevronsUpDown, Filter, MoreHorizontal, X, Rows3, Columns3 } from 'lucide-react';

import AppSidebar from './AppSidebar';
import { ReadOnlyPipelineCanvas } from './PipelineViewPage';
import { getInitial, ComponentDetailsPanel, PipelineDetailsPanel } from './PipelineEditorPage';
import RunPipelineFormModal from './RunPipelineFormModal';
import ConfirmRerunModal from './ConfirmRerunModal';
import { useToast } from './ToastContext';
import './PipelinesListPage.css';
import './PipelineEditorPage.css';
import './PipelineViewPage.css';
import './PipelineRunPage.css';

const RUN_COMPLETE_DELAY_MS = 4000;

function formatElapsed(seconds) {
  if (seconds < 60) return `${seconds} sec${seconds === 1 ? '' : 's'} ago`;
  const minutes = Math.floor(seconds / 60);
  return `${minutes} min${minutes === 1 ? '' : 's'} ago`;
}

function formatDuration(seconds) {
  if (seconds < 60) return `${seconds}s`;
  const minutes = Math.floor(seconds / 60);
  const rest = seconds % 60;
  return `${minutes}m ${rest}s`;
}

const RUN_STATUS_LABELS = { running: 'Running', success: 'Success', completed: 'Completed' };

function RunStatusBadge({ status }) {
  const colorVariant = status === 'running' ? 'running' : 'success';
  return (
    <span className={`px-run-badge px-run-badge--${colorVariant}`}>
      <span className="px-run-badge__dot" />
      {RUN_STATUS_LABELS[status] || 'Success'}
    </span>
  );
}

function RunDetailsPanel({ row, pipeline, userName, onClose, width }) {
  return (
    <div className="px-editor__details" style={{ width }}>
      <div className="px-editor__details-header">
        <h2 className="px-editor__details-title">Run details</h2>
        <button type="button" className="px-editor__details-close" aria-label="Close" title="Close" onClick={onClose}>
          <X size={18} />
        </button>
      </div>

      <div className="px-editor__field">
        <span className="px-editor__field-label">Run name</span>
        <div className="px-editor__field-value">{row.runName}</div>
      </div>

      <div className="px-editor__field">
        <span className="px-editor__field-label">Run ID</span>
        <div className="px-editor__field-value">{row.id || '--'}</div>
      </div>

      <div className="px-editor__field">
        <span className="px-editor__field-label">Duration</span>
        <div className="px-editor__field-value">{row.duration}</div>
      </div>

      <div className="px-editor__field">
        <span className="px-editor__field-label">Created by</span>
        <div className="px-editor__updated-by">
          <span className="px-editor__updated-avatar">{getInitial(userName)}</span>
          <span className="px-editor__field-value">{userName}</span>
        </div>
      </div>

      <div className="px-editor__field">
        <span className="px-editor__field-label">Created at</span>
        <div className="px-editor__field-value">{pipeline.created}</div>
      </div>

      <div className="px-editor__field">
        <span className="px-editor__field-label">Status</span>
        <div className="px-editor__field-value"><RunStatusBadge status={row.status} /></div>
      </div>
    </div>
  );
}

function flattenNodes(nodes) {
  const flat = [];
  nodes.forEach(n => {
    if (n.isGroup) (n.children || []).forEach(c => flat.push(c));
    else flat.push(n);
  });
  return flat;
}

function updateNodeById(prev, nodeId, updater) {
  return prev.map(n => {
    if (n.id === nodeId) return updater(n);
    if (n.isGroup && n.children?.some(c => c.id === nodeId)) {
      return { ...n, children: n.children.map(c => (c.id === nodeId ? updater(c) : c)) };
    }
    return n;
  });
}

function deriveHistoryRow(row, now) {
  if (row.startedAt == null) return row;
  const elapsedMs = now - row.startedAt;
  const done = elapsedMs >= RUN_COMPLETE_DELAY_MS;
  const durationSeconds = done ? Math.round(RUN_COMPLETE_DELAY_MS / 1000) : -1;
  return {
    ...row,
    status: done ? 'success' : 'running',
    startTime: formatElapsed(Math.max(0, Math.floor(elapsedMs / 1000))),
    duration: done ? formatDuration(durationSeconds) : '--',
    durationSeconds,
  };
}

export default function PipelineRunPage({ pipeline, userName, onBack, onNavigate, onEdit, onDeletePipeline, onStartRun, autoOpenRunModal, onAutoOpenRunModalConsumed }) {
  const showToast = useToast();
  const rawHistory = pipeline.runHistory || [];

  const [detailsOpen, setDetailsOpen] = useState(true);
  const [moreMenuOpen, setMoreMenuOpen] = useState(false);
  const [selectedNodeId, setSelectedNodeId] = useState(null);
  const [draftNodes, setDraftNodes] = useState(() => pipeline.canvasNodes || []);
  const [dirtySinceLastRun, setDirtySinceLastRun] = useState(false);
  const [confirmRerunOpen, setConfirmRerunOpen] = useState(false);
  const [nowTick, setNowTick] = useState(() => Date.now());
  const [detailsWidth, setDetailsWidth] = useState(320);
  const [canvasHeight, setCanvasHeight] = useState(420);
  const [pageSize, setPageSize] = useState(10);
  const [currentPage, setCurrentPage] = useState(1);
  const [sort, setSort] = useState({ column: null, ascending: true });
  const [studyFilter, setStudyFilter] = useState(null);
  const [studyMenuOpen, setStudyMenuOpen] = useState(false);
  const [selectedRunIndex, setSelectedRunIndex] = useState(null);
  const [runModalOpen, setRunModalOpen] = useState(false);
  const [flowDirection, setFlowDirection] = useState('horizontal');
  const resizeDragging = useRef(false);
  const resizeStartX = useRef(0);
  const resizeStartWidth = useRef(0);
  const canvasResizeDragging = useRef(false);
  const canvasResizeStartY = useRef(0);
  const canvasResizeStartHeight = useRef(0);
  const latestRunIdRef = useRef(rawHistory[0]?.id);

  useEffect(() => {
    if (autoOpenRunModal) {
      setRunModalOpen(true);
      onAutoOpenRunModalConsumed?.();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [autoOpenRunModal]);

  useEffect(() => {
    const topId = rawHistory[0]?.id;
    if (topId && topId !== latestRunIdRef.current) {
      setSelectedRunIndex(0);
      setSelectedNodeId(null);
      setDirtySinceLastRun(false);
    }
    latestRunIdRef.current = topId;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [rawHistory[0]?.id]);

  useEffect(() => {
    const anyRunning = rawHistory.some(r => r.startedAt != null && Date.now() - r.startedAt < RUN_COMPLETE_DELAY_MS);
    if (!anyRunning) return;
    const tick = setInterval(() => setNowTick(Date.now()), 1000);
    return () => clearInterval(tick);
  }, [rawHistory]);

  const historyRows = rawHistory.map((row, i) => ({ ...deriveHistoryRow(row, nowTick), historyIndex: i }));

  const hasRunAtLeastOnce = historyRows.length > 0;

  const selectedHistoryRow = selectedRunIndex !== null ? historyRows[selectedRunIndex] : null;
  const viewingDraft = selectedRunIndex === null;
  const activeNodes = viewingDraft ? draftNodes : (selectedHistoryRow?.nodes || []);
  const activeRunName = viewingDraft ? 'Pipeline draft' : selectedHistoryRow?.runName;
  const activeVersion = viewingDraft ? (pipeline.version || 'v0.1') : selectedHistoryRow?.version;
  const flatActiveNodes = flattenNodes(activeNodes);

  function getNodeRunStatus(node) {
    if (viewingDraft || !selectedHistoryRow) return null;
    if (selectedHistoryRow.status === 'failed') return 'failed';
    if (selectedHistoryRow.status !== 'running') return 'success';
    if (selectedHistoryRow.startedAt == null) return 'running';
    const idx = flatActiveNodes.findIndex(n => n.id === node.id);
    if (idx === -1) return 'running';
    const total = flatActiveNodes.length || 1;
    const segment = RUN_COMPLETE_DELAY_MS / total;
    const elapsed = nowTick - selectedHistoryRow.startedAt;
    if (elapsed >= (idx + 1) * segment) return 'success';
    if (elapsed >= idx * segment) return 'running';
    return 'pending';
  }

  function findActiveNodeById(id) {
    for (const n of activeNodes) {
      if (n.id === id) return n;
      if (n.isGroup) {
        const child = (n.children || []).find(c => c.id === id);
        if (child) return child;
      }
    }
    return null;
  }

  const selectedNode = selectedNodeId ? findActiveNodeById(selectedNodeId) : null;

  function selectRun(historyIndex) {
    setSelectedRunIndex(prev => (prev === historyIndex ? null : historyIndex));
    setSelectedNodeId(null);
  }

  function handleSort(columnId) {
    setSort(prev => ({
      column: columnId,
      ascending: prev.column === columnId ? !prev.ascending : true,
    }));
    setCurrentPage(1);
  }

  function handleResizeMouseDown(e) {
    e.preventDefault();
    resizeDragging.current = true;
    resizeStartX.current = e.clientX;
    resizeStartWidth.current = detailsWidth;
  }

  function handleCanvasResizeMouseDown(e) {
    e.preventDefault();
    canvasResizeDragging.current = true;
    canvasResizeStartY.current = e.clientY;
    canvasResizeStartHeight.current = canvasHeight;
  }

  function handleBodyMouseMove(e) {
    if (resizeDragging.current) {
      const dx = e.clientX - resizeStartX.current;
      setDetailsWidth(Math.min(560, Math.max(260, resizeStartWidth.current - dx)));
    }
    if (canvasResizeDragging.current) {
      const dy = e.clientY - canvasResizeStartY.current;
      setCanvasHeight(Math.min(720, Math.max(200, canvasResizeStartHeight.current + dy)));
    }
  }

  function handleBodyMouseUp() {
    resizeDragging.current = false;
    canvasResizeDragging.current = false;
  }

  const unsortedRows = historyRows;

  const studyOptions = Array.from(new Set(unsortedRows.map(r => r.studyName))).filter(Boolean);
  const existingStudyNames = studyOptions.filter(name => name !== '--');
  const filteredRows = studyFilter ? unsortedRows.filter(r => r.studyName === studyFilter) : unsortedRows;

  const rows = sort.column
    ? [...filteredRows].sort((a, b) => {
        const av = a[sort.column];
        const bv = b[sort.column];
        if (typeof av === 'number' && typeof bv === 'number') {
          return sort.ascending ? av - bv : bv - av;
        }
        const as = String(av).toLowerCase();
        const bs = String(bv).toLowerCase();
        if (as < bs) return sort.ascending ? -1 : 1;
        if (as > bs) return sort.ascending ? 1 : -1;
        return 0;
      })
    : filteredRows;

  const totalRows = rows.length;
  const totalPages = Math.max(1, Math.ceil(totalRows / pageSize));

  const detailsRow = selectedHistoryRow
    ? { runName: selectedHistoryRow.runName, id: selectedHistoryRow.id, duration: selectedHistoryRow.duration, status: selectedHistoryRow.status }
    : null;

  function handleStudyFilterSelect(study) {
    setStudyFilter(prev => (prev === study ? null : study));
    setStudyMenuOpen(false);
    setCurrentPage(1);
  }

  return (
    <div className="px-pipelines">
      <AppSidebar activeItem="pipelines" onNavigate={onNavigate} userName={userName} />

      <div className="px-pipelines__main">
        <header className="px-pipelines__header">
          <div className="px-sim-detail__header-left">
            <button type="button" className="px-editor__back" onClick={onBack} aria-label="Back" title="Back">
              <ChevronLeft size={16} />
            </button>
            <h1 className="px-pipelines__title">{pipeline.name}</h1>
          </div>
          <div className="px-pipelines__header-actions">
            <div className="px-new-menu-wrap">
              <button
                type="button"
                className="px-icon-btn"
                title="More options"
                aria-label="More options"
                onClick={() => setMoreMenuOpen(o => !o)}
              >
                <MoreHorizontal size={18} />
              </button>
              {moreMenuOpen && (
                <>
                  <div className="px-menu-overlay" onClick={() => setMoreMenuOpen(false)} />
                  <div className="px-new-menu">
                    {!detailsOpen && !selectedNodeId && (
                      <button
                        type="button"
                        onClick={() => { setDetailsOpen(true); setSelectedNodeId(null); setMoreMenuOpen(false); }}
                      >
                        Show run details
                      </button>
                    )}
                    <button type="button" onClick={() => { setMoreMenuOpen(false); onDeletePipeline?.(); }}>
                      Delete pipeline
                    </button>
                  </div>
                </>
              )}
            </div>
            <button type="button" className="px-editor__btn px-editor__btn--secondary" onClick={onEdit}>
              Edit pipeline
            </button>
            <button
              type="button"
              className="px-editor__btn px-editor__btn--primary"
              onClick={() => {
                if (hasRunAtLeastOnce && !dirtySinceLastRun) {
                  setConfirmRerunOpen(true);
                } else {
                  setRunModalOpen(true);
                }
              }}
            >
              Run pipeline
            </button>
          </div>
        </header>

        <div className="px-editor__body" onMouseMove={handleBodyMouseMove} onMouseUp={handleBodyMouseUp}>
          <div className="px-view__canvas-col">
            <div className="px-view__subheader">
              <span className="px-run__name-group">
                {!viewingDraft && <span className="px-run__breadcrumb">Run &gt;</span>}
                <span className="px-view__status">{activeRunName}</span>
                <span className="px-run__version">{activeVersion}</span>
              </span>
              <div className="px-view__subheader-right">
                <button
                  type="button"
                  className="px-icon-btn"
                  title={flowDirection === 'horizontal' ? 'Switch to vertical layout' : 'Switch to horizontal layout'}
                  aria-label={flowDirection === 'horizontal' ? 'Switch to vertical layout' : 'Switch to horizontal layout'}
                  onClick={() => setFlowDirection(d => (d === 'horizontal' ? 'vertical' : 'horizontal'))}
                >
                  {flowDirection === 'horizontal' ? <Rows3 size={16} /> : <Columns3 size={16} />}
                </button>
              </div>
            </div>

            <ReadOnlyPipelineCanvas
              nodes={activeNodes}
              selectedNodeId={selectedNodeId}
              onSelectNode={setSelectedNodeId}
              onDeselect={() => setSelectedNodeId(null)}
              className="px-run__canvas"
              style={{ flex: `0 0 ${canvasHeight}px` }}
              direction={flowDirection}
              getNodeStatus={getNodeRunStatus}
            />

            <div className="resize-handle-h" onMouseDown={handleCanvasResizeMouseDown} />

            <div className="px-run__table-wrap">
              <table className="px-table">
                <thead>
                  <tr>
                    <th className="px-table__checkbox-cell">
                      <input
                        type="checkbox"
                        className="px-checkbox"
                        title="Clear run selection"
                        aria-label="Clear run selection"
                        checked={selectedRunIndex !== null}
                        onChange={() => { setSelectedRunIndex(null); setSelectedNodeId(null); }}
                      />
                    </th>
                    <th>Run</th>
                    <th>
                      <div className="px-new-menu-wrap px-run__filter-th">
                        <button type="button" className="px-sort-th" onClick={() => setStudyMenuOpen(o => !o)}>
                          Experiment
                          <Filter size={14} className={studyFilter ? 'px-run__filter-icon--active' : undefined} />
                        </button>
                        {studyMenuOpen && (
                          <>
                            <div className="px-menu-overlay" onClick={() => setStudyMenuOpen(false)} />
                            <div className="px-new-menu">
                              {studyOptions.map(study => (
                                <button
                                  key={study}
                                  type="button"
                                  className={study === studyFilter ? 'px-new-menu__item--active' : undefined}
                                  onClick={() => handleStudyFilterSelect(study)}
                                >
                                  {study}
                                </button>
                              ))}
                            </div>
                          </>
                        )}
                      </div>
                    </th>
                    <th>Pipeline version</th>
                    <th>Type</th>
                    <th>Status</th>
                    <th>Start time</th>
                    <th>
                      <button type="button" className="px-sort-th" onClick={() => handleSort('durationSeconds')}>
                        Duration
                        <ChevronsUpDown size={14} />
                      </button>
                    </th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {rows.slice((currentPage - 1) * pageSize, currentPage * pageSize).map((row, i) => {
                    const rowIndex = (currentPage - 1) * pageSize + i;
                    return (
                      <tr
                        key={rowIndex}
                        className={row.historyIndex === selectedRunIndex ? 'px-table__row--active' : undefined}
                        onClick={() => selectRun(row.historyIndex)}
                      >
                        <td className="px-table__checkbox-cell" onClick={e => e.stopPropagation()}>
                          <input
                            type="checkbox"
                            className="px-checkbox"
                            title={`Select run ${row.runName}`}
                            aria-label={`Select run ${row.runName}`}
                            checked={row.historyIndex === selectedRunIndex}
                            onChange={() => selectRun(row.historyIndex)}
                          />
                        </td>
                        <td>{row.runName}</td>
                        <td>{row.studyName}</td>
                        <td>{row.version}</td>
                        <td><span className="px-badge">{row.type}</span></td>
                        <td><RunStatusBadge status={row.status} /></td>
                        <td>{row.startTime}</td>
                        <td>{row.duration}</td>
                        <td />
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>

            <div className="px-pagination">
              <div className="px-pagination__rows">
                <select value={pageSize} onChange={e => { setPageSize(Number(e.target.value)); setCurrentPage(1); }}>
                  {[10, 25, 50, 100].map(size => <option key={size} value={size}>{size}</option>)}
                </select>
                Items per page
              </div>

              <div className="px-pagination__pages">
                <button type="button" className="px-page-btn" disabled={currentPage === 1} onClick={() => setCurrentPage(p => Math.max(1, p - 1))}>
                  <ChevronLeft size={14} /> Prev
                </button>
                {Array.from({ length: totalPages }, (_, i) => i + 1).map(page => (
                  <button
                    key={page}
                    type="button"
                    className={`px-page-btn${page === currentPage ? ' px-page-btn--active' : ''}`}
                    onClick={() => setCurrentPage(page)}
                  >
                    {page}
                  </button>
                ))}
                <button type="button" className="px-page-btn" disabled={currentPage === totalPages} onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}>
                  Next <ChevronRight size={14} />
                </button>
              </div>
            </div>
          </div>

          {selectedNode ? (
            <>
              <div className="resize-handle-v resize-handle-v--bare" onMouseDown={handleResizeMouseDown} />
              <ComponentDetailsPanel
                node={selectedNode}
                pipeline={pipeline}
                userName={userName}
                onClose={() => setSelectedNodeId(null)}
                width={detailsWidth}
                editable={viewingDraft}
                inputEditable={false}
                onVersionChange={viewingDraft ? version => {
                  setDraftNodes(prev => updateNodeById(prev, selectedNode.id, n => ({ ...n, version })));
                  setDirtySinceLastRun(true);
                } : undefined}
              />
            </>
          ) : detailsOpen && (
            <>
              <div className="resize-handle-v resize-handle-v--bare" onMouseDown={handleResizeMouseDown} />
              {viewingDraft ? (
                <PipelineDetailsPanel
                  pipeline={pipeline}
                  userName={userName}
                  onClose={() => setDetailsOpen(false)}
                  width={detailsWidth}
                />
              ) : (
                <RunDetailsPanel
                  row={detailsRow}
                  pipeline={pipeline}
                  userName={userName}
                  onClose={() => setDetailsOpen(false)}
                  width={detailsWidth}
                />
              )}
            </>
          )}
        </div>
      </div>

      {runModalOpen && (
        <RunPipelineFormModal
          existingStudies={existingStudyNames}
          onCancel={() => setRunModalOpen(false)}
          onRun={({ runName, studyName, description, runScope }) => {
            setRunModalOpen(false);
            onStartRun?.({ runName, studyName, description, runScope, nodes: draftNodes });
            showToast({ variant: 'success', message: `Run "${runName}" started` });
          }}
        />
      )}

      {confirmRerunOpen && (
        <ConfirmRerunModal
          onCancel={() => setConfirmRerunOpen(false)}
          onConfirm={() => { setConfirmRerunOpen(false); setRunModalOpen(true); }}
        />
      )}
    </div>
  );
}
