/* ── Component Card ─────────────────────────────────────────────── */

function getCardInitials(name) {
  if (name.toLowerCase().startsWith('e2e')) return 'e2e';
  return name.split(/\s+/).map(w => w[0] || '').join('').slice(0, 2).toUpperCase();
}

function ComponentCard({ name, subtitle, isNew, scrollRef }) {
  function handleDragStart(e) {
    e.dataTransfer.setData('componentName', name);
  }
  const initials   = getCardInitials(name);
  const accentColor = isNew ? 'rgba(147,210,255,0.9)' : 'rgba(255,255,255,0.7)';
  const bgColor     = isNew ? 'rgba(59,130,246,0.18)'  : 'rgba(255,255,255,0.07)';
  const borderClr   = isNew ? 'rgba(99,179,237,0.35)'  : 'rgba(255,255,255,0.12)';

  return (
    <div ref={scrollRef} className="component-card" draggable onDragStart={handleDragStart}
      style={isNew ? { borderColor: 'rgba(99,179,237,0.3)', background: 'rgba(59,130,246,0.07)' } : undefined}>
      <div className="component-card__row">
        <div style={{
          width: 26, height: 26, borderRadius: 6, flexShrink: 0,
          background: bgColor, border: `1px solid ${borderClr}`,
          display: 'flex', alignItems: 'center', justifyContent: 'center',
        }}>
          <span style={{
            fontSize: initials.length > 2 ? 8 : 10,
            fontWeight: 700, letterSpacing: '0.01em',
            color: accentColor, fontFamily: "'Geist Mono', monospace",
            lineHeight: 1,
          }}>{initials}</span>
        </div>
        <span className="component-card__name" style={isNew ? { color: 'rgba(147,210,255,0.9)' } : undefined}>{name}</span>
        {isNew && <span style={{ fontSize: 9, fontWeight: 700, letterSpacing: '0.06em', color: 'rgba(99,179,237,0.8)', background: 'rgba(59,130,246,0.18)', border: '1px solid rgba(99,179,237,0.25)', borderRadius: 3, padding: '1px 4px', marginLeft: 'auto' }}>NEW</span>}
      </div>
      {subtitle && <span className="component-card__subtitle">{subtitle}</span>}
    </div>
  );
}

/* ── Section Group ──────────────────────────────────────────────── */

function PipelinesSection({ savedPipelines = [], showE2e = true, newPipelineRef }) {
  const [open, setOpen] = useState(true);
  return (
    <div className="section-group">
      <button className="section-group__header" onClick={() => setOpen(!open)}>
        <span className="section-group__title">Pipelines</span>
        <IconChevronDown up={open} />
      </button>
      {open && (
        <div className="section-group__items">
          {showE2e && <ComponentCard name="e2e Training pipeline" />}
          {savedPipelines.map((pipeline, i) => (
            <SavedPipelineCard
              key={i}
              pipeline={pipeline}
              scrollRef={i === savedPipelines.length - 1 ? newPipelineRef : undefined}
            />
          ))}
        </div>
      )}
    </div>
  );
}

function SectionGroup({ title, items, defaultExpanded = true, newItemRef }) {
  const [open, setOpen] = useState(defaultExpanded);
  return (
    <div className="section-group">
      <button className="section-group__header" onClick={() => setOpen(!open)}>
        <span className="section-group__title">{title}</span>
        <IconChevronDown up={open} />
      </button>
      {open && (
        <div className="section-group__items">
          {items.map((item, i) => {
            const isLastNew = item.isNew && i === items.length - 1;
            return (
              <ComponentCard
                key={i}
                name={item.name}
                subtitle={item.subtitle}
                isNew={item.isNew}
                scrollRef={isLastNew ? newItemRef : undefined}
              />
            );
          })}
        </div>
      )}
    </div>
  );
}

