const FILTER_TABS = ['All', 'Built-in', 'Custom', 'Pipelines', 'Models'];

function SecondaryPanel({ width, onResizeStart, selectedWorkbook, onSelectWorkbook, savedPipelines = [], modelTrainingExtras = [], registeredModels = MODEL_ITEMS }) {
  const newItemRef     = useRef(null);
  const newPipelineRef = useRef(null);
  const newModelRef    = useRef(null);
  const [query,     setQuery]     = useState('');
  const [activeTab, setActiveTab] = useState('All');

  useEffect(() => {
    if (modelTrainingExtras.length === 0) return;
    const t = setTimeout(() => {
      newItemRef.current?.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }, 80);
    return () => clearTimeout(t);
  }, [modelTrainingExtras.length]);

  useEffect(() => {
    if (savedPipelines.length === 0) return;
    const t = setTimeout(() => {
      newPipelineRef.current?.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }, 80);
    return () => clearTimeout(t);
  }, [savedPipelines.length]);

  useEffect(() => {
    const newModel = registeredModels.find(m => m.isNew);
    if (!newModel) return;
    const t = setTimeout(() => {
      newModelRef.current?.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }, 80);
    return () => clearTimeout(t);
  }, [registeredModels.length]);

  const q = query.trim().toLowerCase();

  function filterItems(items) {
    if (!q) return items;
    return items.filter(item => item.name.toLowerCase().includes(q) || (item.subtitle || '').toLowerCase().includes(q));
  }

  function filterPipelines(list) {
    if (!q) return list;
    return list.filter(p => p.name.toLowerCase().includes(q));
  }

  const builtinFiltered  = filterItems(BUILTIN_ITEMS);
  const customFiltered   = filterItems([...CUSTOM_ITEMS, ...modelTrainingExtras.map(n => ({ name: n, isNew: true }))]);
  const pipelineFiltered = filterPipelines(savedPipelines);
  const modelsFiltered   = filterItems(registeredModels);
  const e2eVisible       = !q || 'e2e training pipeline'.includes(q);

  const showBuiltin   = (activeTab === 'All' || activeTab === 'Built-in')  && builtinFiltered.length > 0;
  const showCustom    = (activeTab === 'All' || activeTab === 'Custom')    && customFiltered.length > 0;
  const showPipelines = (activeTab === 'All' || activeTab === 'Pipelines') && (e2eVisible || pipelineFiltered.length > 0);
  const showModels    = (activeTab === 'All' || activeTab === 'Models')    && modelsFiltered.length > 0;

  return (
    <aside className="secondary-panel" style={{ width, minWidth: width }}>
      {/* Workbook box */}
      <div className="panel-box panel-box--workbook">
        <div className="panel-box__title-row">
          <span className="panel-box__title">Workbook</span>
          <button className="panel-box__add-btn">
            <IconPlus color="rgba(255,255,255,0.6)" />
          </button>
        </div>
        <div className="panel-box__scroll">
          <div className="workbook-list">
            {WORKBOOKS.map(({ name, edited }) => (
              <button
                key={name}
                className={`workbook-item${selectedWorkbook === name ? ' workbook-item--active' : ''}`}
                onClick={() => onSelectWorkbook(name)}
              >
                <IconBook />
                <span className="workbook-item__name" style={{ flex: 1 }}>{name}</span>
                <span style={{ fontSize: 10, color: 'rgba(170,171,177,0.4)', fontFamily: 'monospace', flexShrink: 0 }}>{edited}</span>
              </button>
            ))}
          </div>
        </div>
      </div>

      {/* Registry box */}
      <div className="panel-box">
        <div className="panel-box__title-row">
          <span className="panel-box__title">Registry</span>
        </div>

        {/* Search input */}
        <div style={{ padding: '8px 10px 6px', flexShrink: 0 }}>
          <div style={{
            display: 'flex', alignItems: 'center', gap: 6,
            background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.09)',
            borderRadius: 7, padding: '5px 10px',
            transition: 'border-color 0.15s',
          }}
            onFocusCapture={e => e.currentTarget.style.borderColor = 'rgba(99,102,241,0.5)'}
            onBlurCapture={e  => e.currentTarget.style.borderColor = 'rgba(255,255,255,0.09)'}
          >
            <svg width="13" height="13" viewBox="0 0 13 13" fill="none" style={{ flexShrink: 0 }}>
              <circle cx="5.5" cy="5.5" r="4" stroke="rgba(170,171,177,0.5)" strokeWidth="1.3"/>
              <path d="M8.5 8.5L11 11" stroke="rgba(170,171,177,0.5)" strokeWidth="1.3" strokeLinecap="round"/>
            </svg>
            <input
              value={query}
              onChange={e => setQuery(e.target.value)}
              placeholder="Search registry…"
              style={{
                background: 'none', border: 'none', outline: 'none',
                fontSize: 12, color: '#fff', flex: 1,
                fontFamily: 'inherit',
              }}
            />
            {query && (
              <button onClick={() => setQuery('')}
                style={{ background: 'none', border: 'none', cursor: 'pointer', color: 'rgba(170,171,177,0.5)', padding: 0, display: 'flex', lineHeight: 1 }}
                onMouseEnter={e => e.currentTarget.style.color = '#fff'}
                onMouseLeave={e => e.currentTarget.style.color = 'rgba(170,171,177,0.5)'}
              >
                <svg width="11" height="11" viewBox="0 0 11 11" fill="none">
                  <path d="M2 2L9 9M9 2L2 9" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round"/>
                </svg>
              </button>
            )}
          </div>
        </div>

        {/* Filter chips */}
        <div style={{ display: 'flex', gap: 4, padding: '0 10px 8px', flexWrap: 'wrap', flexShrink: 0 }}>
          {FILTER_TABS.map(tab => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              style={{
                fontSize: 10, fontWeight: 600, letterSpacing: '0.04em',
                padding: '3px 8px', borderRadius: 5, cursor: 'pointer', border: 'none',
                background: activeTab === tab ? 'rgba(99,102,241,0.2)' : 'rgba(255,255,255,0.05)',
                color: activeTab === tab ? '#a5b4fc' : 'rgba(170,171,177,0.55)',
                transition: 'background 0.12s, color 0.12s',
              }}
              onMouseEnter={e => { if (activeTab !== tab) e.currentTarget.style.background = 'rgba(255,255,255,0.09)'; }}
              onMouseLeave={e => { if (activeTab !== tab) e.currentTarget.style.background = 'rgba(255,255,255,0.05)'; }}
            >
              {tab}
            </button>
          ))}
        </div>

        {/* Add custom component button */}
        <div style={{ padding: '0 10px 8px', flexShrink: 0 }}>
          <div
            draggable
            onDragStart={e => e.dataTransfer.setData('componentName', 'Custom component')}
            style={{
              width: '100%', display: 'flex', alignItems: 'center', gap: 7,
              background: 'rgba(99,102,241,0.08)', border: '1px dashed rgba(99,102,241,0.3)',
              borderRadius: 7, padding: '7px 10px', cursor: 'grab',
              fontSize: 12, color: 'rgba(165,180,252,0.75)',
              transition: 'background 0.15s, border-color 0.15s, color 0.15s',
              boxSizing: 'border-box', userSelect: 'none',
            }}
            onMouseEnter={e => { e.currentTarget.style.background = 'rgba(99,102,241,0.16)'; e.currentTarget.style.borderColor = 'rgba(99,102,241,0.55)'; e.currentTarget.style.color = '#c4b5fd'; }}
            onMouseLeave={e => { e.currentTarget.style.background = 'rgba(99,102,241,0.08)'; e.currentTarget.style.borderColor = 'rgba(99,102,241,0.3)';  e.currentTarget.style.color = 'rgba(165,180,252,0.75)'; }}
          >
            <svg width="14" height="14" viewBox="0 0 14 14" fill="none" style={{ flexShrink: 0 }}>
              <path d="M7 2v10M2 7h10" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round"/>
            </svg>
            Add custom component
          </div>
        </div>

        <div className="panel-box__scroll">
          {/* No results */}
          {!showBuiltin && !showCustom && !showPipelines && !showModels && (
            <div style={{ padding: '20px 12px', textAlign: 'center', fontSize: 12, color: 'rgba(170,171,177,0.4)' }}>
              No results for "{query}"
            </div>
          )}

          {showBuiltin && (
            <SectionGroup
              title="Built-in components"
              items={builtinFiltered}
              defaultExpanded={true}
            />
          )}
          {showCustom && (
            <SectionGroup
              title="Custom components"
              items={customFiltered}
              defaultExpanded={true}
              newItemRef={newItemRef}
            />
          )}
          {showPipelines && (
            <PipelinesSection savedPipelines={pipelineFiltered} showE2e={e2eVisible} newPipelineRef={newPipelineRef} />
          )}
          {showModels && (
            <SectionGroup
              title="Models"
              items={modelsFiltered}
              defaultExpanded={true}
              newItemRef={newModelRef}
            />
          )}
        </div>
      </div>
    </aside>
  );
}

/* ── Simcard ────────────────────────────────────────────────────── */

function Simcard({ name = 'CAD', version = 'v0.1', status = 'Draft' }) {
  return (
    <div className="simcard">
      <div className="simcard__icon">
        <IconDeployedCode size={20} />
      </div>
      <div className="simcard__title">{name}</div>
      <button className="simcard__play"><IconPlay /></button>
      <div className="simcard__divider" />
      <div className="simcard__version">
        <span className="simcard__version-text">{version}</span>
        <IconArrowDropDown />
      </div>
      <div className="simcard__badge">
        <span className="simcard__badge-dot" />
        <span className="simcard__badge-label">{status}</span>
      </div>
    </div>
  );
}

/* ── Canvas Area ────────────────────────────────────────────────── */

function CanvasTool({ icon, label, active = false }) {
  return (
    <div className="canvas-tool">
      <button className={`icon-btn${active ? ' icon-btn--active' : ''}`}>{icon}</button>
      <span className="canvas-tool__label">{label}</span>
    </div>
  );
}

function CanvasArea({ onNavigate, onDropComponent }) {
  function handleDragOver(e) {
    e.preventDefault();
  }

  function handleDrop(e) {
    e.preventDefault();
    const name = e.dataTransfer.getData('componentName');
    if (name === 'CAD Importer' || name === 'CAD') {
      onDropComponent?.(name);
      onNavigate('vision');
    }
  }

  return (
    <main className="canvas-area">
      <div className="canvas-toolbar">
        <span className="canvas-toolbar__title">Pipeline</span>
        <CanvasTool icon={<IconCursor />} label="Select" active />
        <CanvasTool icon={<IconTransform />} label="Transform" />
        <CanvasTool icon={<IconComment />} label="Comment" />
        <CanvasTool icon={<IconFrame />} label="Frame" />
      </div>
      <div className="canvas-content" onDragOver={handleDragOver} onDrop={handleDrop}>
        <div className="canvas-empty-state">
          <div className="canvas-empty-icon">
            <IconPlus color="rgba(255,255,255,0.45)" />
          </div>
          <div className="canvas-empty-text">
            <p>Start by dragging a component or clicking, or</p>
            <button className="canvas-link">Connect to notebook</button>
          </div>
        </div>
      </div>
    </main>
  );
}

/* ── App ────────────────────────────────────────────────────────── */

function AppInner() {
  const [page, setPage] = useState('pipelines-list');
  const [visionView, setVisionView] = useState('studydriver');
  const [selectedWorkbook, setSelectedWorkbook] = useState('Workbook A');
  const [savedPipelines, setSavedPipelines] = useState([]);
  const [modelTrainingExtras, setModelTrainingExtras] = useState([]);
  const [pendingDrop, setPendingDrop] = useState(null);
  const [leftPanelWidth, setLeftPanelWidth] = useState(232);
  const [registeredModels, setRegisteredModels] = useState(MODEL_ITEMS);

  const leftSplitterDragging = useRef(false);
  const leftSplitterStartX   = useRef(0);
  const leftSplitterStartW   = useRef(0);

  function handleLeftSplitterMouseDown(e) {
    e.preventDefault();
    leftSplitterDragging.current = true;
    leftSplitterStartX.current   = e.clientX;
    leftSplitterStartW.current   = leftPanelWidth;
  }

  function handleNavigate(newPage) {
    setPage(newPage);
    setVisionView('studydriver');
  }

  function handleSidebarNavigate(target) {
    if (target === 'home') handleNavigate('pipelines');
    else if (target === 'pipelines') handleNavigate('pipelines-list');
    else if (target === 'components') handleNavigate('components');
    else if (target === 'runs') handleNavigate('runs');
  }

  function handleSavePipeline(name, names) {
    setSavedPipelines(prev =>
      prev.some(p => p.name === name) ? prev : [{ name, names: names || [] }, ...prev]
    );
  }

  function handleAddToModelTraining(name) {
    setModelTrainingExtras(prev => prev.includes(name) ? prev : [...prev, name]);
  }

  function handleRegisterModel({ name, version, tags, saveAsPipeline }) {
    // Add to models in registry (prepend so it appears at the top)
    const subtitle = `Registered · v${version}`;
    setRegisteredModels(prev =>
      prev.some(m => m.name === name) ? prev : [{ name, subtitle, tags, isNew: true }, ...prev]
    );
    // Optionally save the pipeline too
    if (saveAsPipeline) {
      handleSavePipeline(`${name} pipeline`, []);
    }
  }

  if (page === 'pipelines-list') {
    return (
      <PipelinesListPage
        userName="Ashwini Arumugam"
        onNavigate={handleSidebarNavigate}
      />
    );
  }

  if (page === 'components') {
    return (
      <ComponentsPage
        userName="Ashwini Arumugam"
        onNavigate={handleSidebarNavigate}
      />
    );
  }

  if (page === 'runs') {
    return (
      <RunsPage
        userName="Ashwini Arumugam"
        onNavigate={handleSidebarNavigate}
      />
    );
  }

  return (
    <div
      className="app"
      onMouseMove={e => {
        if (!leftSplitterDragging.current) return;
        const dx = e.clientX - leftSplitterStartX.current;
        setLeftPanelWidth(Math.max(180, Math.min(480, leftSplitterStartW.current + dx)));
      }}
      onMouseUp={() => { leftSplitterDragging.current = false; }}
    >
      <CompactMenu page={page} onNavigate={handleNavigate} />
      <div className="app__main">
        <Header title={selectedWorkbook} />
        <div className="app__workspace">
          <SecondaryPanel
            width={leftPanelWidth}
            selectedWorkbook={selectedWorkbook}
            onSelectWorkbook={setSelectedWorkbook}
            savedPipelines={savedPipelines}
            modelTrainingExtras={modelTrainingExtras}
            registeredModels={registeredModels}
          />
          <div className="resize-handle-v" onMouseDown={handleLeftSplitterMouseDown} />
          {page === 'pipelines' ? (
            <CanvasArea
              onNavigate={handleNavigate}
              onDropComponent={name => setPendingDrop(name)}
            />
          ) : (
            <VisionPage
              visionView={visionView}
              onVisionViewChange={setVisionView}
              onSavePipeline={handleSavePipeline}
              onAddToModelTraining={handleAddToModelTraining}
              onRegisterModel={handleRegisterModel}
              pendingDrop={pendingDrop}
              onPendingDropHandled={() => setPendingDrop(null)}
              selectedWorkbook={selectedWorkbook}
            />
          )}
        </div>
      </div>
      {page === 'registry' && <ModelRegistryPage onBack={() => handleNavigate('pipelines')} />}
    </div>
  );
}

function App() {
  return (
    <ToastProvider>
      <AppDataProvider userName="Ashwini Arumugam">
        <AppInner />
      </AppDataProvider>
    </ToastProvider>
  );
}

export default App;
