import React, { useState, useMemo } from "react";
import {
  Lock, Unlock, RotateCcw, Copy, Check, ChevronDown,
  AlertTriangle, CheckCircle2, Plug, Box, GitBranch, SlidersHorizontal, FileOutput
} from "lucide-react";

// ─── Defaults ────────────────────────────────────────────────────────────────
const DEFAULTS = {
  tool:          "3DX",
  url:           "",
  auth_token:    "",
  model_id:      "",
  model_version: "latest",
  output_format: "STEP",
  design_vars: {
    cant:   { min: 25,  max: 40,  enabled: true },
    sweep:  { min: 20,  max: 35,  enabled: true },
    height: { min: 150, max: 220, enabled: true },
    twist:  { min: 0,   max: 4,   enabled: true },
  },
};

const TOOLS = ["3DX", "CATIA", "NX"];

const TOOL_URL_PLACEHOLDER = {
  "3DX":   "https://3dx.internal.corp/api/v2",
  "CATIA": "https://catia.internal.corp/plm/v1",
  "NX":    "https://nx.internal.corp/api/v2",
};

const MODEL_VERSIONS = [
  { id: "latest", label: "latest",  note: "auto-tracks HEAD" },
  { id: "rev-14", label: "rev-14",  note: "2 days ago" },
  { id: "rev-13", label: "rev-13",  note: "1 week ago" },
  { id: "rev-12", label: "rev-12",  note: "3 weeks ago" },
];

const OUTPUT_FORMATS = ["STEP", "JT", "IGES"];

const VAR_META = {
  cant:   { label: "Cant angle",  unit: "°",  absMin: 0,   absMax: 90,  step: 1  },
  sweep:  { label: "Sweep angle", unit: "°",  absMin: 0,   absMax: 90,  step: 1  },
  height: { label: "Height",      unit: "mm", absMin: 50,  absMax: 500, step: 5  },
  twist:  { label: "Twist",       unit: "°",  absMin: -10, absMax: 20,  step: 0.5 },
};

// ─── Serialisers ─────────────────────────────────────────────────────────────
function toYAML(cfg) {
  const dvLines = Object.entries(cfg.design_vars)
    .filter(([, v]) => v.enabled)
    .map(([k, v]) => {
      const m = VAR_META[k];
      return `    ${k}:\n      min: ${v.min}${m.unit}\n      max: ${v.max}${m.unit}`;
    }).join("\n");
  return `# CAD Importer Configuration
# Generated by Flux Pipelines — ${new Date().toISOString().slice(0, 10)}

connection:
  tool: ${cfg.tool}
  url: "${cfg.url || "<not set>"}"
  auth_token: "${cfg.auth_token ? "***" : "<not set>"}"

fetch:
  model_id: "${cfg.model_id || "<not set>"}"
  version: "${cfg.model_version}"

output:
  format: ${cfg.output_format}

design_variables:
${dvLines || "    # none enabled"}
`;
}

function toAPIJson(cfg) {
  const dvObj = Object.fromEntries(
    Object.entries(cfg.design_vars)
      .filter(([, v]) => v.enabled)
      .map(([k, v]) => [k, { min: v.min, max: v.max, unit: VAR_META[k].unit }])
  );
  return JSON.stringify({
    connection: { tool: cfg.tool, url: cfg.url || null, auth_token: cfg.auth_token ? "***" : null },
    fetch:      { model_id: cfg.model_id || null, version: cfg.model_version },
    output:     { format: cfg.output_format },
    design_variables: dvObj,
  }, null, 2);
}

// ─── Sub-components ───────────────────────────────────────────────────────────
function SectionHeader({ icon: Icon, label }) {
  return (
    <div className="flex items-center gap-2 mb-3">
      <Icon size={13} className="text-[#aaabb1] shrink-0" />
      <span className="text-[11px] font-semibold uppercase tracking-widest text-[#aaabb1] opacity-60">
        {label}
      </span>
    </div>
  );
}

function Field({ label, hint, children }) {
  return (
    <div className="mb-3">
      <div className="flex items-baseline justify-between mb-1">
        <label className="text-[11px] text-[#aaabb1]">{label}</label>
        {hint && <span className="text-[10px] text-[#aaabb1] opacity-40">{hint}</span>}
      </div>
      {children}
    </div>
  );
}

function TextInput({ value, onChange, placeholder, masked, disabled }) {
  return (
    <input
      type={masked ? "password" : "text"}
      value={value}
      onChange={e => onChange(e.target.value)}
      placeholder={placeholder}
      disabled={disabled}
      className="w-full bg-[#1d2024] border border-[#2e3035] rounded px-2.5 py-1.5 text-[12px] text-white
        placeholder-[#aaabb1]/30 focus:outline-none focus:border-[#aaabb1]/40
        disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
    />
  );
}

function ToolSelector({ value, onChange, disabled }) {
  return (
    <div className="flex gap-2">
      {TOOLS.map(t => (
        <button
          key={t}
          disabled={disabled}
          onClick={() => !disabled && onChange(t)}
          className={`flex-1 py-1.5 rounded border text-[12px] font-medium transition-all
            disabled:opacity-40 disabled:cursor-not-allowed
            ${value === t
              ? "border-[#aaabb1]/40 bg-[#2e3035] text-white"
              : "border-[#2e3035] text-[#aaabb1] hover:border-[#aaabb1]/30 hover:text-white"}`}
        >
          {t}
        </button>
      ))}
    </div>
  );
}

function Select({ value, options, onChange, disabled }) {
  const [open, setOpen] = useState(false);
  const selected = options.find(o => (o.id ?? o) === value);
  return (
    <div className="relative">
      <button
        onClick={() => !disabled && setOpen(v => !v)}
        disabled={disabled}
        className="w-full flex items-center justify-between bg-[#1d2024] border border-[#2e3035]
          rounded px-2.5 py-1.5 text-[12px] text-white hover:border-[#aaabb1]/40
          disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
      >
        <span>
          {selected?.label ?? value}
          {selected?.note && <span className="text-[#aaabb1] opacity-40 ml-2">— {selected.note}</span>}
        </span>
        <ChevronDown size={12} className={`text-[#aaabb1] transition-transform ${open ? "rotate-180" : ""}`} />
      </button>
      {open && (
        <div className="absolute z-50 top-full left-0 right-0 mt-1 bg-[#1d2024] border border-[#2e3035]
          rounded shadow-xl overflow-hidden">
          {options.map(opt => {
            const id = opt.id ?? opt; const lbl = opt.label ?? opt;
            return (
              <button key={id} onClick={() => { onChange(id); setOpen(false); }}
                className={`w-full text-left px-3 py-2 text-[12px] flex justify-between
                  hover:bg-[#2e3035] transition-colors
                  ${value === id ? "text-white" : "text-[#aaabb1]"}`}>
                <span>{lbl}</span>
                {opt.note && <span className="text-[10px] opacity-40">{opt.note}</span>}
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
}

function FormatPills({ value, onChange, disabled }) {
  return (
    <div className="flex gap-2">
      {OUTPUT_FORMATS.map(fmt => (
        <button key={fmt} disabled={disabled} onClick={() => !disabled && onChange(fmt)}
          className={`px-3 py-1 rounded text-[12px] font-mono border transition-all
            disabled:opacity-40 disabled:cursor-not-allowed
            ${value === fmt
              ? "border-[#aaabb1]/40 bg-[#2e3035] text-white"
              : "border-[#2e3035] text-[#aaabb1] hover:border-[#aaabb1]/30 hover:text-white"}`}>
          .{fmt}
        </button>
      ))}
    </div>
  );
}

// Range row — toggle + dual number inputs for min/max
function DesignVarRow({ id, val, onChange, disabled }) {
  const m = VAR_META[id];
  const set = (field, raw) => {
    const n = parseFloat(raw);
    if (isNaN(n)) return;
    onChange({ ...val, [field]: n });
  };
  return (
    <div className={`rounded border transition-all ${val.enabled ? "border-[#2e3035] bg-[#1d2024]" : "border-[#2e3035]/50 bg-transparent opacity-50"}`}>
      {/* Header row: toggle + label */}
      <button
        disabled={disabled}
        onClick={() => !disabled && onChange({ ...val, enabled: !val.enabled })}
        className="w-full flex items-center gap-2.5 px-3 py-2 disabled:cursor-not-allowed"
      >
        <div className={`w-3 h-3 rounded-sm border flex items-center justify-center shrink-0 transition-colors
          ${val.enabled ? "border-[#aaabb1]/50 bg-[#2e3035]" : "border-[#2e3035]"}`}>
          {val.enabled && (
            <svg width="7" height="5" viewBox="0 0 7 5" fill="none">
              <path d="M1 2.5L2.5 4L6 1" stroke="white" strokeWidth="1.2" strokeLinecap="round" strokeLinejoin="round"/>
            </svg>
          )}
        </div>
        <span className="text-[12px] text-white text-left flex-1">{m.label}</span>
        <span className="text-[10px] text-[#aaabb1] opacity-40">{m.unit}</span>
      </button>

      {/* Range inputs */}
      {val.enabled && (
        <div className="flex items-center gap-2 px-3 pb-2.5">
          <div className="flex-1">
            <div className="text-[10px] text-[#aaabb1] opacity-40 mb-1">min</div>
            <div className="flex items-center gap-1">
              <input
                type="number"
                value={val.min}
                min={m.absMin} max={val.max - m.step} step={m.step}
                disabled={disabled}
                onChange={e => set("min", e.target.value)}
                className="w-full bg-[#111318] border border-[#2e3035] rounded px-2 py-1 text-[12px]
                  text-white focus:outline-none focus:border-[#aaabb1]/40
                  disabled:opacity-40 disabled:cursor-not-allowed [appearance:textfield]
                  [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
              />
              <span className="text-[11px] text-[#aaabb1] opacity-40 shrink-0">{m.unit}</span>
            </div>
          </div>
          <div className="text-[#2e3035] text-[11px] mt-4">—</div>
          <div className="flex-1">
            <div className="text-[10px] text-[#aaabb1] opacity-40 mb-1">max</div>
            <div className="flex items-center gap-1">
              <input
                type="number"
                value={val.max}
                min={val.min + m.step} max={m.absMax} step={m.step}
                disabled={disabled}
                onChange={e => set("max", e.target.value)}
                className="w-full bg-[#111318] border border-[#2e3035] rounded px-2 py-1 text-[12px]
                  text-white focus:outline-none focus:border-[#aaabb1]/40
                  disabled:opacity-40 disabled:cursor-not-allowed [appearance:textfield]
                  [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none"
              />
              <span className="text-[11px] text-[#aaabb1] opacity-40 shrink-0">{m.unit}</span>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function CodeBlock({ code, lang }) {
  const [copied, setCopied] = useState(false);
  return (
    <div className="relative rounded border border-[#2e3035] bg-[#0c0e13] overflow-hidden">
      <div className="flex items-center justify-between px-3 py-1.5 border-b border-[#2e3035]">
        <span className="text-[10px] text-[#aaabb1] opacity-40 font-mono">{lang}</span>
        <button onClick={() => { navigator.clipboard.writeText(code); setCopied(true); setTimeout(() => setCopied(false), 1500); }}
          className="text-[#aaabb1] hover:text-white transition-colors">
          {copied ? <Check size={12} className="text-green-400" /> : <Copy size={12} />}
        </button>
      </div>
      <pre className="p-3 text-[11px] font-mono text-[#aaabb1] overflow-x-auto whitespace-pre leading-relaxed">{code}</pre>
    </div>
  );
}

// ─── Main ─────────────────────────────────────────────────────────────────────
export default function CADImporterConfig({ locked = false, onClose, onRun, onConfigChange, initialTool, initialVersion }) {
  const [cfg, setCfg]         = useState(() => ({
    ...DEFAULTS,
    tool:          initialTool    || DEFAULTS.tool,
    model_version: initialVersion || DEFAULTS.model_version,
  }));
  const [isLocked, setLocked] = useState(locked);
  const [tab, setTab]         = useState("ui");

  const set = (key, val) => {
    if (!isLocked) setCfg(prev => {
      const next = { ...prev, [key]: val };
      if (key === "tool" || key === "model_version") {
        onConfigChange?.({ tool: next.tool, version: next.model_version });
      }
      return next;
    });
  };
  const setDV  = (id, val)  => { if (!isLocked) setCfg(prev => ({ ...prev, design_vars: { ...prev.design_vars, [id]: val } })); };
  const reset  = ()         => { if (!isLocked) { setCfg(DEFAULTS); onConfigChange?.({ tool: DEFAULTS.tool, version: DEFAULTS.model_version }); } };

  const yaml    = useMemo(() => toYAML(cfg),   [cfg]);
  const apiJson = useMemo(() => toAPIJson(cfg), [cfg]);

  const noToken    = !cfg.auth_token;
  const noModel    = !cfg.model_id;
  const noVarsEnabled = Object.values(cfg.design_vars).every(v => !v.enabled);

  return (
    <div className="flex flex-col h-full bg-[#111318] text-white overflow-hidden select-none">

      {/* Header */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-[#2e3035] shrink-0">
        <div className="flex items-center gap-2">
          <Box size={14} className="text-[#aaabb1]" />
          <span className="text-[13px] font-semibold">CAD Importer</span>
          <span className="text-[10px] text-[#aaabb1] opacity-50 bg-[#1d2024] px-1.5 py-0.5 rounded border border-[#2e3035]">
            {cfg.tool}
          </span>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={reset} disabled={isLocked}
            className="text-[#aaabb1] hover:text-white disabled:opacity-30 transition-colors" title="Reset">
            <RotateCcw size={13} />
          </button>
          <button onClick={() => setLocked(v => !v)}
            className="text-[#aaabb1] hover:text-white transition-colors">
            {isLocked ? <Lock size={13} /> : <Unlock size={13} />}
          </button>
          {onClose && (
            <button onClick={onClose} className="text-[#aaabb1] hover:text-white transition-colors ml-1" title="Close">
              <svg width="13" height="13" viewBox="0 0 13 13" fill="none"><path d="M2 2L11 11M11 2L2 11" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round"/></svg>
            </button>
          )}
        </div>
      </div>

      {/* ── Persistent selectors — visible on all tabs ── */}
      <div className="shrink-0 px-4 py-3 border-b border-[#2e3035] flex flex-col gap-3">
        <div className="flex items-center gap-3">
          <span className="text-[11px] text-[#aaabb1] opacity-60 w-14 shrink-0">Tool</span>
          <div className="flex-1">
            <ToolSelector value={cfg.tool} onChange={v => set("tool", v)} disabled={isLocked} />
          </div>
        </div>
        <div className="flex items-center gap-3">
          <span className="text-[11px] text-[#aaabb1] opacity-60 w-14 shrink-0">Version</span>
          <div className="flex-1">
            <Select
              value={cfg.model_version}
              options={MODEL_VERSIONS}
              onChange={v => set("model_version", v)}
              disabled={isLocked}
            />
          </div>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex border-b border-[#2e3035] shrink-0">
        {["ui", "yaml"].map(t => (
          <button key={t} onClick={() => setTab(t)}
            className={`px-4 py-2 text-[11px] font-medium uppercase tracking-wider transition-colors border-b-2
              ${tab === t ? "border-white text-white" : "border-transparent text-[#aaabb1] hover:text-white"}`}>
            {t === "api" ? "API" : t.toUpperCase()}
          </button>
        ))}
      </div>

      {/* Warnings */}
      {(noToken || noModel) && tab === "ui" && (
        <div className="shrink-0 px-4 pt-3 flex flex-col gap-2">
          {noToken && (
            <div className="flex items-center gap-2 px-3 py-2 rounded border border-[#2e3035] bg-[#1d2024] text-[#aaabb1] text-[11px]">
              <AlertTriangle size={11} className="shrink-0 text-amber-400" />
              Auth token not set — connection will fail at runtime
            </div>
          )}
          {noModel && (
            <div className="flex items-center gap-2 px-3 py-2 rounded border border-[#2e3035] bg-[#1d2024] text-[#aaabb1] text-[11px]">
              <AlertTriangle size={11} className="shrink-0 text-amber-400" />
              Model ID not set — nothing to fetch
            </div>
          )}
          {isLocked && (
            <div className="flex items-center gap-2 px-3 py-2 rounded border border-[#2e3035] bg-[#1d2024] text-[#aaabb1] text-[11px]">
              <Lock size={11} className="shrink-0" />
              Configuration is locked — unlock to edit
            </div>
          )}
        </div>
      )}

      {/* Body */}
      <div className="flex-1 overflow-y-auto px-4 py-4">
        {tab !== "ui" ? (
          <CodeBlock code={yaml} lang="yaml" />
        ) : (
          <div className="space-y-5">

            {/* ── Connection ── */}
            <div>
              <SectionHeader icon={Plug} label="Connection" />
              <Field label="URL">
                <TextInput
                  value={cfg.url}
                  onChange={v => set("url", v)}
                  placeholder={TOOL_URL_PLACEHOLDER[cfg.tool]}
                  disabled={isLocked}
                />
              </Field>
              <Field label="Auth Token" hint="stored encrypted">
                <TextInput
                  value={cfg.auth_token}
                  onChange={v => set("auth_token", v)}
                  placeholder="••••••••••••••••"
                  masked
                  disabled={isLocked}
                />
              </Field>
            </div>

            <div className="border-t border-[#2e3035]" />

            {/* ── What to fetch ── */}
            <div>
              <SectionHeader icon={Box} label="What to Fetch" />
              <Field label="Model ID" hint="winglet reference">
                <TextInput
                  value={cfg.model_id}
                  onChange={v => set("model_id", v)}
                  placeholder="e.g. winglet-blended-v2"
                  disabled={isLocked}
                />
              </Field>
            </div>

            <div className="border-t border-[#2e3035]" />

            {/* ── Output ── */}
            <div>
              <SectionHeader icon={FileOutput} label="Output" />
              <Field label="Format">
                <FormatPills value={cfg.output_format} onChange={v => set("output_format", v)} disabled={isLocked} />
              </Field>
            </div>

            <div className="border-t border-[#2e3035]" />

            {/* ── Design Variables ── */}
            <div>
              <SectionHeader icon={SlidersHorizontal} label="Design Variables to Expose" />
              <p className="text-[11px] text-[#aaabb1] opacity-50 mb-3">
                Toggle on/off and set the min–max range passed to the study driver.
              </p>
              <div className="flex flex-col gap-2">
                {Object.entries(cfg.design_vars).map(([id, val]) => (
                  <DesignVarRow key={id} id={id} val={val} onChange={v => setDV(id, v)} disabled={isLocked} />
                ))}
              </div>
              {noVarsEnabled && (
                <p className="mt-2 text-[11px] text-amber-400 opacity-80">
                  No variables enabled — nothing will be passed downstream.
                </p>
              )}
            </div>

            {/* Status */}
            <div className="flex items-center gap-2 text-[11px] text-[#aaabb1] opacity-40 pt-1">
              <CheckCircle2 size={11} className={!noToken && !noModel ? "text-green-400 opacity-100" : ""} />
              {!noToken && !noModel ? (
                <span className="text-green-400 opacity-100">Ready to run</span>
              ) : "Fix warnings above before running"}
            </div>

          </div>
        )}
      </div>
    </div>
  );
}
