export default function FlowConnectors({ connectors, direction = 'horizontal' }) {
  return (
    <svg className="px-editor__canvas-connectors">
      <defs>
        <marker id="px-flow-arrow" markerWidth="8" markerHeight="8" refX="6" refY="4" orient="auto" markerUnits="userSpaceOnUse">
          <path d="M0,0 L8,4 L0,8 Z" fill="var(--border-subtle)" />
        </marker>
      </defs>
      {connectors.map(c => {
        if (direction === 'vertical') {
          const x = (c.from.centerX + c.to.centerX) / 2;
          return (
            <line
              key={c.key}
              x1={x}
              y1={c.from.bottom}
              x2={x}
              y2={c.to.top - 2}
              stroke="var(--border-subtle)"
              strokeWidth="1.5"
              markerEnd="url(#px-flow-arrow)"
            />
          );
        }
        return c.sameRow ? (
          <line
            key={c.key}
            x1={c.from.right}
            y1={c.from.centerY}
            x2={c.to.left - 2}
            y2={c.to.centerY}
            stroke="var(--border-subtle)"
            strokeWidth="1.5"
            markerEnd="url(#px-flow-arrow)"
          />
        ) : (
          <path
            key={c.key}
            d={`M ${c.from.centerX} ${c.from.bottom} V ${(c.from.bottom + c.to.top) / 2} H ${c.to.centerX} V ${c.to.top - 2}`}
            fill="none"
            stroke="var(--border-subtle)"
            strokeWidth="1.5"
            markerEnd="url(#px-flow-arrow)"
          />
        );
      })}
    </svg>
  );
}
