import React, { useState } from "react";
import { CheckCircle2, BarChart2, ClipboardList } from "lucide-react";
import RegisterModelModal from "./RegisterModelModal";

// ─── Shared tiny helpers ──────────────────────────────────────────────────────

function SectionLabel({ children }) {
  return (
    <div style={{
      fontSize: 10, fontWeight: 700, letterSpacing: "0.1em", textTransform: "uppercase",
      color: "rgba(170,171,177,0.5)", marginBottom: 8,
    }}>
      {children}
    </div>
  );
}

function MetricRow({ name, value, threshold, thresholdLabel, pass }) {
  return (
    <div style={{
      display: "flex", alignItems: "center", justifyContent: "space-between",
      padding: "10px 14px",
      borderBottom: "1px solid rgba(46,48,53,0.7)",
    }}>
      {/* Name */}
      <span style={{ fontSize: 12, fontFamily: "monospace", color: "rgba(255,255,255,0.75)", flex: 1 }}>
        {name}
      </span>
      {/* Value */}
      <span style={{ fontSize: 13, fontFamily: "monospace", fontWeight: 600, color: pass ? "#4ade80" : "#f87171", minWidth: 60, textAlign: "right" }}>
        {value}
      </span>
      {/* Pass indicator */}
      <span style={{ fontSize: 13, margin: "0 10px", color: pass ? "#4ade80" : "#f87171" }}>
        {pass ? "✓" : "✗"}
      </span>
      {/* Threshold */}
      <span style={{ fontSize: 11, fontFamily: "monospace", color: "rgba(170,171,177,0.45)", minWidth: 110, textAlign: "right" }}>
        {thresholdLabel}: {threshold}
      </span>
    </div>
  );
}

const LOG_LINES = [
  "Loading evaluation set (held-out validation · 20% split)…",
  "Restoring trained model: winglet-gnn-v3.pt",
  "Running inference on 312 samples…",
  "Computing scalar metrics (Cd RMSE, bending_moment R², max_stress RMSE)…",
  "Generating parity plots for Cd and bending_moment…",
  "Comparing against acceptance thresholds…",
  "All 3 thresholds passed.",
  "Serialising evaluation_report.json (EvaluationArtefact)…",
  "Writing model_status: PASS",
  "Writing parity_plots/Cd_parity.png, bending_moment_parity.png…",
];

// ─── Main ─────────────────────────────────────────────────────────────────────

export default function EvaluationRunPanel({ onClose, onRegisterModel }) {
  const [tab, setTab] = useState("output");
  const [showRegister, setShowRegister] = useState(false);
  const TABS = ["output", "log"];

  return (
    <>
    {showRegister && (
      <RegisterModelModal
        onClose={() => setShowRegister(false)}
        onSaveAsPipeline={({ name, version, tags }) => {
          onRegisterModel?.({ name, version, tags, saveAsPipeline: true });
          setShowRegister(false);
        }}
        onNotNow={({ name, version, tags } = {}) => {
          onRegisterModel?.({ name, version, tags, saveAsPipeline: false });
          setShowRegister(false);
        }}
      />
    )}
    <div className="flex flex-col h-full bg-[#111318] text-white overflow-hidden select-none">

      {/* Header */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-[#2e3035] shrink-0">
        <div className="flex items-center gap-2">
          <BarChart2 size={14} className="text-[#aaabb1]" />
          <span className="text-[13px] font-semibold">Evaluation</span>
          <span className="text-[10px] text-[#aaabb1] opacity-50 bg-[#1d2024] px-1.5 py-0.5 rounded border border-[#2e3035]">
            Run
          </span>
          <span className="flex items-center gap-1 text-[10px] text-green-400">
            <CheckCircle2 size={10} /> Completed
          </span>
        </div>
        {onClose && (
          <button onClick={onClose} className="text-[#aaabb1] hover:text-white transition-colors" title="Close">
            <svg width="13" height="13" viewBox="0 0 13 13" fill="none">
              <path d="M2 2L11 11M11 2L2 11" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round"/>
            </svg>
          </button>
        )}
      </div>

      {/* Tabs */}
      <div className="flex border-b border-[#2e3035] shrink-0">
        {TABS.map(t => (
          <button key={t} onClick={() => setTab(t)}
            className={`px-4 py-2 text-[11px] font-medium uppercase tracking-wider transition-colors border-b-2
              ${tab === t ? "border-white text-white" : "border-transparent text-[#aaabb1] hover:text-white"}`}>
            {t.charAt(0).toUpperCase() + t.slice(1)}
          </button>
        ))}
      </div>

      {/* Body */}
      <div className="flex-1 overflow-y-auto px-4 py-4">

        {/* ── Output ── */}
        {tab === "output" && (
          <div style={{ display: "flex", flexDirection: "column", gap: 20 }}>

            {/* Section header */}
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}>
              <SectionLabel>Evaluation Results</SectionLabel>
              <span style={{ fontSize: 11, color: "#4ade80", fontFamily: "monospace" }}>✓ complete</span>
            </div>

            {/* Metrics table */}
            <div style={{
              border: "1px solid #2e3035", borderRadius: 8, overflow: "hidden",
              background: "#13161c",
            }}>
              {/* Column headers */}
              <div style={{
                display: "flex", alignItems: "center", justifyContent: "space-between",
                padding: "7px 14px", background: "#0e1014",
                borderBottom: "1px solid #2e3035",
              }}>
                <span style={{ fontSize: 10, fontFamily: "monospace", color: "rgba(170,171,177,0.4)", flex: 1 }}>metric</span>
                <span style={{ fontSize: 10, fontFamily: "monospace", color: "rgba(170,171,177,0.4)", minWidth: 60, textAlign: "right" }}>value</span>
                <span style={{ fontSize: 10, fontFamily: "monospace", color: "rgba(170,171,177,0.4)", margin: "0 10px", width: 16 }} />
                <span style={{ fontSize: 10, fontFamily: "monospace", color: "rgba(170,171,177,0.4)", minWidth: 110, textAlign: "right" }}>acceptance</span>
              </div>
              <MetricRow
                name="Cd RMSE"
                value="0.0008"
                thresholdLabel="threshold"
                threshold="0.001"
                pass
              />
              <MetricRow
                name="bending_moment R²"
                value="0.97"
                thresholdLabel="minimum"
                threshold="0.95"
                pass
              />
              <div style={{ borderBottom: "none" }}>
                <MetricRow
                  name="max_stress RMSE"
                  value="12 MPa"
                  thresholdLabel="threshold"
                  threshold="15 MPa"
                  pass
                />
              </div>
            </div>

            {/* Divider */}
            <div style={{ borderTop: "1px solid #2e3035" }} />

            {/* Status banner */}
            <div style={{
              background: "rgba(34,197,94,0.08)", border: "1px solid rgba(34,197,94,0.3)",
              borderRadius: 8, padding: "14px 16px",
              display: "flex", alignItems: "flex-start", gap: 10,
            }}>
              <CheckCircle2 size={16} style={{ color: "#4ade80", flexShrink: 0, marginTop: 1 }} />
              <div>
                <div style={{ fontSize: 13, fontWeight: 600, color: "#4ade80", marginBottom: 4 }}>
                  Status: PASS
                </div>
                <div style={{ fontSize: 12, color: "rgba(255,255,255,0.55)", lineHeight: 1.55 }}>
                  Model meets all acceptance criteria
                </div>
              </div>
            </div>

            {/* Separator line */}
            <div style={{ borderTop: "1px solid rgba(46,48,53,0.8)" }} />

            {/* Register model CTA */}
            <button
              onClick={() => setShowRegister(true)}
              style={{
                display: "flex", alignItems: "center", justifyContent: "center", gap: 8,
                background: "rgba(59,130,246,0.12)", border: "1px solid rgba(59,130,246,0.35)",
                borderRadius: 8, padding: "10px 16px", cursor: "pointer",
                fontSize: 13, fontWeight: 600, color: "#93c5fd",
                transition: "background 0.15s, border-color 0.15s",
                width: "100%",
              }}
              onMouseEnter={e => { e.currentTarget.style.background = "rgba(59,130,246,0.22)"; e.currentTarget.style.borderColor = "rgba(59,130,246,0.6)"; }}
              onMouseLeave={e => { e.currentTarget.style.background = "rgba(59,130,246,0.12)"; e.currentTarget.style.borderColor = "rgba(59,130,246,0.35)"; }}
            >
              <ClipboardList size={14} />
              Register model →
            </button>

          </div>
        )}

        {/* ── Log ── */}
        {tab === "log" && (
          <div className="rounded border border-[#2e3035] bg-[#0c0e13] overflow-hidden">
            <div className="flex items-center justify-between px-3 py-1.5 border-b border-[#2e3035]">
              <span className="text-[10px] font-mono text-[#aaabb1] opacity-50">run log</span>
              <CheckCircle2 size={11} className="text-green-400" />
            </div>
            <div className="p-3 space-y-1.5">
              {LOG_LINES.map((line, i) => (
                <div key={i} className="flex items-start gap-2 text-[11px] font-mono text-[#aaabb1]">
                  <span className="shrink-0 mt-px">
                    <svg width="10" height="10" viewBox="0 0 10 10" fill="none">
                      <path d="M2 5.5L4 7.5L8 3" stroke="#4ade80" strokeWidth="1.3" strokeLinecap="round" strokeLinejoin="round"/>
                    </svg>
                  </span>
                  {line}
                </div>
              ))}
              <div className="mt-2 pt-2 border-t border-[#2e3035] text-[11px] text-green-400 font-mono">
                ✓ Run complete — evaluation_report.json · model_status: PASS
              </div>
            </div>
          </div>
        )}

      </div>
    </div>
    </>
  );
}
