import React from "react";

// ─── Initials helper ──────────────────────────────────────────────────────────
function initials(name) {
  if (!name) return "?";
  return name.split(/\s+/).map(w => w[0] || "").join("").slice(0, 2).toUpperCase();
}

// ─── Pipeline components strip ────────────────────────────────────────────────
function PipelineStrip({ components }) {
  if (!components || components.length === 0) return null;
  return (
    <div style={{ padding: "12px 24px", borderBottom: "1px solid #2e3035", flexShrink: 0, background: "#0e1014" }}>
      {/* Label row */}
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 10 }}>
        <span style={{ fontSize: 10, fontWeight: 700, letterSpacing: "0.12em", color: "rgba(170,171,177,0.5)", textTransform: "uppercase" }}>
          Pipeline components
        </span>
        <span style={{
          fontSize: 11, fontWeight: 700, fontFamily: "monospace",
          color: "#3b82f6", background: "rgba(59,130,246,0.15)",
          border: "1px solid rgba(59,130,246,0.3)",
          borderRadius: 4, padding: "1px 6px",
        }}>{components.length}</span>
      </div>

      {/* Component pills */}
      <div style={{ display: "flex", alignItems: "center", gap: 6, flexWrap: "wrap" }}>
        {components.map((name, i) => (
          <React.Fragment key={i}>
            <div style={{ display: "flex", alignItems: "center", gap: 6, background: "#16191f", border: "1px solid #2e3035", borderRadius: 7, padding: "5px 10px" }}>
              {/* Initials badge */}
              <div style={{
                width: 22, height: 22, borderRadius: 5, flexShrink: 0,
                background: "rgba(255,255,255,0.06)", border: "1px solid rgba(255,255,255,0.1)",
                display: "flex", alignItems: "center", justifyContent: "center",
              }}>
                <span style={{ fontSize: 9, fontWeight: 700, color: "rgba(255,255,255,0.7)", fontFamily: "monospace", letterSpacing: "0.01em" }}>
                  {initials(name)}
                </span>
              </div>
              <span style={{ fontSize: 12, color: "rgba(255,255,255,0.75)", whiteSpace: "nowrap" }}>{name}</span>
            </div>
            {i < components.length - 1 && (
              <svg width="10" height="10" viewBox="0 0 10 10" fill="none" style={{ flexShrink: 0 }}>
                <path d="M2 5h6M6 2l3 3-3 3" stroke="rgba(170,171,177,0.3)" strokeWidth="1.2" strokeLinecap="round" strokeLinejoin="round"/>
              </svg>
            )}
          </React.Fragment>
        ))}
      </div>
    </div>
  );
}

// ─── Main ─────────────────────────────────────────────────────────────────────
export default function RunPipelineModal({ onClose, onLaunch, pipelineComponents = [] }) {
  return (
    /* Overlay */
    <div
      style={{
        position: "fixed", inset: 0, zIndex: 1000,
        background: "rgba(0,0,0,0.65)", backdropFilter: "blur(2px)",
        display: "flex", alignItems: "center", justifyContent: "center",
      }}
      onClick={e => { if (e.target === e.currentTarget) onClose(); }}
    >
      {/* Modal */}
      <div style={{
        width: 520, background: "#16191f",
        border: "1px solid #2e3035", borderRadius: 16,
        display: "flex", flexDirection: "column", overflow: "hidden",
        boxShadow: "0 24px 80px rgba(0,0,0,0.6)",
      }}>

        {/* Header */}
        <div style={{ padding: "20px 24px 16px", borderBottom: "1px solid #2e3035", flexShrink: 0 }}>
          <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between" }}>
            <div>
              <div style={{ fontSize: 18, fontWeight: 700, color: "#fff", marginBottom: 4 }}>Run pipeline</div>
              <div style={{ fontSize: 12, fontFamily: "monospace", color: "rgba(170,171,177,0.5)" }}>
                Winglet Simulation
              </div>
            </div>
            <button onClick={onClose} style={{ background: "none", border: "none", color: "rgba(170,171,177,0.5)", cursor: "pointer", fontSize: 18, lineHeight: 1, padding: 2 }}
              onMouseEnter={e => e.currentTarget.style.color = "#fff"}
              onMouseLeave={e => e.currentTarget.style.color = "rgba(170,171,177,0.5)"}
            >×</button>
          </div>
        </div>

        {/* Pipeline components strip */}
        <PipelineStrip components={pipelineComponents} />

        {/* Body */}
        <div style={{ padding: "20px 24px" }}>
          <div style={{
            background: "#0e1014", border: "1px solid #2e3035", borderRadius: 8,
            padding: "14px 16px", display: "flex", alignItems: "center", gap: 10,
          }}>
            {/* Status dot */}
            <div style={{
              width: 8, height: 8, borderRadius: "50%",
              background: "#22c55e", flexShrink: 0,
              boxShadow: "0 0 6px rgba(34,197,94,0.5)",
            }} />
            <div>
              <div style={{ fontSize: 13, color: "rgba(255,255,255,0.85)", fontWeight: 500 }}>
                Ready to launch
              </div>
              <div style={{ fontSize: 11, color: "rgba(170,171,177,0.5)", marginTop: 2 }}>
                Study driver and parameters are defined in the pipeline
              </div>
            </div>
          </div>
        </div>

        {/* Footer */}
        <div style={{
          padding: "14px 24px", borderTop: "1px solid #2e3035", flexShrink: 0,
          display: "flex", alignItems: "center", justifyContent: "flex-end", gap: 8,
        }}>
          <button onClick={onClose}
            style={{
              background: "#1a1d23", border: "1px solid #2e3035", borderRadius: 8,
              color: "rgba(255,255,255,0.75)", fontSize: 13, fontWeight: 500,
              padding: "8px 18px", cursor: "pointer",
            }}
            onMouseEnter={e => e.currentTarget.style.borderColor = "#aaabb1"}
            onMouseLeave={e => e.currentTarget.style.borderColor = "#2e3035"}
          >Cancel</button>
          <button onClick={() => { onLaunch?.(); onClose(); }}
            style={{
              background: "#3b82f6", border: "none", borderRadius: 8,
              color: "#fff", fontSize: 13, fontWeight: 600,
              padding: "8px 20px", cursor: "pointer",
            }}
            onMouseEnter={e => e.currentTarget.style.background = "#2563eb"}
            onMouseLeave={e => e.currentTarget.style.background = "#3b82f6"}
          >Launch →</button>
        </div>

      </div>
    </div>
  );
}
