import PipelineRunPage from './PipelineRunPage';
import FlowConnectors from './FlowConnectors';
import { useNodeConnectors } from './useNodeConnectors';
import { getControllerIcon, getNodeIcon } from './PipelineEditorPage';
import { recordRun } from './runsStore';
import './PipelinesListPage.css';
import './PipelineEditorPage.css';
import './PipelineViewPage.css';

function generateRunId() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
}

const NODE_STATUS_LABELS = { pending: 'Pending', running: 'Running', success: 'Success', failed: 'Failed' };

function StatusDot({ status }) {
  if (!status) return null;
  const label = NODE_STATUS_LABELS[status];
  return <span className={`px-view__status-dot px-view__status-dot--${status}`} aria-label={label} title={label} />;
}

export function ReadOnlyPipelineCanvas({ nodes, selectedNodeId, onSelectNode, onDeselect, emptyMessage, className, style, direction = 'horizontal', getNodeStatus }) {
  const { containerRef: canvasFlowRef, setNodeRef, connectors } = useNodeConnectors(nodes.map(n => n.id));

  return (
    <div className={`px-editor__canvas${className ? ` ${className}` : ''}`} style={style} onClick={onDeselect}>
      {nodes.length === 0 ? (
        <div className="px-editor__canvas-empty">{emptyMessage || 'This pipeline has no components yet'}</div>
      ) : (
        <div className={`px-editor__canvas-flow${direction === 'vertical' ? ' px-editor__canvas-flow--vertical' : ''}`} ref={canvasFlowRef}>
          <FlowConnectors connectors={connectors} direction={direction} />
          {nodes.map(node => (
            <div className="px-editor__node-wrap" key={node.id} ref={setNodeRef(node.id)}>
              {node.isGroup ? (
                <div
                  className={`px-editor__group-frame${selectedNodeId === node.id ? ' px-editor__group-frame--selected' : ''}`}
                  onClick={e => { e.stopPropagation(); onSelectNode(node.id); }}
                >
                  {(() => {
                    const ControllerIcon = getControllerIcon(node.name);
                    return (
                      <span className="px-editor__group-frame__pill">
                        <ControllerIcon size={14} />
                        {node.name}
                      </span>
                    );
                  })()}
                  {(!node.children || node.children.length === 0) ? (
                    <div className="px-editor__group-frame__empty">No components in this study</div>
                  ) : (
                    <div className="px-editor__group-frame__children">
                      {node.children.map((child, i) => (
                        <div key={child.id} className="px-editor__group-frame__child-wrap">
                          <div
                            className={`px-editor__group-frame__child${selectedNodeId === child.id ? ' px-editor__group-frame__child--selected' : ''}`}
                            onClick={e => { e.stopPropagation(); onSelectNode(child.id); }}
                          >
                            <div className="px-editor__group-frame__child-text">
                              <span className="px-editor__group-frame__child-name-row">
                                {(() => {
                                  const ChildIcon = getNodeIcon(child);
                                  return (
                                    <span className="px-editor__component-icon">
                                      <ChildIcon size={12} />
                                    </span>
                                  );
                                })()}
                                <span className="px-editor__group-frame__child-name">{child.name}</span>
                              </span>
                              <div className="px-editor__node-bottom-row">
                                <span className="px-editor__group-frame__child-desc">{child.description}</span>
                                <StatusDot status={getNodeStatus?.(child)} />
                              </div>
                            </div>
                          </div>
                          {i < node.children.length - 1 && (
                            <div className="px-editor__group-frame__connector">
                              <span className="px-editor__group-frame__connector-line" />
                              <svg width="12" height="10" viewBox="0 0 12 10" className="px-editor__group-frame__connector-arrow">
                                <path d="M1,0 L11,0 L6,9 Z" fill="var(--on-fill-subtle)" />
                              </svg>
                            </div>
                          )}
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              ) : (
                <div
                  className={`px-editor__node px-view__node${selectedNodeId === node.id ? ' px-editor__node--selected' : ''}`}
                  onClick={e => { e.stopPropagation(); onSelectNode(node.id); }}
                >
                  <div className="px-editor__node-header">
                    {(() => {
                      const NodeIcon = getNodeIcon(node);
                      return (
                        <span className="px-editor__component-icon">
                          <NodeIcon size={12} />
                        </span>
                      );
                    })()}
                    <span className="px-editor__node-name">{node.name}</span>
                  </div>
                  <div className="px-editor__node-bottom-row">
                    <span className="px-editor__node-desc">{node.version || 'v1.0'}</span>
                    <StatusDot status={getNodeStatus?.(node)} />
                  </div>
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default function PipelineViewPage({ pipeline, userName, onBack, onNavigate, onEdit, onDeletePipeline, onRunRecorded, autoRun, onAutoRunConsumed }) {
  const canvasNodes = pipeline.canvasNodes || [];

  function startRun({ runName, studyName, description, runScope, nodes, runType }) {
    onRunRecorded?.({
      id: generateRunId(),
      runName,
      studyName: studyName || '--',
      description,
      runScope,
      nodes,
      version: pipeline.version || 'v0.1',
      type: pipeline.type,
      startedAt: Date.now(),
    });
    recordRun({ pipeline, runName, studyName, description, runScope, nodes, runType, userName });
  }

  return (
    <PipelineRunPage
      pipeline={pipeline}
      userName={userName}
      onNavigate={onNavigate}
      onBack={onBack}
      onEdit={onEdit}
      onDeletePipeline={onDeletePipeline}
      onStartRun={({ runName, studyName, description, runScope, nodes }) => startRun({ runName, studyName, description, runScope, nodes: nodes && nodes.length ? nodes : canvasNodes, runType: 'pipeline' })}
      autoOpenRunModal={autoRun}
      onAutoOpenRunModalConsumed={onAutoRunConsumed}
    />
  );
}
