import { useState } from 'react';
import { ChevronLeft, Plus } from 'lucide-react';

import AppSidebar from './AppSidebar';
import ConfirmDeleteModal from './ConfirmDeleteModal';
import './PipelinesListPage.css';
import './PipelineEditorPage.css';
import './SimulationComponentDetailPage.css';

export function buildSchemaYaml(fields) {
  const required = fields.filter(f => f.required).map(f => f.key);
  const lines = ['type: object'];
  if (required.length > 0) {
    lines.push('required:');
    required.forEach(key => lines.push(`  - ${key}`));
  }
  lines.push('properties:');
  fields.forEach(field => {
    lines.push(`  ${field.key}:`);
    if (field.type === 'list') {
      lines.push('    type: array');
      lines.push('    itemsType: string');
    } else if (field.type === 'params') {
      lines.push('    type: object');
    } else {
      lines.push('    type: string');
    }
    lines.push(`    description: ${field.helper}`);
  });
  return lines.join('\n');
}

function SchemaLine({ text }) {
  const keyMatch = text.match(/^(\s*)([\w]+):(.*)$/);
  if (keyMatch) {
    const [, indent, key, rest] = keyMatch;
    return <div>{indent}<span className="px-sim-detail__schema-key">{key}</span>:{rest}</div>;
  }
  return <div>{text || ' '}</div>;
}

export function SchemaCodeBlock({ yaml }) {
  const lines = yaml.split('\n');
  return (
    <div className="px-sim-detail__schema-code">
      <div className="px-editor__config-gutter">
        {lines.map((_, i) => <div key={i}>{i + 1}</div>)}
      </div>
      <pre className="px-sim-detail__schema-lines">
        {lines.map((line, i) => <SchemaLine key={i} text={line} />)}
      </pre>
    </div>
  );
}

function ConfigField({ field, value, onChange }) {
  if (field.type === 'params') {
    return (
      <div className="px-sim-detail__config-field">
        <div className="px-sim-detail__config-label">{field.label}</div>
        <button type="button" className="px-sim-detail__params-btn">Edit (No entries)</button>
        {field.helper && <div className="px-sim-detail__config-helper">{field.helper}</div>}
      </div>
    );
  }
  if (field.type === 'list') {
    return (
      <div className="px-sim-detail__config-field">
        <div className="px-sim-detail__config-label">
          {field.label}
          {field.required && <span className="px-sim-detail__required">*</span>}
        </div>
        <button type="button" className="px-sim-detail__add-btn">
          <Plus size={14} />
          Add
        </button>
        {field.helper && <div className="px-sim-detail__config-helper">{field.helper}</div>}
      </div>
    );
  }
  return (
    <div className="px-sim-detail__config-field">
      <div className="px-sim-detail__config-label">
        {field.label}
        {field.required && <span className="px-sim-detail__required">*</span>}
      </div>
      <input
        type="text"
        className="px-sim-detail__config-input"
        value={value || ''}
        onChange={e => onChange(field.key, e.target.value)}
      />
      {field.helper && <div className="px-sim-detail__config-helper">{field.helper}</div>}
    </div>
  );
}

export default function SimulationComponentDetailPage({ component, userName, onNavigate, onBack, onDelete }) {
  const [activeSchemaTab, setActiveSchemaTab] = useState('input');
  const [confirmDeleteOpen, setConfirmDeleteOpen] = useState(false);
  const [fieldValues, setFieldValues] = useState({});
  const detail = component.detail || {};
  const inputFields = detail.inputFields || [];
  const outputFields = detail.outputFields || [];

  function handleFieldChange(key, value) {
    setFieldValues(prev => ({ ...prev, [key]: value }));
  }

  return (
    <div className="px-pipelines">
      <AppSidebar activeItem="components" onNavigate={onNavigate} userName={userName} />

      <div className="px-pipelines__main">
        <header className="px-pipelines__header">
          <div className="px-sim-detail__header-left">
            <button type="button" className="px-editor__back" aria-label="Back" title="Back" onClick={onBack}>
              <ChevronLeft size={16} />
            </button>
            <h1 className="px-pipelines__title">{component.name}</h1>
          </div>
          <div className="px-pipelines__header-actions">
            <button type="button" className="px-sim-detail__delete-btn" onClick={() => setConfirmDeleteOpen(true)}>
              Delete component
            </button>
          </div>
        </header>

        <div className="px-sim-detail__body">
          <div className="px-sim-detail__main">
            <section>
              <h2 className="px-sim-detail__section-title">Basic Information</h2>
              <div className="px-sim-detail__grid">
                <div>
                  <div className="px-editor__field">
                    <span className="px-editor__field-label">Display Name</span>
                    <div className="px-editor__field-value">{component.name}</div>
                  </div>
                  <div className="px-editor__field">
                    <span className="px-editor__field-label">Component ID</span>
                    <div className="px-editor__field-value">{detail.componentId}</div>
                  </div>
                  <div className="px-editor__field">
                    <span className="px-editor__field-label">Job Name</span>
                    <div className="px-editor__field-value">{detail.jobName}</div>
                  </div>
                </div>
                <div>
                  <div className="px-editor__field">
                    <span className="px-editor__field-label">Component Name</span>
                    <div className="px-editor__field-value">{detail.componentName}</div>
                  </div>
                  <div className="px-editor__field">
                    <span className="px-editor__field-label">Worker Type</span>
                    <div className="px-editor__field-value">{detail.workerType}</div>
                  </div>
                  <div className="px-editor__field">
                    <span className="px-editor__field-label">Description</span>
                    <div className="px-editor__field-value">{component.description}</div>
                  </div>
                </div>
              </div>
              <div className="px-editor__field">
                <span className="px-editor__field-label">Categories</span>
                <div className="px-editor__field-value">
                  {component.categories && component.categories.length > 0 ? component.categories.join(', ') : '—'}
                </div>
              </div>
            </section>

            <section>
              <h2 className="px-sim-detail__section-title">Schemas</h2>
              <div className="px-sim-detail__schema-tabs">
                <button
                  type="button"
                  className={`px-sim-detail__schema-tab${activeSchemaTab === 'input' ? ' px-sim-detail__schema-tab--active' : ''}`}
                  onClick={() => setActiveSchemaTab('input')}
                >
                  Input schema
                </button>
                <button
                  type="button"
                  className={`px-sim-detail__schema-tab${activeSchemaTab === 'output' ? ' px-sim-detail__schema-tab--active' : ''}`}
                  onClick={() => setActiveSchemaTab('output')}
                >
                  Output schema
                </button>
              </div>
              <SchemaCodeBlock yaml={buildSchemaYaml(activeSchemaTab === 'input' ? inputFields : outputFields)} />
            </section>
          </div>

          <div className="px-sim-detail__side">
            <h2 className="px-sim-detail__section-title">Configuration</h2>
            <div className="px-sim-detail__side-subtitle">{component.name}</div>
            {inputFields.map(field => (
              <ConfigField
                key={field.key}
                field={field}
                value={fieldValues[field.key]}
                onChange={handleFieldChange}
              />
            ))}
          </div>
        </div>
      </div>

      {confirmDeleteOpen && (
        <ConfirmDeleteModal
          title="Delete component"
          description={`Are you sure you want to delete "${component.name}"? This action cannot be undone.`}
          onCancel={() => setConfirmDeleteOpen(false)}
          onConfirm={onDelete}
        />
      )}
    </div>
  );
}
