import React, { useState, useMemo } from "react";
import {
  Lock, Unlock, RotateCcw, Copy, Check,
  ChevronDown, ChevronRight, CheckCircle2,
  Zap, FlaskConical, Anchor, Cpu, BarChart2
} from "lucide-react";

// ─── Constants ────────────────────────────────────────────────────────────────
const ANALYSIS_TYPES  = ["static structural", "modal", "buckling", "fatigue"];
const SOLVERS         = ["NX Nastran direct solver", "NX Nastran iterative", "NX Simcenter"];
const MAPPING_METHODS = ["interpolation from CFD mesh onto FEA mesh", "nearest-node projection", "RBF mapping"];
const GUST_TYPES      = ["regulatory gust load per EASA CS-25", "discrete gust (FAR 25.341)", "continuous turbulence"];
const MESH_FACES      = ["root_attachment", "winglet_skin", "tip_cap", "wake_region", "winglet_body", "far_field"];

const DEFAULTS = {
  // Load cases
  cruise_load_factor: 1.0,
  cruise_pressure_src: "from CFD Solver output (pressure field)",
  cruise_mapping: "interpolation from CFD mesh onto FEA mesh",
  gust_load_factor: 2.5,
  gust_type: "regulatory gust load per EASA CS-25",
  // Materials — CFRP
  cfrp_E11: 135,
  cfrp_E22: 10,
  cfrp_G12: 5,
  cfrp_nu:  0.3,
  cfrp_rho: 1600,
  cfrp_ys:  600,
  // Materials — Aluminium
  al_E:   70,
  al_nu:  0.33,
  al_rho: 2700,
  al_ys:  450,
  // BCs
  root_face:  "root_attachment",
  // Solver
  analysis_type: "static structural",
  solver:        "NX Nastran direct solver",
  conv_tol:      1e-4,
  // Outputs
  outputs: { von_mises: true, root_moment: true, tip_disp: true },
  root_moment_face: "root_attachment",
};

// ─── Serialisers ─────────────────────────────────────────────────────────────
function toYAML(cfg) {
  return `# FEA Solver Configuration
# Generated by Flux Pipelines — ${new Date().toISOString().slice(0, 10)}

load_cases:
  cruise:
    load_factor:    ${cfg.cruise_load_factor}g
    pressure_input: "${cfg.cruise_pressure_src}"
    mapping_method: "${cfg.cruise_mapping}"
  gust:
    load_factor: ${cfg.gust_load_factor}g
    type: "${cfg.gust_type}"

materials:
  CFRP_winglet_body:
    E11_GPa:        ${cfg.cfrp_E11}
    E22_GPa:        ${cfg.cfrp_E22}
    G12_GPa:        ${cfg.cfrp_G12}
    poisson_ratio:  ${cfg.cfrp_nu}
    density_kg_m3:  ${cfg.cfrp_rho}
    yield_MPa:      ${cfg.cfrp_ys}
  aluminium_root_bracket:
    E_GPa:          ${cfg.al_E}
    poisson_ratio:  ${cfg.al_nu}
    density_kg_m3:  ${cfg.al_rho}
    yield_MPa:      ${cfg.al_ys}

boundary_conditions:
  root_attachment:
    face:       ${cfg.root_face}
    constraint: fixed
  all_other:
    constraint: free

solver:
  analysis_type:         ${cfg.analysis_type}
  solver:                ${cfg.solver}
  convergence_tolerance: ${cfg.conv_tol}

outputs:
  max_von_mises_stress: ${cfg.outputs.von_mises}
  root_bending_moment:
    enabled: ${cfg.outputs.root_moment}
    face:    ${cfg.root_moment_face}
  tip_displacement:     ${cfg.outputs.tip_disp}
`;
}

function toAPIJson(cfg) {
  return JSON.stringify({
    load_cases: {
      cruise: { load_factor_g: cfg.cruise_load_factor, pressure_input: cfg.cruise_pressure_src, mapping: cfg.cruise_mapping },
      gust:   { load_factor_g: cfg.gust_load_factor,   type: cfg.gust_type },
    },
    materials: {
      CFRP: { E11: cfg.cfrp_E11, E22: cfg.cfrp_E22, G12: cfg.cfrp_G12, nu: cfg.cfrp_nu, rho: cfg.cfrp_rho, yield_MPa: cfg.cfrp_ys },
      aluminium: { E: cfg.al_E, nu: cfg.al_nu, rho: cfg.al_rho, yield_MPa: cfg.al_ys },
    },
    boundary_conditions: {
      root_attachment: { face: cfg.root_face, constraint: "fixed" },
      all_other: "free",
    },
    solver: { analysis_type: cfg.analysis_type, solver: cfg.solver, convergence: cfg.conv_tol },
    outputs: {
      max_von_mises: cfg.outputs.von_mises,
      root_bending_moment: cfg.outputs.root_moment ? { face: cfg.root_moment_face } : false,
      tip_displacement: cfg.outputs.tip_disp,
    },
  }, null, 2);
}

// ─── Sub-components ───────────────────────────────────────────────────────────
function SectionHeader({ icon: Icon, label }) {
  return (
    <div className="flex items-center gap-2 mb-3">
      <Icon size={13} className="text-[#aaabb1] shrink-0" />
      <span className="text-[11px] font-semibold uppercase tracking-widest text-[#aaabb1] opacity-60">
        {label}
      </span>
    </div>
  );
}

function Field({ label, hint, children, tight }) {
  return (
    <div className={tight ? "mb-2" : "mb-3"}>
      <div className="flex items-baseline justify-between mb-1">
        <label className="text-[11px] text-[#aaabb1]">{label}</label>
        {hint && <span className="text-[10px] text-[#aaabb1] opacity-40">{hint}</span>}
      </div>
      {children}
    </div>
  );
}

function NumInput({ value, onChange, min, max, step, disabled, suffix, sci, wide }) {
  const display = sci ? value.toExponential() : value;
  return (
    <div className="flex items-center gap-1.5">
      <input type={sci ? "text" : "number"} value={display}
        min={min} max={max} step={step} disabled={disabled}
        onChange={e => { const n = parseFloat(e.target.value); if (!isNaN(n)) onChange(n); }}
        className={`${wide ? "w-full" : "w-full"} bg-[#1d2024] border border-[#2e3035] rounded px-2.5 py-1.5 text-[12px] text-white font-mono
          focus:outline-none focus:border-[#aaabb1]/40 disabled:opacity-40 disabled:cursor-not-allowed
          [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none
          [&::-webkit-inner-spin-button]:appearance-none transition-colors`} />
      {suffix && <span className="text-[11px] text-[#aaabb1] opacity-40 shrink-0 font-mono whitespace-nowrap">{suffix}</span>}
    </div>
  );
}

function Select({ value, options, onChange, disabled }) {
  const [open, setOpen] = useState(false);
  return (
    <div className="relative">
      <button onClick={() => !disabled && setOpen(v => !v)} disabled={disabled}
        className="w-full flex items-center justify-between bg-[#1d2024] border border-[#2e3035]
          rounded px-2.5 py-1.5 text-[12px] text-white hover:border-[#aaabb1]/40
          disabled:opacity-40 disabled:cursor-not-allowed transition-colors text-left gap-2">
        <span className="truncate capitalize">{value}</span>
        <ChevronDown size={12} className={`text-[#aaabb1] transition-transform shrink-0 ${open ? "rotate-180" : ""}`} />
      </button>
      {open && (
        <div className="absolute z-50 top-full left-0 right-0 mt-1 bg-[#1d2024] border border-[#2e3035]
          rounded shadow-xl overflow-hidden">
          {options.map(opt => (
            <button key={opt} onClick={() => { onChange(opt); setOpen(false); }}
              className={`w-full text-left px-3 py-2 text-[12px] capitalize hover:bg-[#2e3035] transition-colors
                ${value === opt ? "text-white" : "text-[#aaabb1]"}`}>
              {opt}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

// Collapsible sub-section
function Subsection({ label, badge, defaultOpen = true, children }) {
  const [open, setOpen] = useState(defaultOpen);
  return (
    <div className="rounded border border-[#2e3035] overflow-hidden">
      <button onClick={() => setOpen(v => !v)}
        className="w-full flex items-center gap-2 px-3 py-2 bg-[#1d2024] hover:bg-[#2e3035] transition-colors text-left">
        {open
          ? <ChevronDown  size={11} className="text-[#aaabb1] opacity-50 shrink-0" />
          : <ChevronRight size={11} className="text-[#aaabb1] opacity-50 shrink-0" />}
        <span className="text-[12px] font-medium text-white">{label}</span>
        {badge && (
          <span className="ml-auto text-[10px] font-mono text-[#aaabb1] opacity-40 border border-[#2e3035] rounded px-1.5 py-0.5">
            {badge}
          </span>
        )}
      </button>
      {open && <div className="px-3 pt-2.5 pb-3 bg-[#111318] space-y-2">{children}</div>}
    </div>
  );
}

// Material property row: label + value + unit
function PropRow({ label, value, onChange, disabled, unit, min, max, step }) {
  return (
    <div className="flex items-center gap-2 py-1.5 border-b border-[#2e3035]/50 last:border-0">
      <span className="text-[11px] text-[#aaabb1] w-24 shrink-0">{label}</span>
      <div className="flex items-center gap-1.5 flex-1 min-w-0">
        <input type="number" value={value} min={min} max={max} step={step} disabled={disabled}
          onChange={e => { const n = parseFloat(e.target.value); if (!isNaN(n)) onChange(n); }}
          className="w-full bg-[#111318] border border-[#2e3035] rounded px-2 py-1 text-[12px] text-white font-mono
            focus:outline-none focus:border-[#aaabb1]/40 disabled:opacity-40 disabled:cursor-not-allowed
            [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none
            [&::-webkit-inner-spin-button]:appearance-none" />
        <span className="text-[10px] text-[#aaabb1] opacity-40 shrink-0 font-mono w-14 text-right">{unit}</span>
      </div>
    </div>
  );
}

// Output toggle row
function OutputRow({ id, label, desc, value, onChange, disabled, extra }) {
  return (
    <div className="py-2 border-b border-[#2e3035]/60 last:border-0">
      <button disabled={disabled} onClick={() => !disabled && onChange(!value)}
        className="flex items-start gap-3 w-full text-left disabled:cursor-not-allowed">
        <div className={`mt-0.5 w-3 h-3 rounded-sm border flex items-center justify-center shrink-0 transition-colors
          ${value ? "border-[#aaabb1]/50 bg-[#2e3035]" : "border-[#2e3035]"}`}>
          {value && (
            <svg width="7" height="5" viewBox="0 0 7 5" fill="none">
              <path d="M1 2.5L2.5 4L6 1" stroke="white" strokeWidth="1.2" strokeLinecap="round" strokeLinejoin="round"/>
            </svg>
          )}
        </div>
        <div className="flex-1 min-w-0">
          <span className="text-[12px] text-white block">{label}</span>
          <span className="text-[11px] text-[#aaabb1] opacity-50">{desc}</span>
        </div>
      </button>
      {value && extra && <div className="mt-2 pl-6">{extra}</div>}
    </div>
  );
}

function CodeBlock({ code, lang }) {
  const [copied, setCopied] = useState(false);
  return (
    <div className="rounded border border-[#2e3035] bg-[#0c0e13] overflow-hidden">
      <div className="flex items-center justify-between px-3 py-1.5 border-b border-[#2e3035]">
        <span className="text-[10px] text-[#aaabb1] opacity-40 font-mono">{lang}</span>
        <button onClick={() => { navigator.clipboard.writeText(code); setCopied(true); setTimeout(() => setCopied(false), 1500); }}
          className="text-[#aaabb1] hover:text-white transition-colors">
          {copied ? <Check size={12} className="text-green-400" /> : <Copy size={12} />}
        </button>
      </div>
      <pre className="p-3 text-[11px] font-mono text-[#aaabb1] overflow-x-auto whitespace-pre leading-relaxed">{code}</pre>
    </div>
  );
}

// ─── Main ─────────────────────────────────────────────────────────────────────
export default function FEASolverConfig({ locked = false, onClose }) {
  const [cfg, setCfg]         = useState(DEFAULTS);
  const [isLocked, setLocked] = useState(locked);
  const [tab, setTab]         = useState("ui");

  const set    = (k, v) => { if (!isLocked) setCfg(p => ({ ...p, [k]: v })); };
  const setOut = (k, v) => { if (!isLocked) setCfg(p => ({ ...p, outputs: { ...p.outputs, [k]: v } })); };
  const reset  = ()     => { if (!isLocked) setCfg(DEFAULTS); };

  const yaml    = useMemo(() => toYAML(cfg),   [cfg]);
  const apiJson = useMemo(() => toAPIJson(cfg), [cfg]);

  return (
    <div className="flex flex-col h-full bg-[#111318] text-white overflow-hidden select-none">

      {/* Header */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-[#2e3035] shrink-0">
        <div className="flex items-center gap-2">
          <Zap size={14} className="text-[#aaabb1]" />
          <span className="text-[13px] font-semibold">FEA Solver</span>
          <span className="text-[10px] text-[#aaabb1] opacity-50 bg-[#1d2024] px-1.5 py-0.5 rounded border border-[#2e3035]">NX</span>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={reset} disabled={isLocked}
            className="text-[#aaabb1] hover:text-white disabled:opacity-30 transition-colors" title="Reset">
            <RotateCcw size={13} />
          </button>
          <button onClick={() => setLocked(v => !v)} className="text-[#aaabb1] hover:text-white transition-colors">
            {isLocked ? <Lock size={13} /> : <Unlock size={13} />}
          </button>
          {onClose && (
            <button onClick={onClose} className="text-[#aaabb1] hover:text-white transition-colors ml-1" title="Close">
              <svg width="13" height="13" viewBox="0 0 13 13" fill="none"><path d="M2 2L11 11M11 2L2 11" stroke="currentColor" strokeWidth="1.4" strokeLinecap="round"/></svg>
            </button>
          )}
        </div>
      </div>

      {/* Tabs */}
      <div className="flex border-b border-[#2e3035] shrink-0">
        {["ui", "yaml"].map(t => (
          <button key={t} onClick={() => setTab(t)}
            className={`px-4 py-2 text-[11px] font-medium uppercase tracking-wider transition-colors border-b-2
              ${tab === t ? "border-white text-white" : "border-transparent text-[#aaabb1] hover:text-white"}`}>
            {t === "api" ? "API" : t.toUpperCase()}
          </button>
        ))}
      </div>

      {/* Body */}
      <div className="flex-1 overflow-y-auto px-4 py-4">
        {tab !== "ui" ? (
          <CodeBlock code={yaml} lang="yaml" />
        ) : (
          <div className="space-y-5">

            {/* ── Load cases ── */}
            <div>
              <SectionHeader icon={Zap} label="Load Cases" />
              <div className="flex flex-col gap-2">

                <Subsection label="Cruise" badge="1g">
                  <Field label="Load factor" tight>
                    <NumInput value={cfg.cruise_load_factor} onChange={v => set("cruise_load_factor", v)}
                      min={0.1} max={10} step={0.1} suffix="g" disabled={isLocked} />
                  </Field>
                  <Field label="Pressure input" tight>
                    <div className="flex items-center gap-2 px-3 py-2 rounded bg-[#1d2024] border border-[#2e3035]">
                      <div className="w-1.5 h-1.5 rounded-full bg-green-400 shrink-0" />
                      <span className="text-[11px] text-[#aaabb1] truncate">{cfg.cruise_pressure_src}</span>
                    </div>
                  </Field>
                  <Field label="Mapping method" tight>
                    <Select value={cfg.cruise_mapping} options={MAPPING_METHODS}
                      onChange={v => set("cruise_mapping", v)} disabled={isLocked} />
                  </Field>
                </Subsection>

                <Subsection label="Gust" badge="2.5g" defaultOpen={false}>
                  <Field label="Load factor" tight>
                    <NumInput value={cfg.gust_load_factor} onChange={v => set("gust_load_factor", v)}
                      min={1} max={10} step={0.1} suffix="g" disabled={isLocked} />
                  </Field>
                  <Field label="Type" tight>
                    <Select value={cfg.gust_type} options={GUST_TYPES}
                      onChange={v => set("gust_type", v)} disabled={isLocked} />
                  </Field>
                </Subsection>

              </div>
            </div>

            <div className="border-t border-[#2e3035]" />

            {/* ── Material properties ── */}
            <div>
              <SectionHeader icon={FlaskConical} label="Material Properties" />
              <div className="flex flex-col gap-2">

                <Subsection label="CFRP" badge="winglet body">
                  <div className="divide-y divide-[#2e3035]/50">
                    <PropRow label="E₁₁" value={cfg.cfrp_E11} onChange={v => set("cfrp_E11", v)} unit="GPa" min={1} max={500} step={1} disabled={isLocked} />
                    <PropRow label="E₂₂" value={cfg.cfrp_E22} onChange={v => set("cfrp_E22", v)} unit="GPa" min={1} max={100} step={0.5} disabled={isLocked} />
                    <PropRow label="G₁₂" value={cfg.cfrp_G12} onChange={v => set("cfrp_G12", v)} unit="GPa" min={0.1} max={50}  step={0.1} disabled={isLocked} />
                    <PropRow label="ν (Poisson)" value={cfg.cfrp_nu}  onChange={v => set("cfrp_nu",  v)} unit="—"   min={0.01} max={0.5} step={0.01} disabled={isLocked} />
                    <PropRow label="Density"     value={cfg.cfrp_rho} onChange={v => set("cfrp_rho", v)} unit="kg/m³" min={100} max={5000} step={10} disabled={isLocked} />
                    <PropRow label="Yield str."  value={cfg.cfrp_ys}  onChange={v => set("cfrp_ys",  v)} unit="MPa" min={10} max={3000} step={10} disabled={isLocked} />
                  </div>
                </Subsection>

                <Subsection label="Aluminium alloy" badge="root bracket" defaultOpen={false}>
                  <div className="divide-y divide-[#2e3035]/50">
                    <PropRow label="E"           value={cfg.al_E}   onChange={v => set("al_E",   v)} unit="GPa"   min={1}  max={300} step={1}    disabled={isLocked} />
                    <PropRow label="ν (Poisson)" value={cfg.al_nu}  onChange={v => set("al_nu",  v)} unit="—"     min={0.01} max={0.5} step={0.01} disabled={isLocked} />
                    <PropRow label="Density"     value={cfg.al_rho} onChange={v => set("al_rho", v)} unit="kg/m³" min={100} max={5000} step={10}  disabled={isLocked} />
                    <PropRow label="Yield str."  value={cfg.al_ys}  onChange={v => set("al_ys",  v)} unit="MPa"   min={10} max={2000} step={10}   disabled={isLocked} />
                  </div>
                </Subsection>

              </div>
            </div>

            <div className="border-t border-[#2e3035]" />

            {/* ── Boundary conditions ── */}
            <div>
              <SectionHeader icon={Anchor} label="Boundary Conditions" />
              <div className="rounded border border-[#2e3035] bg-[#1d2024] divide-y divide-[#2e3035]/60">
                <div className="flex items-center justify-between px-3 py-2.5 gap-3">
                  <div>
                    <div className="text-[12px] text-white">Root attachment</div>
                    <div className="text-[10px] text-[#aaabb1] opacity-50 mt-0.5">fixed constraint</div>
                  </div>
                  <div className="w-40">
                    <Select value={cfg.root_face} options={MESH_FACES}
                      onChange={v => set("root_face", v)} disabled={isLocked} />
                  </div>
                </div>
                <div className="flex items-center justify-between px-3 py-2.5">
                  <div>
                    <div className="text-[12px] text-white">All other faces</div>
                    <div className="text-[10px] text-[#aaabb1] opacity-50 mt-0.5">free</div>
                  </div>
                  <span className="text-[11px] text-[#aaabb1] opacity-40 border border-[#2e3035] rounded px-2 py-0.5">auto</span>
                </div>
              </div>
            </div>

            <div className="border-t border-[#2e3035]" />

            {/* ── Solver settings ── */}
            <div>
              <SectionHeader icon={Cpu} label="Solver Settings" />
              <Field label="Analysis type">
                <Select value={cfg.analysis_type} options={ANALYSIS_TYPES}
                  onChange={v => set("analysis_type", v)} disabled={isLocked} />
              </Field>
              <Field label="Solver">
                <Select value={cfg.solver} options={SOLVERS}
                  onChange={v => set("solver", v)} disabled={isLocked} />
              </Field>
              <Field label="Convergence tolerance">
                <NumInput value={cfg.conv_tol} onChange={v => set("conv_tol", v)} sci disabled={isLocked} />
              </Field>
            </div>

            <div className="border-t border-[#2e3035]" />

            {/* ── Scalar outputs ── */}
            <div>
              <SectionHeader icon={BarChart2} label="Scalar Outputs" />
              <div className="rounded border border-[#2e3035] bg-[#1d2024] px-3 divide-y divide-[#2e3035]/60">
                <OutputRow
                  label="Max von Mises stress"
                  desc="Peak across all elements"
                  value={cfg.outputs.von_mises}
                  onChange={v => setOut("von_mises", v)}
                  disabled={isLocked}
                />
                <OutputRow
                  label="Root bending moment"
                  desc="Integrated at root attachment face"
                  value={cfg.outputs.root_moment}
                  onChange={v => setOut("root_moment", v)}
                  disabled={isLocked}
                  extra={
                    <div className="flex items-center gap-2">
                      <span className="text-[11px] text-[#aaabb1] shrink-0">Face</span>
                      <Select value={cfg.root_moment_face} options={MESH_FACES}
                        onChange={v => set("root_moment_face", v)} disabled={isLocked} />
                    </div>
                  }
                />
                <OutputRow
                  label="Tip displacement"
                  desc="Max nodal displacement at winglet tip"
                  value={cfg.outputs.tip_disp}
                  onChange={v => setOut("tip_disp", v)}
                  disabled={isLocked}
                />
              </div>
            </div>

            {/* Status */}
            <div className="flex items-center gap-2 text-[11px] text-[#aaabb1] opacity-40 pt-1">
              <CheckCircle2 size={11} className="text-green-400 opacity-100" />
              <span className="text-green-400 opacity-100">Ready to run</span>
            </div>

          </div>
        )}
      </div>
    </div>
  );
}
