import { useMemo, useState } from 'react';
import { Search, Trash2, ChevronLeft, ChevronRight, ChevronsUpDown } from 'lucide-react';

import AppSidebar from './AppSidebar';
import ConfirmDeleteModal from './ConfirmDeleteModal';
import NewPipelineModal from './NewPipelineModal';
import PipelineEditorPage from './PipelineEditorPage';
import PipelineViewPage from './PipelineViewPage';
import { useAppData, generateId } from './AppDataContext';
import './PipelinesListPage.css';

const COLUMNS = [
  { id: 'name', label: 'Pipeline', sortable: true },
  { id: 'type', label: 'Type', sortable: true },
  { id: 'created', label: 'Created', sortable: true },
  { id: 'updated', label: 'Last updated', sortable: true },
  { id: 'actions', label: 'Actions', sortable: false },
];

const PAGE_SIZE_OPTIONS = [10, 25, 50, 100];
const TOTAL_PIPELINE_COUNT = 5031;

function getPageNumbers(currentPage, totalPages) {
  if (totalPages <= 7) return Array.from({ length: totalPages }, (_, i) => i + 1);
  if (currentPage <= 2) return [1, 2, 3, '...', totalPages - 1, totalPages];
  if (currentPage === 3) return [1, 2, 3, 4, '...', totalPages - 1, totalPages];
  if (currentPage >= totalPages - 1) return [1, 2, '...', totalPages - 2, totalPages - 1, totalPages];
  if (currentPage === totalPages - 2) return [1, '...', totalPages - 3, totalPages - 2, totalPages - 1, totalPages];
  return [1, '...', currentPage - 1, currentPage, currentPage + 1, '...', totalPages];
}

export default function PipelinesListPage({ onNavigate, userName }) {
  const { pipelines, setPipelines } = useAppData();
  const [search, setSearch] = useState('');
  const [sort, setSort] = useState({ column: null, ascending: true });
  const [pageSize, setPageSize] = useState(50);
  const [currentPage, setCurrentPage] = useState(2);
  const [pendingDelete, setPendingDelete] = useState(null);
  const [newPipelineOpen, setNewPipelineOpen] = useState(false);
  const [openPipeline, setOpenPipeline] = useState(null);
  const [editingCanvas, setEditingCanvas] = useState(false);
  const [autoRunOnOpen, setAutoRunOnOpen] = useState(false);

  const totalPages = Math.max(1, Math.ceil(TOTAL_PIPELINE_COUNT / pageSize));
  const pageNumbers = useMemo(() => getPageNumbers(currentPage, totalPages), [currentPage, totalPages]);

  const visiblePipelines = useMemo(() => {
    let rows = pipelines;
    if (search.trim()) {
      const query = search.trim().toLowerCase();
      rows = rows.filter(p => p.name.toLowerCase().includes(query));
    }
    if (sort.column) {
      rows = [...rows].sort((a, b) => {
        const aIsNew = a.updated === 'Just now';
        const bIsNew = b.updated === 'Just now';
        if (aIsNew !== bIsNew) return aIsNew ? -1 : 1;
        const av = (a[sort.column] || '').toLowerCase();
        const bv = (b[sort.column] || '').toLowerCase();
        if (av < bv) return sort.ascending ? -1 : 1;
        if (av > bv) return sort.ascending ? 1 : -1;
        return 0;
      });
    }
    return rows;
  }, [pipelines, search, sort]);

  function handleSort(columnId) {
    setSort(prev => ({
      column: columnId,
      ascending: prev.column === columnId ? !prev.ascending : true,
    }));
  }

  function handleDeleteClick(pipeline, e) {
    e.stopPropagation();
    setPendingDelete(pipeline);
  }

  function confirmDelete() {
    setPipelines(prev => prev.filter(p => p.id !== pendingDelete.id));
    setOpenPipeline(prev => {
      if (prev && prev.id === pendingDelete.id) {
        setEditingCanvas(false);
        return null;
      }
      return prev;
    });
    setPendingDelete(null);
  }

  function goToPage(page) {
    setCurrentPage(Math.min(totalPages, Math.max(1, page)));
  }

  function handleSaveCanvas(canvasNodes) {
    setPipelines(prev => prev.map(p => (p.id === openPipeline.id ? { ...p, canvasNodes } : p)));
    setOpenPipeline(prev => (prev ? { ...prev, canvasNodes } : prev));
  }

  function handleRunRecorded(run) {
    setPipelines(prev => prev.map(p => (p.id === openPipeline.id ? { ...p, runHistory: [run, ...(p.runHistory || [])] } : p)));
    setOpenPipeline(prev => (prev ? { ...prev, runHistory: [run, ...(prev.runHistory || [])] } : prev));
  }

  function handleSaveAndRun(canvasNodes) {
    handleSaveCanvas(canvasNodes);
    setEditingCanvas(false);
    setAutoRunOnOpen(true);
  }

  function handleCreatePipeline({ name, description }) {
    const now = 'Just now';
    const pipeline = {
      id: generateId(),
      name,
      description,
      type: 'AI',
      created: now,
      updated: now,
    };
    setPipelines(prev => [pipeline, ...prev]);
    setNewPipelineOpen(false);
    setOpenPipeline(pipeline);
    setEditingCanvas(true);
    setCurrentPage(1);
  }

  if (openPipeline) {
    return (
      <>
        {editingCanvas ? (
          <PipelineEditorPage
            pipeline={openPipeline}
            userName={userName}
            onNavigate={onNavigate}
            onBack={() => setEditingCanvas(false)}
            onDeletePipeline={() => setPendingDelete(openPipeline)}
            onSaveCanvas={handleSaveCanvas}
            onSaveAndRun={handleSaveAndRun}
          />
        ) : (
          <PipelineViewPage
            pipeline={openPipeline}
            userName={userName}
            onNavigate={onNavigate}
            onBack={() => setOpenPipeline(null)}
            onEdit={() => setEditingCanvas(true)}
            autoRun={autoRunOnOpen}
            onAutoRunConsumed={() => setAutoRunOnOpen(false)}
            onDeletePipeline={() => setPendingDelete(openPipeline)}
            onRunRecorded={handleRunRecorded}
          />
        )}
        {pendingDelete && (
          <ConfirmDeleteModal
            title="Delete pipeline"
            description={`Are you sure you want to delete "${pendingDelete.name}"? This action cannot be undone.`}
            onCancel={() => setPendingDelete(null)}
            onConfirm={confirmDelete}
          />
        )}
      </>
    );
  }

  return (
    <div className="px-pipelines">
      <AppSidebar activeItem="pipelines" onNavigate={onNavigate} userName={userName} />

      <div className="px-pipelines__main">
        <header className="px-pipelines__header">
          <h1 className="px-pipelines__title">Pipelines</h1>
          <button type="button" className="px-pipelines__new-btn" onClick={() => setNewPipelineOpen(true)}>
            New pipeline
          </button>
        </header>

        <div className="px-pipelines__content">
          <div className="px-pipelines__toolbar">
            <label className="px-search" style={{ marginLeft: 'auto' }}>
              <Search size={16} />
              <input
                type="text"
                placeholder="Search pipeline"
                value={search}
                onChange={e => { setSearch(e.target.value); setCurrentPage(1); }}
              />
            </label>
          </div>

          <div className="px-table-scroll">
            <table className="px-table">
              <thead>
                <tr>
                  {COLUMNS.map(col => (
                    <th key={col.id}>
                      {col.sortable ? (
                        <button type="button" className="px-sort-th" onClick={() => handleSort(col.id)}>
                          {col.label}
                          <ChevronsUpDown size={14} />
                        </button>
                      ) : col.label}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {visiblePipelines.map(pipeline => {
                  return (
                  <tr
                    key={pipeline.id}
                    onClick={() => { setOpenPipeline(pipeline); setEditingCanvas(false); }}
                  >
                    <td>
                      <div className="px-table__name">
                        <span>{pipeline.name}</span>
                        <span className="px-table__desc">{pipeline.description || ''}</span>
                      </div>
                    </td>
                    <td><span className="px-badge">{pipeline.type}</span></td>
                    <td>{pipeline.created}</td>
                    <td>{pipeline.updated}</td>
                    <td>
                      <div className="px-table__actions">
                        <button
                          type="button"
                          className="px-icon-btn"
                          title={`Delete ${pipeline.name}`}
                          aria-label={`Delete ${pipeline.name}`}
                          onClick={e => handleDeleteClick(pipeline, e)}
                        >
                          <Trash2 size={16} />
                        </button>
                      </div>
                    </td>
                  </tr>
                  );
                })}
              </tbody>
            </table>
            {visiblePipelines.length === 0 && (
              <div className="px-empty-state">No pipelines match your search.</div>
            )}
          </div>

          <div className="px-pagination">
            <div className="px-pagination__rows">
              <select value={pageSize} onChange={e => { setPageSize(Number(e.target.value)); setCurrentPage(1); }}>
                {PAGE_SIZE_OPTIONS.map(size => <option key={size} value={size}>{size}</option>)}
              </select>
              Items per page
            </div>

            <div className="px-pagination__pages">
              <button type="button" className="px-page-btn" disabled={currentPage === 1} onClick={() => goToPage(currentPage - 1)}>
                <ChevronLeft size={14} /> Prev
              </button>
              {pageNumbers.map((page, index) =>
                page === '...' ? (
                  <span key={`ellipsis-${index}`} className="px-page-ellipsis">•••</span>
                ) : (
                  <button
                    key={page}
                    type="button"
                    className={`px-page-btn${page === currentPage ? ' px-page-btn--active' : ''}`}
                    onClick={() => goToPage(page)}
                  >
                    {page}
                  </button>
                )
              )}
              <button type="button" className="px-page-btn" disabled={currentPage === totalPages} onClick={() => goToPage(currentPage + 1)}>
                Next <ChevronRight size={14} />
              </button>
            </div>
          </div>
        </div>
      </div>

      {pendingDelete && (
        <ConfirmDeleteModal
          title="Delete pipeline"
          description={`Are you sure you want to delete "${pendingDelete.name}"? This action cannot be undone.`}
          onCancel={() => setPendingDelete(null)}
          onConfirm={confirmDelete}
        />
      )}

      {newPipelineOpen && (
        <NewPipelineModal
          onCancel={() => setNewPipelineOpen(false)}
          onCreate={handleCreatePipeline}
        />
      )}
    </div>
  );
}
