// ─── YAML serialiser ─────────────────────────────────────────────────────────
function toYAML(cfg) {
  const r = cfg.mesh_regions;
  return `# k-ω SST Turbulence Model Configuration
# Generated by Flux Pipelines — ${new Date().toISOString().slice(0, 10)}

model: k_omega_sst
compatibility: "StarCCM+ 2310+"

constants:
  sigma_k1: ${cfg.sigma_k1.toFixed(3)}
  sigma_k2: ${cfg.sigma_k2.toFixed(3)}
  sigma_w1: ${cfg.sigma_w1.toFixed(3)}
  sigma_w2: ${cfg.sigma_w2.toFixed(3)}
  beta1: ${cfg.beta1.toFixed(4)}
  beta2: ${cfg.beta2.toFixed(4)}
  beta_star: ${cfg.beta_star.toFixed(4)}
  a1: ${cfg.a1.toFixed(3)}

wall_treatment:
  type: ${cfg.wall_treatment}${cfg.wall_treatment === "low-re" ? `\n  y_plus_target: ${cfg.y_plus_target.toFixed(1)}` : ""}

convergence:
  max_iterations: ${cfg.max_iterations}
  residual_tol: ${cfg.residual_tol.toExponential(1)}

mesh_regions:${r.length === 0 ? " []" : "\n" + r.map(x => `  - ${x}`).join("\n")}
`;
}

// ─── API JSON serialiser ──────────────────────────────────────────────────────
function toAPIJson(cfg) {
  const payload = {
    model: "k_omega_sst",
    constants: {
      sigma_k1: cfg.sigma_k1,
      sigma_k2: cfg.sigma_k2,
      sigma_w1: cfg.sigma_w1,
      sigma_w2: cfg.sigma_w2,
      beta1: cfg.beta1,
      beta2: cfg.beta2,
      beta_star: cfg.beta_star,
      a1: cfg.a1,
    },
    wall_treatment: {
      type: cfg.wall_treatment,
      ...(cfg.wall_treatment === "low-re" ? { y_plus_target: cfg.y_plus_target } : {}),
    },
    convergence: {
      max_iterations: cfg.max_iterations,
      residual_tol: cfg.residual_tol,
    },
    mesh_regions: cfg.mesh_regions,
  };
  return JSON.stringify(payload, null, 2);
}

