function SliderRow({ id, meta, value, defaultVal, onChange, disabled }) {
  const pct = ((value - meta.min) / (meta.max - meta.min)) * 100;
  const modified = Math.abs(value - defaultVal) > 1e-9;
  return (
    <div className="group flex items-center gap-3 px-3 py-2 rounded-lg hover:bg-slate-800/60 transition-colors">
      {/* label */}
      <div className="w-16 shrink-0">
        <span className="text-xs font-mono text-slate-300">{meta.label}</span>
        {modified && (
          <span className="ml-1 inline-block w-1.5 h-1.5 rounded-full bg-indigo-400 align-middle" title="Modified" />
        )}
      </div>
      {/* slider */}
      <div className="flex-1 relative h-5 flex items-center">
        <div className="absolute inset-x-0 h-[3px] rounded-full bg-slate-700" />
        <div
          className="absolute left-0 h-[3px] rounded-full bg-indigo-500"
          style={{ width: `${pct}%` }}
        />
        <input
          type="range"
          min={meta.min} max={meta.max} step={meta.step}
          value={value}
          disabled={disabled}
          onChange={e => onChange(id, parseFloat(e.target.value))}
          className="absolute inset-x-0 w-full opacity-0 cursor-pointer h-5 disabled:cursor-not-allowed"
        />
        {/* thumb */}
        <div
          className={`absolute w-3 h-3 rounded-full border-2 border-indigo-400 bg-slate-900 shadow ${disabled ? "opacity-40" : ""}`}
          style={{ left: `calc(${pct}% - 6px)` }}
        />
      </div>
      {/* numeric input */}
      <input
        type="number"
        value={value}
        min={meta.min} max={meta.max} step={meta.step}
        disabled={disabled}
        onChange={e => {
          const v = parseFloat(e.target.value);
          if (!isNaN(v)) onChange(id, v);
        }}
        className="w-20 shrink-0 bg-slate-800 border border-slate-700 rounded px-2 py-0.5 text-xs font-mono text-slate-200 text-right focus:outline-none focus:border-indigo-500 disabled:opacity-40"
      />
    </div>
  );
}

