import { useState } from 'react';
import { X, ChevronDown, Search } from 'lucide-react';
import './ConfirmDeleteModal.css';
import './NewPipelineModal.css';
import './StartNotebookModal.css';
import { COMPUTE_PROFILES } from './computeProfiles';

export default function NewComponentModal({ onCancel, onCreate, existingNames = [], cloneFrom = null, cloneCandidates = [] }) {
  const [startMode, setStartMode] = useState('scratch');
  const [cloneSearchText, setCloneSearchText] = useState('');
  const [selectedCloneId, setSelectedCloneId] = useState(null);
  const [cloneMenuOpen, setCloneMenuOpen] = useState(false);
  const [name, setName] = useState(cloneFrom ? `${cloneFrom.name} (copy)` : '');
  const [description, setDescription] = useState(cloneFrom?.description || '');
  const [computeProfile, setComputeProfile] = useState(cloneFrom?.computeProfile || '');

  const offerClonePicker = !cloneFrom && cloneCandidates.length > 0;
  const selectedCandidate = cloneCandidates.find(c => c.id === selectedCloneId) || null;
  const effectiveClone = cloneFrom || (startMode === 'clone' ? selectedCandidate : null);
  const filteredCloneCandidates = cloneCandidates.filter(c => (
    c.name.toLowerCase().includes(cloneSearchText.trim().toLowerCase())
  ));

  const trimmedName = name.trim();
  const isDuplicate = trimmedName !== '' && existingNames.some(n => n.toLowerCase() === trimmedName.toLowerCase());
  const canCreate = trimmedName && computeProfile && !isDuplicate && (startMode !== 'clone' || selectedCandidate);
  const profileOptions = cloneFrom?.computeProfile && !COMPUTE_PROFILES.includes(cloneFrom.computeProfile)
    ? [cloneFrom.computeProfile, ...COMPUTE_PROFILES]
    : COMPUTE_PROFILES;

  function handleSelectCloneCandidate(candidate) {
    setSelectedCloneId(candidate.id);
    setCloneSearchText(candidate.name);
    setCloneMenuOpen(false);
    setName(`${candidate.name} (copy)`);
    setDescription(candidate.description || '');
    setComputeProfile(candidate.computeProfile || '');
  }

  function handleCloneSearchChange(value) {
    setCloneSearchText(value);
    setSelectedCloneId(null);
    setCloneMenuOpen(true);
  }

  function handleCreate() {
    if (!canCreate) return;
    onCreate({ name: trimmedName, description: description.trim(), computeProfile, code: effectiveClone?.code });
  }

  return (
    <div className="px-modal-overlay" onClick={onCancel}>
      <div className="px-modal px-modal--form" onClick={e => e.stopPropagation()}>
        <button type="button" className="px-modal__close" aria-label="Close" onClick={onCancel}>
          <X size={18} />
        </button>
        <h2 className="px-modal__title">{cloneFrom ? 'Clone component' : 'New component'}</h2>
        <p className="px-modal__subtitle">
          {cloneFrom
            ? `Create an editable copy of "${cloneFrom.name}".`
            : 'Start from an existing component, or build one from scratch.'}
        </p>

        {offerClonePicker && (
          <div className="px-field">
            <label className="px-field__label">Start from</label>
            <div className="px-radio-row">
              <label className="px-radio-option">
                <input
                  type="radio"
                  name="start-mode"
                  checked={startMode === 'scratch'}
                  onChange={() => setStartMode('scratch')}
                />
                Start from scratch
              </label>
              <label className="px-radio-option">
                <input
                  type="radio"
                  name="start-mode"
                  checked={startMode === 'clone'}
                  onChange={() => setStartMode('clone')}
                />
                Clone an existing component
              </label>
            </div>
            {startMode === 'clone' && (
              <div className="px-clone-search" style={{ marginTop: 10 }}>
                <div className="px-clone-search__input-wrap">
                  <Search size={14} className="px-clone-search__icon" />
                  <input
                    type="text"
                    className="px-clone-search__input"
                    placeholder="Search components to clone"
                    autoComplete="off"
                    value={cloneSearchText}
                    onChange={e => handleCloneSearchChange(e.target.value)}
                    onFocus={() => setCloneMenuOpen(true)}
                  />
                </div>
                {cloneMenuOpen && (
                  <>
                    <div className="px-menu-overlay" onClick={() => setCloneMenuOpen(false)} />
                    <div className="px-clone-search__menu">
                      {filteredCloneCandidates.length === 0 ? (
                        <div className="px-clone-search__empty">No components match</div>
                      ) : filteredCloneCandidates.map(c => (
                        <button
                          key={c.id}
                          type="button"
                          className={`px-clone-search__item${c.id === selectedCloneId ? ' px-clone-search__item--active' : ''}`}
                          onClick={() => handleSelectCloneCandidate(c)}
                        >
                          {c.name}
                        </button>
                      ))}
                    </div>
                  </>
                )}
              </div>
            )}
          </div>
        )}

        <div className="px-field">
          <label className="px-field__label" htmlFor="component-name">
            Component name <span className="px-field__required">*</span>
          </label>
          <input
            id="component-name"
            type="text"
            className={`px-field__input${isDuplicate ? ' px-field__input--error' : ''}`}
            placeholder="Enter component name"
            value={name}
            onChange={e => setName(e.target.value)}
            aria-invalid={isDuplicate}
          />
          {isDuplicate && (
            <p className="px-field__error">A component named "{trimmedName}" already exists. Choose a different name.</p>
          )}
        </div>

        <div className="px-field">
          <label className="px-field__label" htmlFor="component-description">Description</label>
          <textarea
            id="component-description"
            className="px-field__textarea"
            placeholder="Enter a description"
            value={description}
            onChange={e => setDescription(e.target.value)}
          />
        </div>

        <div className="px-field">
          <label className="px-field__label" htmlFor="component-compute-profile">
            Compute profile <span className="px-field__required">*</span>
          </label>
          <div className="px-notebook-select-wrap">
            <select
              id="component-compute-profile"
              className="px-notebook-select"
              value={computeProfile}
              onChange={e => setComputeProfile(e.target.value)}
              required
            >
              <option value="" disabled>Select compute profile</option>
              {profileOptions.map(option => (
                <option key={option} value={option}>{option}</option>
              ))}
            </select>
            <ChevronDown size={16} className="px-notebook-select-chevron" />
          </div>
        </div>

        <div className="px-modal__actions">
          <button type="button" className="px-modal__btn px-modal__btn--cancel" onClick={onCancel}>
            Cancel
          </button>
          <button
            type="button"
            className="px-modal__btn px-modal__btn--primary"
            disabled={!canCreate}
            onClick={handleCreate}
          >
            {effectiveClone ? 'Clone component' : 'Create component'}
          </button>
        </div>
      </div>
    </div>
  );
}
