import { useCallback, useLayoutEffect, useRef, useState } from 'react';

export function useNodeConnectors(nodeIds) {
  const containerRef = useRef(null);
  const nodeElsRef = useRef({});
  const [connectors, setConnectors] = useState([]);

  const setNodeRef = useCallback(id => el => {
    if (el) nodeElsRef.current[id] = el;
    else delete nodeElsRef.current[id];
  }, []);

  useLayoutEffect(() => {
    function measure() {
      const container = containerRef.current;
      if (!container) return;
      const containerRect = container.getBoundingClientRect();
      const rects = nodeIds.map(id => {
        const el = nodeElsRef.current[id];
        if (!el) return null;
        const r = el.getBoundingClientRect();
        return {
          id,
          top: r.top - containerRect.top,
          left: r.left - containerRect.left,
          right: r.right - containerRect.left,
          bottom: r.bottom - containerRect.top,
          centerX: r.left - containerRect.left + r.width / 2,
          centerY: r.top - containerRect.top + r.height / 2,
        };
      });
      const next = [];
      for (let i = 1; i < rects.length; i++) {
        const from = rects[i - 1];
        const to = rects[i];
        if (!from || !to) continue;
        next.push({ key: `${from.id}-${to.id}`, from, to, sameRow: Math.abs(from.centerY - to.centerY) < 4 });
      }
      setConnectors(next);
    }

    measure();
    const ro = new ResizeObserver(measure);
    if (containerRef.current) ro.observe(containerRef.current);
    window.addEventListener('resize', measure);
    return () => {
      ro.disconnect();
      window.removeEventListener('resize', measure);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [nodeIds.join('|')]);

  return { containerRef, setNodeRef, connectors };
}
