import { useEffect, useState } from 'react';
import { PanelLeftClose, PanelLeftOpen, Info } from 'lucide-react';
import './AppSidebar.css';

import { ReactComponent as WordmarkIcon } from './assets/pipelines-sidebar/wordmark.svg';
import { ReactComponent as LogoMarkIcon } from './assets/pipelines-sidebar/logo-mark.svg';
import { ReactComponent as HomeNavIcon } from './assets/pipelines-sidebar/nav-home.svg';
import { ReactComponent as VaultNavIcon } from './assets/pipelines-sidebar/nav-vault.svg';
import { ReactComponent as PipelinesNavIcon } from './assets/pipelines-sidebar/nav-pipelines.svg';
import { ReactComponent as RunsNavIcon } from './assets/pipelines-sidebar/nav-runs.svg';
import { ReactComponent as ComponentsNavIcon } from './assets/pipelines-sidebar/nav-components.svg';
import { ReactComponent as ModelCatalogNavIcon } from './assets/pipelines-sidebar/nav-modelcatalog.svg';
import { ReactComponent as EndpointsNavIcon } from './assets/pipelines-sidebar/nav-endpoints.svg';
import { ReactComponent as MlFlowNavIcon } from './assets/pipelines-sidebar/nav-mlflow.svg';
import { ReactComponent as DesignWorkbenchNavIcon } from './assets/pipelines-sidebar/nav-designworkbench.svg';
import { ReactComponent as OptimizerNavIcon } from './assets/pipelines-sidebar/nav-optimizer.svg';

const NAV_ITEMS = [
  { id: 'home', label: 'Home', Icon: HomeNavIcon },
  { id: 'vault', label: 'Vault', Icon: VaultNavIcon },
  { id: 'components', label: 'Components', Icon: ComponentsNavIcon, enabled: true },
  { id: 'pipelines', label: 'Pipelines', Icon: PipelinesNavIcon, enabled: true },
  { id: 'runs', label: 'Runs', Icon: RunsNavIcon, enabled: true },
  { id: 'model-catalog', label: 'Model catalog', Icon: ModelCatalogNavIcon },
  { id: 'endpoints', label: 'Endpoints', Icon: EndpointsNavIcon },
  { id: 'ml-flow', label: 'ML Flow', Icon: MlFlowNavIcon },
  { id: 'design-workbench', label: 'Design Workbench', Icon: DesignWorkbenchNavIcon },
  { id: 'optimizer', label: 'Optimizer', Icon: OptimizerNavIcon },
];

function getInitial(name) {
  return name?.trim()?.[0]?.toUpperCase() ?? '?';
}

export default function AppSidebar({ activeItem, onNavigate, userName, showLogo = true, defaultCollapsed = false }) {
  const [collapsed, setCollapsed] = useState(defaultCollapsed);

  useEffect(() => {
    document.documentElement.style.setProperty('--px-sidebar-width', collapsed ? '72px' : '248px');
  }, [collapsed]);

  return (
    <aside className={`px-sidebar${collapsed ? ' px-sidebar--collapsed' : ''}`}>
      <div>
        {showLogo && (
          <div className="px-sidebar__logo">
            {collapsed ? <LogoMarkIcon /> : <WordmarkIcon />}
          </div>
        )}
        <nav className="px-sidebar__nav">
          {NAV_ITEMS.map(({ id, label, Icon, enabled }) => (
            <button
              key={id}
              type="button"
              disabled={!enabled}
              title={collapsed ? label : undefined}
              className={`px-sidebar__item${id === activeItem ? ' px-sidebar__item--active' : ''}${!enabled ? ' px-sidebar__item--disabled' : ''}`}
              onClick={() => onNavigate?.(id)}
            >
              <span className="px-sidebar__item-icon"><Icon /></span>
              {!collapsed && label}
            </button>
          ))}
        </nav>
      </div>

      <div className="px-sidebar__bottom">
        <button
          type="button"
          title={collapsed ? 'Expand' : undefined}
          className="px-sidebar__item"
          onClick={() => setCollapsed(c => !c)}
        >
          <span className="px-sidebar__item-icon">
            {collapsed ? <PanelLeftOpen size={18} /> : <PanelLeftClose size={18} />}
          </span>
          {!collapsed && 'Collapse'}
        </button>
        <a
          href="https://alpha.platform.physicsx.ai/platform-documentation/"
          target="_blank"
          rel="noopener noreferrer"
          title="Documentation"
          className="px-sidebar__item"
        >
          <span className="px-sidebar__item-icon"><Info size={18} /></span>
          {!collapsed && 'Documentation'}
        </a>
        <div className="px-sidebar__user" title={collapsed ? userName : undefined}>
          <div className="px-sidebar__avatar">{getInitial(userName)}</div>
          {!collapsed && <span className="px-sidebar__user-name">{userName}</span>}
        </div>
      </div>
    </aside>
  );
}
